<?php
declare(strict_types=1);require __DIR__.'/lib.php';
// CSS, JS and built-in pictures are served by this same file as separate, cached responses
// (index.php?asset=…&v=…). The page itself stays uncached but is now small; the heavy parts are
// downloaded once per deploy instead of on every reload. v changes whenever index.php is updated.
const MB_ASSETS = ['app.css'=>'text/css; charset=utf-8','app.js'=>'text/javascript; charset=utf-8','ref.webp'=>'image/webp','example.webp'=>'image/webp','kukla.webp'=>'image/webp','hero.jpg'=>'image/jpeg'];
define('MB_ASSET_V', substr(hash('sha256', (string)filemtime(__FILE__).'|'.(string)filesize(__FILE__)), 0, 12));
function mb_asset_url(string $name): string { return 'index.php?asset='.$name.'&v='.MB_ASSET_V; }
if (isset($_GET['asset'])) {
 $name = (string)$_GET['asset'];
 if (!isset(MB_ASSETS[$name])) { http_response_code(404); exit; }
 if (!is_file(__DIR__.'/.memorybox-config.php')) { http_response_code(404); exit; }
 session_cache_limiter(''); // no "no-cache" headers from session_start for cacheable files
 $c = config(); session_begin($c); $signedIn = !empty($_SESSION['uid']); session_write_close();
 header('X-Content-Type-Options: nosniff');
 if (!$signedIn) { header('Cache-Control: no-store'); http_response_code(403); exit; }
 $etag = '"'.MB_ASSET_V.'-'.$name.'"';
 $fresh = ($_GET['v'] ?? '') === MB_ASSET_V;
 header('Cache-Control: '.($fresh ? 'private, max-age=31536000, immutable' : 'private, no-cache'));
 header('ETag: '.$etag);
 if (trim((string)($_SERVER['HTTP_IF_NONE_MATCH'] ?? '')) === $etag) { http_response_code(304); exit; }
 header('Content-Type: '.MB_ASSETS[$name]);
 if (str_starts_with(MB_ASSETS[$name], 'text/') && extension_loaded('zlib') && !ini_get('zlib.output_compression')) ob_start('ob_gzhandler');
 mb_asset_body($name);
 exit;
}
guard_headers();
header('Pragma: no-cache');header('Expires: 0');
// One canonical document URL for directory links and explicit editor links.
$entryPath=parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_PATH);
if(is_string($entryPath)&&str_ends_with($entryPath,'/')){
 $query=$_SERVER['QUERY_STRING']??'';header('Location: index.php'.($query!==''?'?'.$query:''),true,302);exit;
}

if(!is_file(__DIR__.'/.memorybox-config.php')){header('Location: setup.php');exit;}
$c=config();session_begin($c);if(empty($_SESSION['uid'])){header('Location: '.(is_file(__DIR__.'/index.html')?'index.html':'login.php'));exit;}session_write_close();
if(extension_loaded('zlib')&&!ini_get('zlib.output_compression'))ob_start('ob_gzhandler');
?>
