// Asset bodies. Called only for index.php?asset=… requests (see the top of this file).
function mb_asset_body(string $name): void {
 if ($name === 'app.css') { ?>
/* Memorybox atelier — one stylesheet. Tokens first, then base, components, steps, dialogs, states, phone. */
:root{
 --paper:#faf7f3;--surface:#fff;--surface-2:#f5f0ea;--surface-3:#efe7e0;
 --ink:#2b2129;--ink-2:#5d5159;--ink-3:#8b7f87;--line:#ebe3dc;--line-2:#ddd1c9;
 --plum:#6d2e58;--plum-2:#55203f;--plum-soft:#f5eaf0;--plum-line:#e3cbd8;--rose:#ecd6de;--gold:#b48a52;--gold-soft:#f6eddf;
 --ok:#4b7a5f;--ok-soft:#eaf2ec;--warn:#946426;--warn-soft:#fbf1e1;--danger:#a3443b;--danger-soft:#fbecE8;
 --r-lg:22px;--r-md:14px;--r-sm:10px;
 --shadow-1:0 1px 2px #2b21290a;--shadow-2:0 1px 2px #2b21290a,0 10px 30px #2b21290d;--shadow-3:0 2px 4px #2b21290d,0 24px 60px #2b21291f;
 --display:"Cormorant Garamond",Georgia,"Times New Roman",serif;--ui:"Manrope",-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
 /* aliases used by inline styles and older markup */
 --accent:var(--plum);--accent-dark:var(--plum-2);--accent-soft:var(--plum-soft);--muted:var(--ink-3);--fg:var(--ink);--bg:var(--paper);--card:var(--surface);--green:var(--ok);--green-soft:var(--ok-soft);
 font-family:var(--ui);color-scheme:light;font-synthesis:none;-webkit-font-smoothing:antialiased
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;overflow-x:clip;max-width:100%}
body{margin:0;overflow-x:clip;max-width:100%;background:var(--paper);color:var(--ink);font-size:15px;line-height:1.6;-webkit-text-size-adjust:100%}
[hidden]{display:none!important}
p{margin:0;color:var(--ink-2)}
h1,h2,h3,h4{margin:0;color:var(--ink);line-height:1.2}
h1,h2{font-family:var(--display);font-weight:500;letter-spacing:-.02em}
h3{font-size:16px;font-weight:700;letter-spacing:-.01em}
h4{font-size:14px;font-weight:700}
button,input,select{font:inherit}
button,label.btn2,.drop,.photo-upload,a{-webkit-tap-highlight-color:transparent;touch-action:manipulation}
::selection{background:var(--rose)}
:focus-visible{outline:2px solid var(--plum);outline-offset:3px;border-radius:6px}

/* ---------- Buttons ---------- */
button,.btn2{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:46px;padding:11px 20px;border-radius:12px;border:1px solid transparent;background:var(--plum);color:#fff;font-size:14px;font-weight:600;line-height:1.3;text-align:center;text-decoration:none;cursor:pointer;max-width:100%;transition:background-color .18s,border-color .18s,color .18s,box-shadow .18s,transform .18s}
button:disabled{opacity:.45;cursor:not-allowed}
button:active:not(:disabled),label.btn2:active{transform:translateY(1px)}
.primary{background:var(--plum);border-color:var(--plum);color:#fff;box-shadow:0 1px 2px #55203f26,0 6px 16px #6d2e5824}
.primary:hover:not(:disabled){background:var(--plum-2);border-color:var(--plum-2)}
.button-secondary,.btn2{background:var(--surface);border-color:var(--line-2);color:var(--plum)}
.button-secondary:hover:not(:disabled),.btn2:hover{border-color:var(--plum-line);background:var(--plum-soft)}
.button-light{background:var(--surface-2);border-color:transparent;color:var(--ink-2)}
.button-light:hover:not(:disabled){background:var(--surface-3)}
.button-icon{width:44px;min-width:44px;height:44px;padding:0;background:var(--surface);border:1px solid var(--line-2);color:var(--ink-2);font-size:22px;border-radius:12px}
.button-icon:hover:not(:disabled){color:var(--plum);border-color:var(--plum-line)}
.text-button{background:none;border:0;color:var(--plum);padding:8px 2px;min-height:40px;font-size:13px;font-weight:600;box-shadow:none}
.text-button:hover:not(:disabled){color:var(--plum-2);text-decoration:underline;text-underline-offset:4px}
.danger,.text-button.danger{color:var(--danger)}
.button-secondary.danger{border-color:#ebcdc8}
.full{width:100%}
.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}

/* ---------- Text helpers ---------- */
.eyebrow{display:block;font-size:11px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--gold);margin-bottom:10px}
.hint{font-size:12.5px;line-height:1.65;color:var(--ink-3);overflow-wrap:anywhere}
.quiet{margin-top:12px}
.notice{font-size:13px;line-height:1.6;color:var(--ink-2);overflow-wrap:anywhere}
.notice:empty{display:none}
.notice.is-error{color:var(--danger);background:var(--danger-soft);border-radius:var(--r-sm);padding:12px 14px}
.filename{margin-top:10px;font-size:12px;color:var(--ink-3);overflow-wrap:anywhere}
.tag{display:inline-flex;align-items:center;font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;padding:5px 10px;border-radius:999px;background:var(--surface-2);color:var(--ink-3);white-space:nowrap}
.score{display:inline-block;border-radius:999px;padding:2px 9px;background:var(--surface-2);color:var(--ink-2);font-size:11px;font-weight:700;font-family:var(--ui);letter-spacing:0}
.score.good{background:var(--ok-soft);color:var(--ok)}.score.mid{background:var(--warn-soft);color:var(--warn)}.score.bad{background:var(--danger-soft);color:var(--danger)}
.report{white-space:pre-wrap;overflow-wrap:anywhere;margin:16px 0 0;font:12px/1.7 var(--ui);color:var(--ink-3)}
.report:empty{display:none}

/* ---------- Shell: studio sidebar + workspace ---------- */
.workshop{display:grid;grid-template-columns:252px minmax(0,1fr);column-gap:56px;max-width:1400px;margin:0 auto;padding:0 48px 0 0}
.workshop>*{grid-column:2;min-width:0}
.app-header{grid-column:1;grid-row:1/span 60;position:sticky;top:0;align-self:start;height:100vh;height:100dvh;display:flex;flex-direction:column;gap:30px;padding:30px 18px 24px;background:#f3ece5;border-right:1px solid var(--line)}
.app-header .header-actions{display:grid;gap:4px}
.nav-item{justify-content:flex-start;gap:12px;width:100%;min-height:46px;padding:10px 14px;background:none;border:0;border-radius:12px;color:var(--ink-2);font-size:14px;font-weight:600;box-shadow:none}
.nav-item svg{width:20px;height:20px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linejoin:round;stroke-linecap:round}
.nav-item:hover:not(:disabled){background:#ffffff99;color:var(--ink)}
.nav-studio{background:var(--surface);color:var(--plum);box-shadow:var(--shadow-1),0 4px 14px #2b21290d}
.nav-studio:hover:not(:disabled){background:var(--surface);color:var(--plum)}
.member-badge{margin-top:auto;display:flex;gap:12px;align-items:center;padding:14px;border-radius:16px;background:linear-gradient(150deg,#3a2232,#55203f);color:#f4e4d0;box-shadow:0 10px 24px #2b212933}
.member-badge>span{display:grid;place-items:center;flex-shrink:0;width:34px;height:34px;border-radius:50%;background:#ffffff1a;color:#e9c99a;font-size:15px}
.member-badge b{display:block;font-size:13px;color:#fff}
.member-badge small{display:block;font-size:11.5px;line-height:1.4;color:#d9bfae}
.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--ink);font-family:var(--display);font-size:26px;font-weight:600;letter-spacing:-.01em;line-height:1}
.brand small{display:block;font-family:var(--ui);font-size:9.5px;font-weight:700;letter-spacing:.2em;text-transform:uppercase;color:var(--gold);margin-top:6px}
.brand-mark{width:42px;height:42px;border-radius:13px;background:linear-gradient(145deg,#7d3a67,#55203f);color:#fff;display:grid;place-items:center;font-family:var(--display);font-size:28px;font-weight:600;position:relative;box-shadow:0 6px 16px #55203f33}
.brand-mark>span{position:absolute;right:6px;top:2px;color:#e9c99a;font-size:16px}
.app-footer{display:flex;align-items:center;justify-content:space-between;gap:20px;border-top:1px solid var(--line);margin-top:64px;padding:22px 0 32px;font-size:12px;color:var(--ink-3)}
.app-footer .text-button{font-size:12px}

/* ---------- Studio home heading ---------- */
.workspace-heading{display:block;padding:44px 0 6px}
.hero-art{display:none!important}
.hero-copy{max-width:640px}
.workspace-heading h1{font-size:56px;line-height:1;letter-spacing:-.02em;font-weight:500}
.workspace-heading p{font-size:15px;color:var(--ink-3);margin-top:12px}
.route-grid.simple-start{display:flex;flex-wrap:wrap;align-items:center;gap:8px 20px;margin-top:26px}
.simple-start>.route-card{display:inline-flex;align-items:center;gap:10px;min-height:52px;padding:14px 26px;border-radius:14px;border:0;background:var(--plum);color:#fff;font-size:15px;box-shadow:0 2px 4px #55203f26,0 14px 30px #6d2e5833}
.simple-start>.route-card:hover{background:var(--plum-2)}
.simple-start>.route-card b{font-weight:700}
.simple-start>.route-card small,.simple-start>.route-card em{display:none}
.simple-start>.text-button{font-size:14px;color:var(--ink-2);font-weight:500}
.hero-art{position:relative;min-height:340px;pointer-events:none;user-select:none}
.hero-halo{position:absolute;inset:0 -30px;background:radial-gradient(ellipse at 55% 50%,#efd9e2 0%,#f5e8e6 40%,#faf7f300 70%)}
.hero-book{position:absolute;left:20%;top:16px;width:60%;height:300px;border-radius:6px 18px 18px 6px;background:#fff;transform:rotate(-6deg);overflow:hidden;box-shadow:12px 22px 40px #55203f26,-6px -3px 0 #f1e6e3,-9px -6px 0 #fff}
.hero-book>img{width:100%;height:100%;object-fit:cover;object-position:72% 50%;display:block}
.hero-book::after{content:'';position:absolute;left:10px;top:0;bottom:0;width:1px;background:#f6e3e9;box-shadow:-4px 0 6px #43233822}
.hero-book-title{position:absolute;left:10px;right:0;bottom:0;padding:34px 16px 20px;background:linear-gradient(transparent,#f8e7ec 45%);font-family:var(--display);font-size:26px;font-weight:600;color:var(--plum);text-align:center}
.hero-note{position:absolute;bottom:14px;right:0;padding:12px 18px;background:var(--surface);border:1px solid var(--line);border-radius:12px;transform:rotate(5deg);font-family:var(--display);font-style:italic;font-size:17px;color:var(--plum);box-shadow:var(--shadow-2)}
.hero-swatch{position:absolute;width:90px;height:106px;display:grid;place-items:center;background:var(--surface);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow-2)}
.hero-swatch svg{width:48px;height:56px;stroke:var(--gold);stroke-width:1.3;fill:var(--gold-soft)}
.hero-swatch-shirt{left:0;bottom:26px;transform:rotate(-11deg)}
.hero-swatch-dress{right:2px;top:2px;transform:rotate(9deg)}
.hero-star{position:absolute;right:7%;bottom:112px;font-size:28px;color:var(--gold)}
.hero-dot{position:absolute;left:8%;top:28px;width:6px;height:6px;border-radius:50%;background:var(--rose)}
.workshop:not(:has(#projectStep:not([hidden]))) .workspace-heading{display:none!important}
.workshop:has(#activeOrderCard:not([hidden])) .workspace-heading :is(p,.simple-start){display:none}

/* ---------- Step navigation ---------- */
.step-nav{position:sticky;top:12px;z-index:20;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px;padding:5px;margin:28px 0 30px;background:#f3ece6ee;border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow-2);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}
.step-nav>[data-stage="1"]{display:none!important}
.workshop:has(#projectStep:not([hidden])) .step-nav{position:static}
.step-nav button{display:flex;align-items:center;gap:12px;min-width:0;min-height:62px;padding:10px 18px;background:none;border:0;border-radius:14px;color:var(--ink-3);font-size:15px;font-weight:700;text-align:left;box-shadow:none}
.step-nav button:hover:not([aria-current]){color:var(--ink-2);background:#ffffff80}
.step-nav button[aria-current=step]{background:var(--surface);color:var(--plum);box-shadow:var(--shadow-1),0 4px 14px #2b21290f}
.step-nav small{display:block;margin-top:2px;font-size:11.5px;font-weight:500;color:var(--ink-3)}
.step-number{flex-shrink:0;display:grid;place-items:center;width:32px;height:32px;border-radius:50%;border:1px solid var(--line-2);font-size:13px;font-weight:700;color:var(--ink-3);background:var(--surface)}
.step-nav button[aria-current=step] .step-number{background:var(--plum);border-color:var(--plum);color:#fff}
.step-nav button[data-complete=true]:not([aria-current]) .step-number{background:var(--gold-soft);border-color:#e3cfae;color:var(--gold)}
.step-nav i{font-style:normal;font-size:10px;font-weight:700;border-radius:999px;padding:1px 7px;margin-left:4px;background:var(--plum-soft);color:var(--plum)}

/* Context line under the steps: project name, readiness, save state */
.work-context{display:block;margin:-12px 0 26px;padding:0 4px}
.workshop:has(#projectStep:not([hidden])) .work-context{display:none}
#contextTitle{display:block;background:none;border:0;padding:0;min-height:28px;text-align:left;color:var(--ink-3);font-size:13px;font-weight:600;box-shadow:none}
#contextTitle:hover{color:var(--plum)}
.context-status-row{display:flex;align-items:center;gap:18px;flex-wrap:wrap}
.context-meta{display:flex;align-items:center;gap:18px}
.readiness-item{display:flex;align-items:center;gap:7px;font-size:13px;color:var(--ink-2);cursor:default}
.readiness-item input{appearance:none;-webkit-appearance:none;position:relative;flex:0 0 16px;width:16px;height:16px;margin:0;border:1px solid var(--line-2);border-radius:50%;background:var(--surface)}
.readiness-item input:checked{background:var(--ok);border-color:var(--ok)}
.readiness-item input:checked::after{content:'';position:absolute;left:4.5px;top:4px;width:6px;height:3.5px;border-left:1.5px solid #fff;border-bottom:1.5px solid #fff;transform:rotate(-45deg)}
.context-save{font-size:12px;color:var(--ink-3);white-space:nowrap}
.context-save[data-phase=saved]::before{content:'·';margin-right:10px;color:var(--line-2)}
.context-save[data-phase=error],.context-save[data-phase=dirty]{color:var(--warn)}
#contextNext,.work-context #contextAction{display:none!important}

/* ---------- Sections and cards ---------- */
.stage:not([hidden]){animation:enter .25s ease-out}
.section-heading{margin:6px 0 26px}
.section-heading .eyebrow{margin-bottom:10px}
.section-heading h2{font-size:44px;line-height:1.05}
.section-heading p{font-size:15px;margin-top:12px;max-width:680px;color:var(--ink-2)}
.card,.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--r-lg);padding:28px;box-shadow:var(--shadow-1);min-width:0}
.card-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:20px}
.card-divider{height:1px;background:var(--line);margin:24px 0}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:18px}
.flow-path{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;list-style:none;margin:0 0 22px;padding:0}
.flow-path li{display:flex;align-items:center;gap:10px;padding:12px 14px;border:1px solid var(--line);border-radius:14px;background:var(--surface)}
.flow-path b{display:grid;place-items:center;flex:none;width:30px;height:30px;border-radius:50%;background:var(--plum-soft);color:var(--plum);font-size:14px}
.flow-path span{font-weight:700;font-size:14px;line-height:1.2}.flow-path small{display:block;font-weight:500;font-size:12px;color:var(--ink-3)}
@media (max-width:760px){.flow-path{grid-template-columns:repeat(2,minmax(0,1fr))}}
.step-footer{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-top:32px;padding-top:24px;border-top:1px solid var(--line)}
.step-footer>.primary{min-height:52px;padding:14px 28px;font-size:15px}

/* Disclosures */
.disclosure{margin-top:20px;background:var(--surface);border:1px solid var(--line);border-radius:var(--r-md);overflow:hidden}
.disclosure>summary{display:flex;align-items:center;gap:12px;min-height:58px;padding:16px 22px;list-style:none;cursor:pointer;font-size:14px;font-weight:700;color:var(--ink)}
.disclosure>summary::-webkit-details-marker{display:none}
.disclosure>summary::after{content:'';flex-shrink:0;margin-left:auto;width:9px;height:9px;border-right:1.6px solid var(--ink-3);border-bottom:1.6px solid var(--ink-3);transform:rotate(45deg) translateY(-3px);transition:transform .2s}
.disclosure[open]>summary::after{transform:rotate(-135deg) translateY(-2px)}
.disclosure>summary>span:not(.tag){font-size:12.5px;font-weight:500;color:var(--ink-3)}
.disclosure>summary:hover{background:#fcfaf8}
.disclosure-body{display:grid;gap:16px;padding:6px 22px 22px}
.disclosure.compact>summary{min-height:44px;padding:10px 16px;font-size:13px}
.disclosure .disclosure{margin-top:4px}

/* Forms */
.field{display:grid;gap:8px;font-size:13px;font-weight:700;color:var(--ink-2)}
.field small{font-size:12px;font-weight:500;color:var(--ink-3)}
input:not([type=checkbox]):not([type=range]):not([type=file]):not([type=hidden]),select{display:block;width:100%;min-width:0;min-height:48px;padding:12px 14px;border:1px solid var(--line-2);border-radius:12px;background:var(--surface);color:var(--ink);font-size:15px;line-height:1.4;transition:border-color .15s,box-shadow .15s}
input:not([type=checkbox]):not([type=range]):focus,select:focus{outline:none;border-color:var(--plum);box-shadow:0 0 0 4px #6d2e581a}
input::placeholder{color:#b3a8af;opacity:1}
input[type=checkbox]{width:19px;height:19px;accent-color:var(--plum);flex-shrink:0}
input[type=range]{width:100%;accent-color:var(--plum);min-height:24px}
.check-row{display:flex!important;align-items:center;gap:10px;min-height:38px;font-size:13px!important;font-weight:500;color:var(--ink-2)}
.slider{display:grid;gap:8px;font-size:13px;font-weight:600;color:var(--ink-2)}
.slider #tolVal{color:var(--plum)}
.params{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:16px;align-items:start}
.params label{display:grid;gap:7px;min-width:0;font-size:12px;font-weight:600;color:var(--ink-3)}
.params .check-row{align-self:end;min-height:48px}
.params+p{margin-top:14px}

/* Spinners, toasts, boot */
.spinner{display:inline-block;flex-shrink:0;width:18px;height:18px;border:2px solid #6d2e5826;border-top-color:var(--plum);border-radius:50%;animation:spin .8s linear infinite;vertical-align:middle}
.spinner.large{width:36px;height:36px;border-width:3px}
.button-spinner{width:15px;height:15px;border-color:#fff5;border-top-color:currentColor}
.button-secondary .button-spinner{border-color:#6d2e5826;border-top-color:var(--plum)}
.toast{display:block;margin:-14px 0 22px;padding:13px 18px;border-radius:var(--r-md);background:var(--ok-soft);border:1px solid #d5e6da;color:var(--ok);font-size:13.5px;font-weight:600}
#appToast.is-error{background:var(--danger-soft);border-color:#efcdc6;color:var(--danger)}
.boot-screen{position:fixed;inset:0;z-index:20000;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;padding:30px;text-align:center;background:var(--paper)}
.boot-screen b{font-family:var(--display);font-size:32px;font-weight:500}
.boot-screen>span:last-child{font-size:14px;color:var(--ink-3)}
:root[data-ready=true] .boot-screen{display:none}
:root[data-loading=project]::after{content:'Открываем проект…';position:fixed;top:18px;left:50%;z-index:30000;transform:translateX(-50%);padding:11px 20px 11px 40px;border-radius:999px;background:var(--plum) no-repeat 16px 50%/14px 14px;background-image:radial-gradient(circle,#fff 30%,transparent 32%);color:#fff;font:600 13px var(--ui);box-shadow:var(--shadow-3)}
:root[data-loading=project] main{cursor:progress}
.resume-modal{max-width:400px;padding:38px 32px 28px;text-align:center;background:radial-gradient(ellipse at 50% 0%,#f8e9ef 0%,#fff 58%)}
.resume-modal[open]{animation:celebrate .35s ease-out}
.resume-close{position:absolute;top:14px;right:14px;width:38px;min-width:38px;height:38px;min-height:38px;font-size:20px;border-color:transparent;background:transparent}
.resume-art{position:relative;width:118px;height:150px;margin:0 auto 20px;border-radius:18px;background:linear-gradient(160deg,#fff,#f6eef1);border:1px solid var(--line);box-shadow:0 14px 34px #55203f1f;overflow:hidden;display:grid;place-items:center}
.resume-art img{width:100%;height:100%;object-fit:contain;background:#fff}
.resume-art>span{position:absolute;right:8px;top:6px;color:var(--gold);font-size:16px}
.resume-art:not(:has(img:not([hidden])))>span{position:static;font-size:42px}
.resume-modal .eyebrow{margin-bottom:6px}
.resume-modal h2{font-size:30px;line-height:1.1;overflow-wrap:anywhere}
.resume-modal #resumeMeta{margin-top:8px;font-size:13px;color:var(--ink-3)}
.resume-actions{display:grid;gap:6px;margin-top:24px}
.resume-actions .primary{min-height:52px;font-size:15px}
.processing-notice{display:flex;align-items:flex-start;gap:12px;margin-top:20px;padding:15px 18px;min-height:50px;border-radius:var(--r-md);background:var(--surface-2)}
.processing-notice .notice{color:var(--ink-2)}
.processing-notice .spinner{margin-top:2px}
.processing-notice:has(.notice:empty){display:none}
.checker{background-color:#fbfaf8;background-image:linear-gradient(45deg,#f1ede8 25%,transparent 25%),linear-gradient(-45deg,#f1ede8 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#f1ede8 75%),linear-gradient(-45deg,transparent 75%,#f1ede8 75%);background-size:18px 18px;background-position:0 0,0 9px,9px -9px,-9px 0}

/* ---------- Home: project card, ready books ---------- */
#projectStep>.section-heading{margin:0 0 18px}
#projectStep>.section-heading>.eyebrow{display:none}
#projectHeading{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
#projectStep>.section-heading>p{font-size:13px;color:var(--ink-3)}
.project-layout{display:block;margin:0 0 24px}
.project-guide{display:none!important}
.project-card{padding:32px}
.save-indicator{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-3)}
#cloudSaveDot{width:7px;height:7px;border-radius:50%;background:var(--line-2)}
#cloudSaveDot.saved{background:var(--ok)}#cloudSaveDot.busy{background:var(--gold);animation:pulse 1s ease-in-out infinite}#cloudSaveDot.error{background:var(--danger)}
.project-name-field>span{font-size:14px}
.project-name-field input,input#cloudTitle{min-height:62px;font-family:var(--display);font-size:28px!important;font-weight:600;padding:12px 18px;background:#fdfbf9}
#activeOrderCard #cloudStatus:not(.is-error),#activeOrderCard .card-divider{display:none}
.card-bottom{display:grid;gap:14px;margin-top:20px}
.card-bottom>p,.project-name-field small{display:none}
.card-bottom>.primary,#homeNextAction{width:100%;min-height:54px;font-size:15px}
.home-project-actions{gap:22px;margin:0}
.project-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:6px}
.project-actions button{flex:1}
/* Ready books: a section of the studio home, always open */
.ready-book-options{margin-top:48px;padding-top:36px;border:0;border-top:1px solid var(--line);border-radius:0;background:none;overflow:visible;scroll-margin-top:20px}
#readyBookOptions>summary{pointer-events:none;flex-wrap:wrap;gap:4px;min-height:0;padding:0 0 20px;font-family:var(--display);font-size:38px;font-weight:500;letter-spacing:-.02em}
#readyBookOptions>summary::after{display:none}
#readyBookOptions>summary>span{width:100%;font-family:var(--ui);font-size:14px!important}
#readyBookOptions>.disclosure-body{padding:0}
#readyBookOptions>.disclosure-body>p.hint{display:none}
.gender-tabs{gap:8px;margin:0 0 6px}
.gender-tabs button{min-height:38px;padding:8px 18px;border-radius:999px;background:var(--surface-2);border:0;color:var(--ink-2);font-size:13px}
.gender-tabs button[aria-pressed=true]{background:var(--ink);color:#fff}
.library-card{display:flex;align-items:center;justify-content:space-between;gap:16px 24px;flex-wrap:wrap;margin-top:20px;padding:20px 24px}
.library-card h3{margin:0 0 4px}.library-card .hint{margin:0}
.library-modal{max-width:1000px}
.library-grid{grid-template-columns:repeat(auto-fill,minmax(170px,1fr));margin-top:16px}
.library-grid .garment-image{height:170px}
.library-grid .garment-card strong{font-size:13px;overflow-wrap:anywhere}
.library-grid .library-hidden{opacity:.55}
.library-upload{display:grid;gap:12px;padding:16px;margin-top:12px;border:1.5px dashed var(--line-2);border-radius:16px;background:var(--surface)}
.library-upload .hint{margin:4px 0 0}
.library-upload-row{display:flex;flex-wrap:wrap;gap:12px;align-items:end}.library-upload-row .field{flex:1 1 160px;margin:0}
.cut-mode-modal{max-width:560px}.cut-mode-choices{display:grid;gap:12px;margin-top:18px}
.cut-mode-choice{display:grid;gap:6px;text-align:left;padding:18px 20px;border:1.5px solid var(--line-2);border-radius:16px;background:var(--surface);cursor:pointer;font:inherit;color:var(--ink)}
.cut-mode-choice:hover{border-color:var(--plum)}.cut-mode-choice b{font-size:17px}.cut-mode-choice span{font-size:13.5px;color:var(--ink-3);line-height:1.45}
.sheet-rail{background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:16px;margin-bottom:16px;box-shadow:var(--shadow-1)}
.sheet-rail.side{position:fixed;z-index:15;margin:0;max-height:calc(100vh - 140px);overflow:auto}
.sheet-rail-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px}.sheet-rail-head b{font-size:15px}
.sheet-rail-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(76px,1fr));gap:8px;margin-bottom:12px}
.sheet-rail:not(.side) .sheet-rail-list{display:flex;overflow-x:auto;padding-bottom:4px}.sheet-rail:not(.side) .sheet-rail-item{flex:0 0 78px}
.sheet-rail-item{position:relative;display:grid;gap:4px;justify-items:center;padding:6px 4px;border:1px solid var(--line);border-radius:12px;background:#fff;font-size:11px;color:var(--ink-3);text-align:center}
.sheet-rail-item canvas{width:60px;height:60px;object-fit:contain}
.sheet-rail-item button{position:absolute;top:-6px;right:-6px;width:22px;height:22px;border-radius:50%;border:0;background:var(--plum);color:#fff;font-size:13px;line-height:22px;padding:0;cursor:pointer}
.sheet-rail #sheetRailEmpty{margin:0 0 12px}
.fit-tile-pic{position:relative}.fit-tile .on-sheet{position:absolute;left:8px;bottom:8px;padding:2px 8px;border-radius:999px;background:var(--plum);color:#fff;font-size:11px;font-weight:700}
.fit-tip{display:block;margin-top:2px;color:var(--ink-3)}
.cut-mode-switch{margin:-4px 0 10px;font-size:13px}
.library-pick{display:inline-flex;align-items:center;justify-content:center;min-height:46px;padding:0 20px;border:1px solid var(--line-2);border-radius:999px;background:var(--surface);color:var(--plum);font-weight:700;cursor:pointer;white-space:nowrap}
.library-pending:empty{display:none}.library-pending{margin-top:0}.library-pending .garment-card canvas{display:block;width:100%;height:120px;object-fit:contain}
.library-grid select{min-height:38px;font-size:13px}
/* Fitting room: on the left a soft pink «studio» with the doll on a podium, on the right the wardrobe as a shop window. */
.fitting{position:relative;margin:0 0 30px}
.fit-body{display:grid;grid-template-columns:minmax(300px,430px) minmax(0,1fr);gap:24px;align-items:start}
.fit-doll-col{position:sticky;top:96px;z-index:0;display:grid;gap:14px;padding:30px 22px 22px;border-radius:34px;border:1px solid #f1e1ea;overflow:hidden;
 background:radial-gradient(60% 45% at 50% 36%,#fff 0,#fff0 100%),linear-gradient(180deg,#fcf1f6 0%,#f8ecf2 60%,#f3e4ec 100%);box-shadow:inset 0 1px 0 #fff,0 34px 70px -46px #55203f66}
.fit-doll-col::before{content:'';position:absolute;inset:0;z-index:-1;pointer-events:none;background-image:radial-gradient(#e7cfdc 1.1px,transparent 1.4px);background-size:20px 20px;
 -webkit-mask-image:radial-gradient(ellipse 70% 60% at 50% 40%,#0000 35%,#000 100%);mask-image:radial-gradient(ellipse 70% 60% at 50% 40%,#0000 35%,#000 100%);opacity:.7}
/* The doll stands on a round podium; a white photo background melts into the studio (multiply). */
.fit-stage{position:relative;height:min(62vh,600px);aspect-ratio:1360/2919;max-width:100%;margin:0 auto 26px;overflow:visible}
.fit-stage::before{content:'';position:absolute;z-index:-1;left:-38%;right:-38%;bottom:-4.6%;height:9%;border-radius:50%;background:radial-gradient(ellipse at 50% 30%,#fff 0,#fdf7fa 55%,#efdfe8 100%);box-shadow:0 5px 0 #e9d5e0,0 7px 0 #dcc4d2,0 26px 30px -14px #55203f50}
.fit-stage img{position:absolute;max-width:none;pointer-events:none;user-select:none}
.fit-stage .fit-doll{left:0;top:0;width:100%;height:100%;object-fit:contain;mix-blend-mode:multiply}
.fit-stage .fit-wear{animation:fitIn .3s cubic-bezier(.2,.8,.3,1.2);pointer-events:auto;cursor:grab;touch-action:none;filter:drop-shadow(0 2px 3px #2b212924)}
.fit-stage .fit-wear.selected{outline:2px dashed #6d2e58aa;outline-offset:4px;border-radius:8px}
.fit-stage .fit-wear.dragging{cursor:grabbing;animation:none;filter:drop-shadow(0 12px 16px #55203f55)}
@keyframes fitIn{from{opacity:0;transform:translateY(-10px) scale(.97)}to{opacity:1;transform:none}}
.fit-empty{position:absolute;inset:0;display:grid;place-content:center;gap:10px;padding:28px;text-align:center;color:var(--ink-2);font-size:13px}
.fit-empty b{font:800 18px/1.2 var(--ui);color:var(--ink)}
.fe-art{position:relative;height:min(320px,46vh);aspect-ratio:200/470;margin:0 auto}
.fe-svg{width:100%;height:100%;display:block;opacity:.9}
#fitEmpty .fe-plus{position:absolute;left:50%;top:92%;width:64px;height:64px;min-height:0;margin:-32px 0 0 -32px;padding:0;border:0;border-radius:50%;display:grid;place-items:center;background:linear-gradient(135deg,#86386b,#5a2247);color:#fff;box-shadow:0 14px 30px -10px #6d2e58cc,0 0 0 8px #ffffffa6;cursor:pointer;animation:fePulse 2.4s ease-in-out infinite}
#fitEmpty .fe-plus span{font:300 40px/1 var(--ui);margin-top:-4px}
@keyframes fePulse{0%,100%{transform:scale(1)}50%{transform:scale(1.07)}}
.fitting.no-doll+.own-cta{display:none}
.fit-tools{display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap;padding:8px 12px;border-radius:20px;background:#ffffffd9;backdrop-filter:blur(8px);border:1px solid #f0dfe8;box-shadow:0 10px 24px -18px #55203f77;font-size:13px;font-weight:700}
.fit-size{display:inline-flex;align-items:center;gap:6px}.fit-size button{width:36px;height:36px;min-height:0;padding:0;border-radius:50%;border:0;background:var(--plum-soft);color:var(--plum);font-size:20px;font-weight:700;box-shadow:none}
.fit-size button:hover{background:#ecdbe5}
.fit-size b{min-width:56px;text-align:center;font-variant-numeric:tabular-nums}
.fit-hint{text-align:center;font-size:12px;font-weight:700;color:#7a4b1f;background:#fbf0dc;border-radius:999px;padding:6px 12px;margin:6px auto 0;width:max-content;max-width:94%}
.fit-hint[hidden]{display:none}
 @media(max-width:760px){.fit-hint{position:absolute;left:50%;transform:translateX(-50%);bottom:64px;z-index:7;pointer-events:none;box-shadow:0 4px 14px rgba(60,30,10,.15)}}
.fit-worn{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;min-height:56px;align-items:center}
.fit-worn:empty::before{content:'Пока ничего не надето — выбери вещь в гардеробе';color:var(--ink-3);font-size:12.5px}
.fit-chip{position:relative;width:54px;height:54px;padding:5px;border-radius:18px;border:0;background:#fff;box-shadow:0 0 0 1px #f0e0e9,0 8px 18px -12px #55203f77;min-height:0;transition:transform .15s,box-shadow .15s}
.fit-chip:hover{transform:translateY(-2px);box-shadow:0 0 0 2px var(--plum),0 10px 20px -12px #55203f88}
.fit-chip img{width:100%;height:100%;object-fit:contain}
.fit-chip span{position:absolute;top:-5px;right:-5px;display:grid;place-items:center;width:20px;height:20px;border-radius:50%;background:var(--plum);color:#fff;font-size:13px;line-height:1;box-shadow:0 0 0 2px #fff}
.fit-actions{display:flex;justify-content:center;align-items:center;gap:12px}
.fit-actions #fitAdd{flex:1;max-width:300px;min-height:52px;border-radius:999px;font-size:15px;background:linear-gradient(135deg,#86386b 0%,#5a2247 100%);box-shadow:0 16px 30px -16px #6d2e58cc,inset 0 1px 0 #ffffff30}
.fit-actions #fitAdd:disabled{background:#d9c3cf;box-shadow:none}
/* The wardrobe: a white panel, sections as soft pills, items as cards. */
.fit-shop{min-width:0;padding:24px;border-radius:34px;background:#fff;border:1px solid #f1e5ea;box-shadow:0 34px 70px -50px #55203f55}
.fit-shop-head{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;margin:0 0 16px}
.fit-shop-head b{display:block;font:800 19px/1.2 var(--ui);color:var(--ink);letter-spacing:-.01em}
.fit-shop-head small{display:block;margin-top:6px;color:var(--ink-3);font-size:12.5px;font-weight:600}
.fit-tabs{display:flex;flex-wrap:wrap;gap:8px;padding:0 0 16px;margin-bottom:4px;border-bottom:1px solid #f3eaee}
.fit-tab{flex:none;display:inline-flex;align-items:center;gap:8px;min-height:42px;padding:6px 14px 6px 6px;border-radius:999px;border:0;background:#f8f2f5;color:var(--ink);font:700 13px var(--ui);box-shadow:none;transition:background .15s,transform .15s,box-shadow .15s}
.fit-tab:hover{background:#f2e7ed}
.fit-tab-icon{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#fff;font-size:16px;box-shadow:0 2px 6px -3px #55203f44}
.fit-tab small{min-width:20px;padding:1px 7px;border-radius:999px;background:#fff;color:var(--ink-3);font-size:11px;text-align:center}
.fit-tab[aria-pressed=true]{background:linear-gradient(135deg,#86386b,#5a2247);color:#fff;box-shadow:0 10px 20px -12px #6d2e58cc}
.fit-tab[aria-pressed=true] .fit-tab-icon{background:#ffffff26;box-shadow:none}
.fit-tab[aria-pressed=true] small{background:#ffffff2e;color:#fff}
.fit-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(138px,1fr));gap:14px;max-height:calc(100vh - 300px);min-height:360px;overflow-y:auto;padding:14px 6px 8px 2px;margin-top:2px;scrollbar-width:thin;scrollbar-color:#e3cbd8 transparent;align-content:start}
.fit-tile{position:relative;display:grid;gap:8px;align-content:start;padding:0 0 10px;border:0;border-radius:24px;background:none;color:var(--ink);font:700 12px var(--ui);text-align:center;min-height:0;box-shadow:none;transition:transform .2s}
.fit-tile-pic{display:block;aspect-ratio:1;border-radius:24px;background:radial-gradient(circle at 50% 42%,#fff 0,#f9f3f6 62%,#f4eaef 100%);overflow:hidden;box-shadow:inset 0 0 0 1px #f2e6ec;transition:box-shadow .2s,background .2s}
.fit-tile-pic img{width:100%;height:100%;object-fit:contain;padding:12%;transition:transform .3s cubic-bezier(.2,.8,.3,1.2)}
.fit-tile-pic img:not([src]){opacity:0}
.fit-tile-pic:has(img:not([src])){background:linear-gradient(100deg,#f7eff3 30%,#fdf9fb 50%,#f7eff3 70%) 0 0/300% 100%;animation:fitShimmer 1.4s linear infinite}
@keyframes fitShimmer{to{background-position:-150% 0}}
.fit-tile:hover .fit-tile-pic{background:radial-gradient(circle at 50% 42%,#fff 0,#fff 60%,#f8eef3 100%);box-shadow:inset 0 0 0 1px #ead6e1,0 18px 30px -20px #55203f77}
.fit-tile:hover .fit-tile-pic img{transform:scale(1.06) translateY(-2px)}
.fit-tile-name{color:var(--ink-2)}
.fit-tile[aria-pressed=true] .fit-tile-pic{background:radial-gradient(circle at 50% 42%,#fff 0,#fdf5f9 60%,#f6e3ed 100%);box-shadow:inset 0 0 0 2px var(--plum),0 18px 30px -20px #6d2e58aa}
.fit-tile[aria-pressed=true]::after{content:'✓';position:absolute;top:10px;right:10px;display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:var(--plum);color:#fff;font-size:13px;font-weight:800;box-shadow:0 0 0 3px #fff}
.fit-tile[aria-pressed=true] .fit-tile-name{color:var(--plum)}
.own-clothes{margin-top:8px}
@media (max-width:1100px) and (min-width:761px){.fit-body{grid-template-columns:minmax(260px,340px) minmax(0,1fr)}.fit-grid{grid-template-columns:repeat(auto-fill,minmax(118px,1fr))}}
/* Phone: the doll on top, sections as one swipeable row, three items per row, the «Гардероб собран» bar fixed at the bottom. */
@media (max-width:760px){.fitting{padding-bottom:84px}.fit-body{grid-template-columns:1fr;gap:14px}
 .fit-doll-col{position:static;padding:18px 14px 14px;border-radius:28px}.fit-stage{height:min(50vh,430px);margin-bottom:22px}
 .fit-shop{padding:16px 12px;border-radius:28px}.fit-shop-head{margin-bottom:12px}.fit-shop-head b{font-size:17px}
 .fit-tabs{flex-wrap:nowrap;overflow-x:auto;scroll-snap-type:x proximity;scrollbar-width:none;margin:0 -12px 4px;padding:0 12px 14px}
 .fit-tabs::-webkit-scrollbar{display:none}.fit-tab{scroll-snap-align:start;min-height:40px}
 .fit-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;max-height:none;min-height:0;overflow:visible;padding:12px 0 0}
 .fit-tile{border-radius:18px;padding-bottom:6px;font-size:11px}.fit-tile-pic{border-radius:18px}.fit-tile[aria-pressed=true]::after{top:6px;right:6px;width:22px;height:22px;font-size:12px}
 .fit-actions{position:fixed;left:12px;right:12px;bottom:12px;z-index:40;padding:10px 12px;border-radius:26px;background:#ffffffeb;-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);box-shadow:0 0 0 1px #f0e0e9,0 18px 40px -18px #55203f88}
 .fit-actions #fitAdd{max-width:none;min-height:48px}}
#openOrders,#bookPublish{display:none!important}
.book-catalog{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:18px}
.book-card{display:grid;gap:12px;align-content:start;padding:14px;border-radius:18px;transition:box-shadow .2s,transform .2s}
.book-card:not(:has(button:disabled)):hover{box-shadow:var(--shadow-2);transform:translateY(-2px)}
.book-art{height:200px;border-radius:12px;display:grid;place-items:center;overflow:hidden;background:linear-gradient(150deg,#f3e3e9,#ead6df);color:var(--plum);font-size:48px}
.book-art>img{width:100%;height:100%;object-fit:cover!important;object-position:70% center}
.book-art svg{width:72px;height:72px;fill:none;stroke:currentColor;stroke-width:1.1}
/* Book step: a card per ready book with its spreads. */
.book-choices{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,420px),1fr));gap:22px}
.book-choice{display:flex;flex-direction:column;gap:12px}
.book-choice.is-chosen{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft)}
.book-choice-spread{display:block;width:100%;height:auto;aspect-ratio:1200/609;object-fit:cover;border-radius:12px;background:var(--accent-soft)}
.book-choice-thumbs{display:flex;gap:8px;flex-wrap:wrap}
.book-choice-thumbs button{padding:0;border:2px solid transparent;border-radius:8px;background:none;cursor:pointer;line-height:0}
.book-choice-thumbs button[aria-pressed=true]{border-color:var(--accent)}
.book-choice-thumbs img{width:84px;height:43px;object-fit:cover;border-radius:6px}
.book-choice .card-heading{margin:0}.book-choice h3{margin:0}.book-choice p{margin:0}
.book-choice>button:last-child{margin-top:auto}
#bookChoiceStatus{margin-top:18px}
#bookStep .step-footer{flex-wrap:wrap}
@media (max-width:760px){#bookNone{order:3;flex:1 0 100%;max-width:none;justify-content:center;text-align:center}}
.book-card h3{font-family:var(--display);font-size:24px;font-weight:600}
.book-card p{font-size:13px;line-height:1.55}
.book-card button{min-height:44px}
.book-card button:disabled{background:var(--surface-2);border-color:var(--surface-2);color:var(--ink-3);opacity:1}
.book-publish-previews{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:18px 0}
#lastResultRecoveryPanel,#resumeOrderPanel{border-color:var(--plum-line);background:linear-gradient(180deg,#fff,#fdf8fa)}
#localDraftNotice{margin-top:20px;padding:16px 18px;border-radius:var(--r-md);background:var(--warn-soft)}

/* ---------- Step 1: doll ---------- */
.creation-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px;align-items:start}
.photo-upload{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:300px;border:1.5px dashed var(--plum-line);border-radius:18px;background:linear-gradient(180deg,#fdf9fb,#faf3f6);text-align:center;overflow:hidden;cursor:pointer;transition:background .2s,border-color .2s}
.photo-upload:hover,.photo-upload.over,.clothes-drop:hover,.clothes-drop.over{border-color:var(--plum);background:var(--plum-soft)}
.photo-upload img{display:block;width:100%;height:300px;object-fit:contain;padding:14px;background:var(--surface-2)}
.upload-empty{display:flex;flex-direction:column;align-items:center;gap:8px;padding:26px 16px}
.upload-empty b,.clothes-drop strong{font-size:16px;font-weight:700;color:var(--plum)}
.upload-empty>span:last-child{font-size:13px;color:var(--ink-3)}
.upload-icon{display:grid;place-items:center;width:52px;height:52px;margin-bottom:6px;border-radius:50%;background:var(--surface);color:var(--plum);font-size:26px;line-height:1;box-shadow:var(--shadow-2)}
.photo-change{position:absolute;bottom:12px;padding:7px 16px;border-radius:999px;background:#fffffff0;border:1px solid var(--line);color:var(--plum);font-size:12px;font-weight:600;box-shadow:var(--shadow-1)}
.upload-advice{margin:16px 0;font-size:13px;line-height:1.65;color:var(--ink-2)}
.portrait-guide{margin:0 0 16px;padding:20px 18px 18px;border-radius:18px;text-align:center;background:linear-gradient(160deg,#fdf8fa,#f7f1ea);border:1px solid var(--line)}
.portrait-guide-title{margin:0;font-family:var(--display);font-size:21px;line-height:1.25;color:var(--ink)}
.portrait-guide-title b,.portrait-guide-sub b{color:var(--plum);font-weight:700}
.portrait-guide-sub{margin:8px 0 16px;font-size:13.5px;color:var(--ink-2)}
.portrait-guide-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.portrait-tip{margin:0;min-width:0}
.portrait-photo{position:relative;display:block;aspect-ratio:1;border-radius:14px;border:3px solid #5f9a72;box-shadow:0 6px 16px #2b21291a;background:var(--surface-2)}
.portrait-photo img{display:block;width:100%;height:100%;object-fit:cover;border-radius:11px}
.portrait-photo i{position:absolute;right:-8px;bottom:-8px;display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:#4f9566;border:2.5px solid #fff;color:#fff;font-size:14px;font-style:normal;font-weight:800;box-shadow:0 2px 6px #2b212933}
.portrait-tip figcaption{margin-top:12px;font-size:11.5px;line-height:1.4;color:var(--ink-2)}
.portrait-tip figcaption b{color:var(--ink)}
#gRun{width:100%;min-height:54px;font-size:15px}
.gen-quota{margin:10px 0 0;text-align:center;font-size:12.5px;font-weight:600;color:var(--ink-3)}
.gen-quota[data-empty=true]{padding:10px 12px;border-radius:12px;background:var(--warn-soft);color:var(--warn)}
.result-stage{position:relative;display:grid;place-items:center;min-height:380px;border-radius:16px;overflow:hidden}
.result-stage img{display:block;width:100%;max-height:560px;object-fit:contain}
.result-empty{display:flex;flex-direction:column;align-items:center;gap:12px;padding:30px;text-align:center;color:var(--line-2)}
.result-empty b{font-size:15px;font-weight:600;color:var(--ink-2)}
.result-empty>span{font-size:13px;color:var(--ink-3)}
.result-card:has(#dollEmpty:not([hidden])) .result-stage{min-height:140px}
.result-card:has(#dollEmpty:not([hidden])) .result-empty{gap:8px;padding:22px}
.result-card:has(#dollEmpty:not([hidden])) .result-empty svg{width:30px;height:42px}
.result-card:has(#dollEmpty:not([hidden])) :is(.result-actions,.small-actions){display:none}
.result-actions{display:flex;gap:10px;margin-top:18px}
.result-actions>.primary{flex:1}
.small-actions{gap:20px;margin-top:6px}
/* After the doll is ready: only the doll, the next step and two quiet links. */
#gCmp{display:none!important}
.result-actions:has(#gAdd[hidden]){justify-content:center;margin-top:12px}
.result-actions:has(#gAdd[hidden]) #gSave{flex:0 0 auto;min-height:40px;padding:8px 2px;background:none;border:0;box-shadow:none;color:var(--plum);font-size:13px}
.small-actions{justify-content:center;gap:28px}
#dollStep:has(#gOut:not([hidden])):has(#generationSpinner[hidden]) .processing-notice:not(:has(.is-error)){display:none}
#dollStep:has(#gOut:not([hidden]))>details.disclosure{display:none}.doll-check{display:grid;gap:3px;margin-top:12px;padding:14px 16px;border-radius:14px;font-size:12.5px;line-height:1.5;text-align:center}
.doll-check b{font-family:var(--display);font-size:22px;font-weight:600;line-height:1.2}
.doll-check[data-state=ok]{animation:celebrate .6s ease-out}
.doll-check[data-state=ok]{background:linear-gradient(135deg,#fbf3e6,#f6e9f0);color:var(--ink-2);border:1px solid #efdcc0}
.doll-check[data-state=ok] b{color:var(--plum)}
.doll-check[data-state=warn]{background:var(--warn-soft);color:var(--warn)}
/* Generation waiting screen */
.generation-overlay.magic{gap:12px;background:radial-gradient(circle at 50% 38%,#fff9f2f5,#fbf3f6f0 60%,#f7ecf2f2);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
.generation-overlay.magic>b{font-family:var(--display);font-size:28px;font-weight:600;color:var(--plum);max-width:300px}
.magic-orb{position:relative;width:96px;height:96px;margin-bottom:4px}
.magic-orb>span{position:absolute;inset:0;display:grid;place-items:center;font-size:40px;color:var(--gold);animation:glow 2.4s ease-in-out infinite}
.magic-orb>i{position:absolute;left:50%;top:50%;width:7px;height:7px;margin:-3.5px;border-radius:50%;background:var(--gold);box-shadow:0 0 10px #e9c99a;animation:orbit 3.2s linear infinite}
.magic-orb>i:nth-child(2){animation-delay:-.53s;background:#d9a7c0;box-shadow:0 0 10px #ecc3d6}
.magic-orb>i:nth-child(3){animation-delay:-1.07s;width:5px;height:5px}
.magic-orb>i:nth-child(4){animation-delay:-1.6s;background:#d9a7c0;box-shadow:0 0 10px #ecc3d6}
.magic-orb>i:nth-child(5){animation-delay:-2.13s;width:5px;height:5px}
.magic-orb>i:nth-child(6){animation-delay:-2.67s;background:#c9a0e0;box-shadow:0 0 10px #dcc0ee}
.magic-phrase{min-height:22px;font-size:14px;font-weight:600;color:var(--ink-2)!important}
.magic-phrase.swap{animation:phrase .5s ease-out}
.magic-bar{width:min(240px,80%);height:5px;border-radius:999px;background:#6d2e581a;overflow:hidden}
.magic-bar>i{display:block;height:100%;width:0;border-radius:inherit;background:linear-gradient(90deg,var(--gold),#d9a7c0,var(--plum));transition:width .5s ease-out}
.generation-overlay.magic>small{font-size:12px;color:var(--ink-3)}
#dollStep:has(#generationSpinner:not([hidden])) .processing-notice{display:none}
.result-card:has(#generationOverlay:not([hidden])) .result-stage{min-height:420px}
.result-card:has(#generationOverlay:not([hidden])) :is(#dollCheck,.result-actions,.small-actions){display:none!important}
@keyframes orbit{from{transform:rotate(0) translateX(40px) scale(1)}50%{transform:rotate(180deg) translateX(40px) scale(.6)}to{transform:rotate(360deg) translateX(40px) scale(1)}}
@keyframes glow{50%{transform:scale(1.15);opacity:.75;text-shadow:0 0 18px #e9c99a}}
@keyframes phrase{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
@keyframes celebrate{0%{opacity:0;transform:scale(.96)}60%{transform:scale(1.02)}to{opacity:1;transform:none}}.generation-overlay{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;padding:26px;text-align:center;background:#fffdfbeb;-webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px)}
.generation-overlay b{font-family:var(--display);font-size:26px;font-weight:600}
.generation-overlay>span:last-child{font-size:13px;color:var(--ink-3)}
#repeatChildNotice{padding:16px 18px;border-radius:var(--r-md);background:var(--plum-soft);color:var(--plum)}

/* ---------- Step 2: clothes ---------- */
.clothes-intro{display:flex;align-items:center;gap:18px;margin-bottom:18px;padding:18px 22px;border-radius:var(--r-md);background:var(--gold-soft);border:1px solid #efe1c9}
.intro-number{flex-shrink:0;display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:var(--surface);color:var(--gold);font-size:12px;font-weight:800}
.clothes-intro p{flex:1;font-size:13px;color:#7a6446}
.clothes-intro p b{color:#4e3d27}
.clothes-intro button{background:var(--surface);border-color:#e6d3b4;color:#7a5a2c}
.drop{position:relative;display:flex;flex-direction:column;align-items:center;gap:8px;padding:32px 22px;border:1.5px dashed var(--plum-line);border-radius:18px;background:linear-gradient(180deg,#fdf9fb,#faf3f6);text-align:center;cursor:pointer;transition:background .2s,border-color .2s}
.drop input[type=file]{position:absolute;opacity:0;width:1px;height:1px;overflow:hidden}
.clothes-drop{min-height:230px;justify-content:center}
.clothes-drop>span:not(.upload-icon){font-size:13px;color:var(--ink-3)}
.clothes-drop .upload-caption{font-size:11.5px!important}
.drop.small{padding:18px;gap:6px}
.drop.small strong{font-size:13px}
.bcards{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:16px;margin-top:20px}
.bcards:empty{display:none}
.bcard{display:grid;gap:12px;padding:12px;background:var(--surface);border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow-1);transition:border-color .2s,box-shadow .2s}
.bcard:hover{box-shadow:var(--shadow-2)}
.bcard.selected{border-color:var(--plum);box-shadow:0 0 0 3px #6d2e5814}
.bcard img{width:100%;height:220px;object-fit:contain;border-radius:12px;background:var(--surface-2)}
.bcard .hint{font-size:12.5px;font-weight:600;color:var(--ink-2)}
.bcard button{width:100%;min-height:44px;font-size:13px;background:var(--surface);border-color:var(--line-2);color:var(--plum)}
.bcard button:hover:not(:disabled){background:var(--plum);border-color:var(--plum);color:#fff}
.bcard.selected button{background:var(--plum);border-color:var(--plum);color:#fff}
.clothing-workflow{margin-top:24px}
.workflow-explanation{font-size:14px;line-height:1.7;color:var(--ink-2)}
.split-actions{margin-top:18px}
.clothing-workflow>.hint{margin-top:14px}
.clothing-whole{margin-top:20px}
.clothing-whole img{display:block;width:100%;height:280px;object-fit:contain;margin-top:10px;padding:10px;border-radius:14px}
.garment-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:16px;margin-top:22px}
.garment-cards:empty{display:none}
.garment-card{display:grid;gap:10px;align-content:start;padding:14px;border:1px solid var(--line);border-radius:18px;background:#fdfcfa}
.garment-image{display:block;width:100%;height:220px;object-fit:contain;padding:12px;border-radius:12px}
.garment-card h3{font-size:15px}
.garment-card .hint{font-size:12px}
.garment-card button{width:100%;font-size:13px}
.clothes-previews{margin-top:4px}
.clothes-previews .panel{padding:16px;border-radius:16px;box-shadow:none}
.clothes-previews h3{font-size:13px;margin-bottom:12px}
.clothes-previews .checker{min-height:120px;border-radius:10px}
.clothes-previews img{display:block;width:100%;max-height:380px;object-fit:contain}
#wardrobeReady{border-color:var(--plum-line);background:linear-gradient(180deg,#fff,#fdf8fa)}
#wardrobeReady h3{font-family:var(--display);font-size:26px;font-weight:600;margin-bottom:8px}

/* ---------- Step 3: print ---------- */
.print-layout{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:24px;align-items:start;margin-bottom:24px}
.print-controls{display:grid;gap:16px}
.print-controls>.disclosure{margin:0}
.dock{position:static!important;inset:auto!important;z-index:auto!important;width:auto!important;display:grid;gap:18px;cursor:default}
.dockhead{display:flex;align-items:center;justify-content:space-between;gap:12px}
.dockhead h3{font-family:var(--display);font-size:26px;font-weight:600}
#dockSize{margin-left:4px;font-family:var(--ui);font-size:13px;font-weight:700;color:var(--gold);vertical-align:middle}
.dockpaper{position:relative;width:100%;max-width:470px;margin:0 auto;aspect-ratio:297/420;overflow:hidden;background:#fff;border:1px solid var(--line);border-radius:4px;box-shadow:0 2px 4px #2b21290a,0 18px 40px #2b21291a}
.dockpaper canvas{display:block;width:100%;height:100%}
.sheet-empty{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;text-align:center;pointer-events:none}
.sheet-empty>span{font-size:34px;font-weight:300;color:var(--line-2)}
.sheet-empty b{font-size:15px;font-weight:600;color:var(--ink-2)}
.sheet-empty p{font-size:13px;line-height:1.6}
.sheet-error{padding:20px;pointer-events:auto;background:#fff}.sheet-error>span{color:var(--plum);font-weight:700}.sheet-error p{margin:0;max-width:300px}
.docknav{display:flex;align-items:center;justify-content:center;gap:18px;font-size:13px;font-weight:600;color:var(--ink-2)}
.docknav button{width:44px;min-height:40px;padding:8px}
.dockbtns{display:grid;gap:8px}
.dockbtns .row{justify-content:space-between;gap:8px}
#dockZip{min-height:56px;font-size:15px}
.dock .notice{padding:2px 0}
.pieces{display:grid;max-height:520px;overflow-y:auto;padding-right:6px}
.piece{display:flex;align-items:center;gap:12px;min-width:0;padding:12px 0;border-bottom:1px solid var(--line)}
.piece:last-child{border-bottom:0}
.piece canvas{flex-shrink:0;width:48px;height:60px;object-fit:contain;border-radius:8px;background:var(--surface-2)}
.pmeta{flex:1;display:grid;gap:4px;min-width:0;overflow-wrap:anywhere;font-size:12px}
.pmeta b{font-size:13px;font-weight:700}
.pmeta span{font-size:11.5px;color:var(--ink-3)}
.piece button{min-height:40px;padding:6px 8px;background:none;border:0;color:var(--danger);font-size:12px;box-shadow:none}
.piece-coords summary{padding:3px 0;list-style:none;cursor:pointer;font-size:11.5px;color:var(--plum)}
.piece-coords summary::-webkit-details-marker{display:none}
.piece-coords summary::before{content:'+ '}
.piece-coords[open] summary::before{content:'− '}
.piece-coords small{display:block;margin-top:3px;font-size:11.5px;line-height:1.7;color:var(--ink-3);overflow-wrap:anywhere}
.list-empty{padding:10px 0 20px;font-size:13px;color:var(--ink-3)}
.secondary-upload{margin-top:14px}
.canva-heading{margin:18px 0 8px;font-size:13px;font-weight:700;color:var(--ink-2)}
#sheetOut{margin-top:22px}
#sheetOut:empty{display:none}
#sheetOut h2{font-family:var(--ui);font-size:14px;font-weight:700;margin-bottom:14px}
.sheetprev{width:100%;height:auto;background:#fff;border:1px solid var(--line);border-radius:6px}
#bookFrozen{margin-bottom:20px;padding:16px 18px;border-radius:var(--r-md);background:var(--gold-soft)}
.production-gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:20px 0}
.production-item{display:grid;gap:9px;padding:12px;border:1px solid var(--line);border-radius:14px}
.production-item img{width:100%;height:auto;aspect-ratio:2;object-fit:contain;background:var(--surface-2);border-radius:8px}
.production-item a{justify-content:start;font-size:13px}
.production-item b{font-size:14px}
#productionStatus{margin:14px 0;padding:14px;border-radius:var(--r-sm);background:var(--surface-2)}
#bookRehearsal{min-width:0}
#bookRehearsal canvas{max-width:100%;background:var(--surface-2)}
#bookRehearsal h4{margin:22px 0 12px;font-size:15px}
#bookRehearsal>.row>button{min-width:46px}
#rehearsalItem{font-size:13px;color:var(--ink-2)}
#bookRehearsal>.notice{margin-top:16px;padding:18px;border:1px solid var(--line);border-radius:var(--r-md);background:var(--surface-2)}
#bookRehearsal>.notice .field{margin-bottom:14px}
#garmentSize{font-size:12.5px}
#rehearsalStrip{display:flex;gap:8px;max-width:100%;overflow-x:auto;padding:14px 0;scrollbar-width:thin}
#rehearsalStrip button{flex:0 0 78px;padding:4px;border-radius:12px;background:var(--surface);border:2px solid transparent;box-shadow:var(--shadow-1)}
#rehearsalStrip button[aria-pressed=true]{border-color:var(--plum)}

/* ---------- Dialogs ---------- */
.modal{width:calc(100% - 32px);max-width:620px;max-height:calc(100dvh - 36px);overflow-y:auto;padding:32px;border:1px solid var(--line);border-radius:24px;background:var(--surface);color:var(--ink);box-shadow:var(--shadow-3)}
.modal::backdrop{background:#2b212966;-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
.modal-head{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:22px}
.modal-head h2,.modal h2{font-size:34px}
.modal-head .eyebrow{display:none}
.modal p{font-size:14px}
.modal .field{margin:16px 0}
.modal .row{margin:16px 0}
.modal .disclosure{margin-top:16px}
.modal .disclosure-body{gap:12px}
.modal input:not([type=checkbox]){min-height:52px}
.account-modal{max-width:480px}
#adminTools:not(:has(:is(#accountCreate,#accountHF,#bookPublishSection):not([hidden]))){display:none}
#adminTools .account-form{margin:0;padding:18px 0 4px;border-top:1px solid var(--line)}
textarea{display:block;width:100%;min-width:0;padding:12px 14px;border:1px solid var(--line-2);border-radius:14px;background:var(--surface);color:var(--ink);font:inherit;font-size:14px;line-height:1.5;resize:vertical}
textarea:focus{outline:none;border-color:var(--plum);box-shadow:0 0 0 4px #6d2e581a}
html,body,#clothesStep{overflow-anchor:none}
.gen-hint{margin-top:8px;color:var(--ink-2);font-size:13px;line-height:1.5}
.gen-hint.is-error{color:var(--danger)}
.prompt-box{margin:18px 0 0;padding:18px;border:1px solid var(--line);border-radius:20px;background:var(--surface-2)}
.prompt-box h4{margin:0 0 6px;font-size:15px}
.prompt-list{display:grid;gap:10px;margin-top:12px}
.prompt-card{display:grid;gap:8px;padding:14px 16px;border:1px solid var(--line);border-radius:16px;background:var(--surface)}
.prompt-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
.prompt-head b{font-size:14px}
.prompt-head button{min-height:38px;padding:6px 16px;font-size:13px}
.prompt-card summary{cursor:pointer;color:var(--ink-3);font-size:12.5px;font-weight:700}
.prompt-card pre{margin:8px 0 0;white-space:pre-wrap;overflow-wrap:anywhere;font:12.5px/1.6 var(--ui);color:var(--ink-2)}
.wz .prompt-card{position:relative;gap:12px;padding:18px;border:1.5px solid var(--plum-line);border-radius:24px;background:#fff;box-shadow:0 18px 36px -28px #55203f88}
.prompt-title{display:grid;gap:6px;min-width:0}
.prompt-tag{justify-self:start;padding:5px 12px;border-radius:999px;background:linear-gradient(135deg,#86386b,#5a2247);color:#fff;font-size:11.5px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}
.prompt-title b{font-size:14.5px;line-height:1.35}
.prompt-card pre{position:relative;margin:0;padding:22px 18px 16px 18px;border-radius:16px;background:#faf7f9;border:1.5px dashed var(--plum-line);font:13px/1.65 var(--ui);color:var(--ink);white-space:pre-wrap;overflow-wrap:anywhere}
.prompt-card pre::before{content:'ТЕКСТ ПРОМТА';position:absolute;top:-9px;left:14px;padding:0 8px;background:#fff;border-radius:6px;color:var(--plum);font-size:10.5px;font-weight:800;letter-spacing:.14em}
.prompt-p{display:block;margin-top:12px}.prompt-p:first-child{margin-top:0}
.prompt-p em{margin-left:8px;color:#a07a44;font-style:normal;font-size:11.5px;font-weight:800;white-space:nowrap}
.mark-name{padding:1px 4px;border-radius:5px;background:#ffe7a8;font-weight:800;-webkit-box-decoration-break:clone;box-decoration-break:clone}
.mark-rule{padding:1px 4px;border-radius:5px;background:#ffd2f8;font-weight:700;-webkit-box-decoration-break:clone;box-decoration-break:clone}
.prompt-legend{margin:0;font-size:12px;color:var(--ink-3)}.prompt-legend span{font-weight:700;color:var(--ink)}
.prompt-editor{display:grid;gap:12px;margin:12px 0}
.prompt-row{display:grid;gap:8px;padding:12px;border:1px solid var(--line);border-radius:16px;background:var(--surface-2)}
.prompt-row textarea{min-height:140px}
.access-list{display:grid;gap:10px;margin-top:18px}
.tg-message{margin-top:14px;padding:14px 16px;border-radius:16px;background:var(--plum-soft);color:var(--plum-2);font-weight:600;display:grid;gap:10px}
.tg-message a{justify-self:start}
.access-row{display:grid;gap:8px;padding:12px 14px;border:1px solid var(--line);border-radius:16px;background:var(--surface-2)}
.access-row b{font-size:14px}.access-row small{display:block;color:var(--ink-3);font-size:12.5px}
.access-row .row{gap:8px;margin:0}.access-row button{min-height:36px;padding:6px 14px;font-size:12.5px}
#adminTools .account-form:first-child{border-top:0;padding-top:4px}
#accountLogout{margin-top:22px}
.project-dialog-actions{margin:18px 0 6px}
.project-dialog-actions>button{flex:1}
#projectsDialog .project-more .disclosure-body>.text-button{justify-self:start}.account-line{display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:14px}
.account-form{display:grid;gap:12px;margin-top:22px}
.account-form .field{margin:0}
.history-list{display:grid;gap:8px;max-height:300px;margin:14px 0;overflow:auto}
.history-list:empty{display:none}
.history-list button{justify-content:flex-start;text-align:left;font-size:13px;background:var(--surface-2);border:1px solid var(--line);color:var(--plum)}
.order-list{display:grid;margin-bottom:14px}
.order-row{display:grid;grid-template-columns:52px minmax(0,1fr) auto 38px;gap:14px;align-items:center;padding:12px 10px;margin:0 -10px;border-bottom:1px solid var(--line);border-radius:14px}
.order-row.is-current{background:var(--plum-soft);border-bottom-color:transparent}
.order-thumb{display:grid;place-items:center;width:52px;height:64px;border-radius:10px;background:var(--surface-2);overflow:hidden;color:var(--line-2);font-size:20px}
.order-thumb img{width:100%;height:100%;object-fit:contain;background:#fff}
.order-info{display:grid;gap:2px;min-width:0;justify-items:start}
.order-info small{font-size:12.5px;color:var(--ink-3)}
.order-current{margin-top:4px;background:var(--surface);color:var(--plum)}
.order-info>b{min-width:0;font-size:15px;font-weight:600;overflow-wrap:anywhere}
.order-row>button{min-height:38px;padding:7px 14px;font-size:13px}
.projects-empty{padding:14px 0 20px;font-size:14px!important;color:var(--ink-3)}
#projectDialogStatus:empty{display:none}
#projectsDialog .project-more{margin-top:10px;border:0;background:transparent}
#projectsDialog .project-more>summary{min-height:40px;padding:8px 0;font-size:13px;font-weight:600;color:var(--ink-3)}
#projectsDialog .project-more>summary:hover{background:none}
#projectsDialog .project-more>.disclosure-body{padding:12px 0 0}
.project-row-menu{position:relative}
.project-row-menu>summary{display:grid;place-items:center;width:38px;height:38px;border-radius:10px;list-style:none;cursor:pointer;font-size:22px;color:var(--ink-3)}
.project-row-menu>summary::-webkit-details-marker{display:none}
.project-row-menu[open]>summary{background:var(--surface-2)}
.project-row-actions{position:absolute;right:0;top:42px;z-index:30;display:grid;min-width:180px;padding:6px;border:1px solid var(--line);border-radius:14px;background:var(--surface);box-shadow:var(--shadow-3)}
.project-row-actions button{justify-content:flex-start;min-height:42px;padding:9px 12px;border:0;background:none;color:var(--ink);font-size:13px;white-space:nowrap;box-shadow:none}
.project-row-actions button:hover{background:var(--surface-2)}
.project-row-actions button.danger{color:var(--danger)}
#reuseChildChoice{display:block;margin-top:20px;padding:16px;border:1px solid var(--plum-line);border-radius:16px;background:var(--plum-soft)}
#readyChildPreview{grid-row:1/4;width:80px!important;height:130px!important;border-radius:10px;background:#fff}
#readyChildLabel{font-size:13px;font-weight:700;color:var(--plum);overflow-wrap:anywhere}
#reuseChildChoice label{font-size:13px;line-height:1.5;color:var(--ink-2)}
#reuseChildChoice .hint{margin:12px 0 0;font-size:12px}
#reuseChildChoice p{margin:0}
#childPicker{display:flex;gap:10px;overflow-x:auto;padding:2px 2px 12px;margin-bottom:4px;-webkit-overflow-scrolling:touch}
#childPicker button{flex:none;display:grid;gap:4px;justify-items:center;width:78px;min-height:0;padding:6px;background:#fff;color:var(--ink-2);border:2px solid var(--line);border-radius:12px;font-size:11px;font-weight:600;line-height:1.2}
#childPicker button[aria-pressed=true]{border-color:var(--plum);color:var(--plum)}
#childPicker img{width:56px;height:84px;object-fit:contain;border-radius:8px;background:#f5f0ea}
#childPicker span{max-width:66px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#reuseChildChoice #childPicker button{width:78px}
#reuseChildChoice button{width:100%}
#bookOrderError:not([hidden]){margin-top:14px;padding:14px;border-radius:var(--r-sm);background:var(--danger-soft);color:var(--danger)}
#bookOrderSubmit{min-height:54px}

@keyframes spin{to{transform:rotate(360deg)}}
@keyframes pulse{50%{opacity:.3}}
@keyframes enter{from{opacity:.6;transform:translateY(6px)}to{opacity:1;transform:none}}
@keyframes sway{0%,100%{transform:rotate(-6deg) translateY(0)}50%{transform:rotate(-5deg) translateY(-5px)}}
@media(hover:hover) and (pointer:fine){.hero-book{animation:sway 9s ease-in-out infinite}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}

/* ---------- Narrow desktop / tablet: sidebar becomes a top bar ---------- */
@media(max-width:1100px){.workshop{grid-template-columns:220px minmax(0,1fr);column-gap:32px;padding-right:28px}}
@media(max-width:900px){
 .workshop{display:block;padding:0 24px}
 .app-header{position:relative;top:auto;z-index:30;height:auto;flex-direction:row;flex-wrap:wrap;align-items:center;gap:10px;margin:0 -24px;padding:10px 24px;border-right:0;border-bottom:1px solid var(--line);background:#f3ece5f2;-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}
 .app-header .header-actions{display:flex;gap:2px;margin-left:auto}
 .nav-item{flex-direction:column;gap:3px;width:auto;min-height:54px;padding:6px 10px;font-size:11px;font-weight:700}
 .nav-studio{box-shadow:none;background:var(--surface)}
 .member-badge{display:none}
 .step-nav{top:10px}
 .step-nav button{padding:10px 12px;gap:10px}
 .creation-grid,.print-layout{gap:18px}
 .card,.panel{padding:22px}
 .params{grid-template-columns:repeat(2,minmax(0,1fr))}
}
/* ---------- Phone ---------- */
@media(max-width:640px){
 body{font-size:15px}
 .card,.panel,.workshop>*,.creation-grid>*,.print-layout>*{min-width:0;max-width:100%}
 img,canvas,video,svg,pre,table{max-width:100%}
 .workshop{padding:0 16px}
 .app-header{margin:0 -16px;padding:8px 12px 8px 16px;gap:6px}
 .brand{font-size:21px;gap:9px}
 .brand-mark{width:36px;height:36px;font-size:24px;border-radius:11px}
 .brand small{display:none}
 .app-header .header-actions{flex:1 1 100%;min-width:0;margin-left:0;display:flex;gap:2px}
 .nav-item{flex:1 1 0;min-width:0;min-height:50px;padding:5px 2px;font-size:10px;line-height:1.15;text-align:center;overflow-wrap:anywhere}
 .nav-item svg{width:19px;height:19px}
 .workspace-heading{padding:26px 0 4px}
 .workspace-heading h1{font-size:42px}
 .route-grid.simple-start{flex-direction:column;align-items:stretch}
 .simple-start>.route-card{width:100%}
 .step-nav{top:10px;margin:18px 0 24px;border-radius:16px}
 .step-nav button{flex-direction:column;justify-content:center;gap:5px;min-height:62px;padding:8px 4px;font-size:13px;text-align:center}
 .step-nav small{display:none}
 .step-number{width:26px;height:26px;font-size:12px}
 .work-context{margin:-10px 0 20px}
 .section-heading h2{font-size:34px}
 .section-heading p{font-size:14px}
 .card,.panel{padding:20px 18px;border-radius:18px}
 .project-card{padding:22px 18px}
 .project-name-field input,input#cloudTitle{font-size:21px!important;min-height:56px}
 .ready-book-options{margin-top:36px;padding-top:28px}
 #readyBookOptions>summary{font-size:32px;padding:0 0 16px}
 .book-catalog{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
 .book-card{padding:9px;gap:9px}
 .book-art{height:140px}
 .book-card h3{font-size:19px}
 .book-card p{font-size:12px}
 .creation-grid{grid-template-columns:minmax(0,1fr);gap:16px}
 .photo-upload{min-height:230px}.photo-upload img{height:250px}
 .result-stage{min-height:300px}
 .disclosure>summary{flex-wrap:wrap;gap:4px 10px;padding:14px 44px 14px 16px;position:relative;min-height:54px}
 .disclosure>summary::after{position:absolute;right:18px;top:24px}
 .disclosure>summary>span:not(.tag){width:100%}
 .disclosure-body{padding:4px 16px 18px}
 .disclosure .row{display:grid;grid-template-columns:minmax(0,1fr);gap:9px}
 .clothes-intro{flex-wrap:wrap;padding:16px}
 .clothes-intro button{width:100%}
 .bcards,.garment-cards{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
 .bcard{padding:9px;gap:9px}
 .bcard img,.garment-image{height:180px}
 .split-actions{display:grid;grid-template-columns:minmax(0,1fr);gap:10px}
 .print-layout{grid-template-columns:minmax(0,1fr)}
 .params{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}
 .production-gallery,.book-publish-previews{grid-template-columns:minmax(0,1fr)}
 .step-footer{align-items:stretch}
 .step-footer>.primary{flex:1;padding:14px 16px;font-size:14px}
 .step-footer>.text-button{max-width:38%;text-align:left;justify-content:flex-start}
 .app-footer{flex-direction:column;align-items:flex-start;gap:4px;margin-top:40px}
 .modal{padding:22px 18px;border-radius:20px;width:calc(100% - 24px);max-height:calc(100dvh - 24px)}
 .modal-head h2,.modal h2{font-size:28px}
 .modal .row button{flex:1}
 .order-row{grid-template-columns:44px minmax(0,1fr) auto 32px;gap:8px}
 .order-thumb{width:44px;height:56px}
 #reuseChildChoice{padding:12px}
 #readyChildPreview{width:65px!important;height:110px!important}
 #reuseChildChoice .hint{grid-column:1/-1}
 .project-actions{display:grid;grid-template-columns:minmax(0,1fr)}
 #bookRehearsal{padding:16px}
}
/* ---------- Premium layer: only look and motion, no behaviour ---------- */
:root{--ease:cubic-bezier(.22,.8,.24,1);--glass:#ffffffb8;--hair:#efe5de;--paper:#fbf7f3}
body{background:radial-gradient(900px 420px at 78% -140px,#f7e3ea 0%,#fbf7f300 70%),radial-gradient(700px 380px at -8% 12%,#f6ebdd 0%,#fbf7f300 65%),var(--paper);background-attachment:fixed}
::selection{background:#ecd6de;color:var(--plum-2)}
html{scrollbar-width:thin;scrollbar-color:#d9c7cf transparent}
.app-header{background:linear-gradient(180deg,#f8f1eb 0%,#f2e8e1 100%);border-right:1px solid #eadfd7}
.app-header .header-actions button,.app-header .header-actions a{border-radius:14px;transition:background .25s var(--ease),color .25s var(--ease),box-shadow .25s var(--ease),transform .25s var(--ease)}
.app-header .header-actions [aria-current],.app-header .header-actions .is-active{box-shadow:0 1px 0 #fff inset,0 10px 24px -12px #55203f40}
.brand-mark{box-shadow:0 1px 0 #ffffff55 inset,0 10px 22px -6px #55203f66}
@media(min-width:900px){.workspace-heading{padding-top:56px}}
.workspace-heading .eyebrow{letter-spacing:.22em}
.workspace-heading h1{font-size:clamp(52px,6.2vw,80px);line-height:.98;letter-spacing:-.035em;background:linear-gradient(120deg,#2b2129 25%,#6d2e58 100%);-webkit-background-clip:text;background-clip:text;color:transparent}
.workspace-heading p{font-size:16.5px;max-width:560px}
.section-heading h2{font-size:clamp(36px,4.2vw,52px);letter-spacing:-.03em}
button,.btn2{transition:background .25s var(--ease),border-color .25s var(--ease),color .25s var(--ease),box-shadow .25s var(--ease),transform .25s var(--ease);letter-spacing:.005em}
.primary,.simple-start>.route-card{background:linear-gradient(135deg,#7f3a69 0%,#5a2244 100%);border-color:#5a2244;box-shadow:0 1px 0 #ffffff2e inset,0 2px 4px #55203f26,0 16px 32px -12px #6d2e5880}
.primary:hover:not(:disabled),.simple-start>.route-card:hover{background:linear-gradient(135deg,#8a416f 0%,#5f2648 100%);transform:translateY(-1px);box-shadow:0 1px 0 #ffffff38 inset,0 4px 8px #55203f2e,0 22px 40px -14px #6d2e58a0}
.button-secondary,.btn2{border-color:#e6d8dc;box-shadow:0 1px 2px #2b21290a}
.button-secondary:hover:not(:disabled),.btn2:hover{transform:translateY(-1px);box-shadow:0 8px 20px -10px #55203f40}
.card{border-radius:24px;border-color:var(--hair);background:linear-gradient(180deg,#fff 0%,#fffdfc 100%);box-shadow:0 1px 0 #fff inset,0 1px 2px #2b21290a,0 22px 48px -26px #55203f33}
.card-heading h3{font-size:17px;letter-spacing:-.01em}
.tag{background:linear-gradient(180deg,#f8f1ea,#f2e9e0);color:#7a6a60;border:1px solid #eadfd5}
.step-nav{border-radius:22px;background:#f7f0ebd9;border-color:#ebe0d8;box-shadow:0 1px 0 #fff inset,0 18px 40px -22px #55203f40;-webkit-backdrop-filter:blur(14px) saturate(1.2);backdrop-filter:blur(14px) saturate(1.2)}
.step-nav button{border-radius:17px;transition:background .3s var(--ease),color .3s var(--ease),box-shadow .3s var(--ease)}
.step-nav button[aria-current=step]{box-shadow:0 1px 0 #fff inset,0 10px 24px -12px #55203f4d}
.step-nav button[aria-current=step] .step-number{background:linear-gradient(135deg,#7f3a69,#5a2244);box-shadow:0 6px 14px -4px #55203f80}
input:not([type=checkbox]):not([type=range]):not([type=file]):not([type=hidden]),select{border-radius:14px;border-color:#e6d9dd;box-shadow:0 1px 2px #2b21290a inset}
input:not([type=checkbox]):not([type=range]):focus,select:focus{box-shadow:0 0 0 4px #6d2e5820,0 1px 2px #2b21290a inset}
.drop,.photo-upload{border-radius:22px;border-color:#dcc3d0;background:linear-gradient(180deg,#fffafc,#faf1f5);transition:border-color .3s var(--ease),background .3s var(--ease),transform .3s var(--ease)}
.drop:hover,.photo-upload:hover{border-color:var(--plum);transform:translateY(-1px)}
.book-catalog{gap:22px;grid-template-columns:repeat(auto-fill,minmax(250px,1fr))}
.book-card{padding:12px 12px 16px;border-radius:26px;gap:14px;transition:box-shadow .4s var(--ease),transform .4s var(--ease)}
.book-card:not(:has(button:disabled)):hover{transform:translateY(-4px);box-shadow:0 1px 0 #fff inset,0 2px 4px #2b21290a,0 36px 60px -28px #55203f59}
.book-art{height:auto;aspect-ratio:4/3;border-radius:18px;position:relative;background:linear-gradient(150deg,#f6e9ee,#ead7df)}
.book-art::after{content:'';position:absolute;inset:0;border-radius:inherit;box-shadow:inset 0 0 0 1px #ffffff66,inset 0 -40px 50px -30px #55203f30;pointer-events:none}
.book-art>img{position:absolute;inset:0;width:100%;height:100%;transition:transform .8s var(--ease)}
.book-catalog{align-items:stretch}.book-card{grid-template-rows:auto auto 1fr auto}
.book-card:hover .book-art>img{transform:scale(1.045)}
.book-card h3{font-size:27px;letter-spacing:-.02em;padding:0 6px}
.book-card p{padding:0 6px}
.book-card button{margin:0 4px;width:calc(100% - 8px)}
.modal{border-radius:30px;border-color:#efe4dd;box-shadow:0 2px 4px #2b21290d,0 40px 90px -20px #2b212966}
.modal::backdrop{background:radial-gradient(circle at 50% 30%,#55203f40,#2b212980);-webkit-backdrop-filter:blur(10px) saturate(1.1);backdrop-filter:blur(10px) saturate(1.1)}
.modal-head h2,.modal h2{font-size:38px;letter-spacing:-.03em}
@keyframes mbRise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
@keyframes mbPop{from{opacity:0;transform:translateY(16px) scale(.985)}to{opacity:1;transform:none}}
[data-step]:not([hidden]){animation:mbRise .55s var(--ease) both}
.modal[open]{animation:mbPop .4s var(--ease) both}
@media (prefers-reduced-motion:reduce){[data-step]:not([hidden]),.modal[open]{animation:none}.book-art>img,.book-card,button,.btn2,.drop{transition:none}}
.book-art>img[src*="small=1"]{object-position:16% center!important}
/* ---------- Bold type layer ---------- */
:root{--display:"Unbounded","Manrope",sans-serif}
h1,h2{font-weight:700;letter-spacing:-.045em;line-height:1.08}
.workspace-heading h1{font-size:clamp(34px,4.4vw,58px);line-height:1.02;letter-spacing:-.05em}
.workspace-heading p{font-size:16px;line-height:1.65}
.section-heading h2{font-size:clamp(24px,2.8vw,36px)}
.modal-head h2,.modal h2{font-size:26px;letter-spacing:-.04em}
.brand{font-size:18px;font-weight:700;letter-spacing:-.04em}
.brand-mark{font-size:21px;font-weight:700}
.book-card h3{font-size:19px;font-weight:700;letter-spacing:-.035em}
#readyBookOptions>summary{font-size:28px;font-weight:700;letter-spacing:-.045em}
.project-name-field input,input#cloudTitle{font-size:19px!important;font-weight:700}
.dockhead h3,#wardrobeReady h3,.generation-overlay b,.generation-overlay.magic>b{font-size:19px;font-weight:700;letter-spacing:-.03em}
.doll-check b{font-size:16px;font-weight:700}.portrait-guide-title{font-size:15px;font-weight:700}
.hero-note{font-style:normal;font-size:13px;font-weight:700}.hero-book-title{font-size:18px;font-weight:700}
.boot-screen b{font-size:22px;font-weight:700}
button,.btn2{border-radius:999px;font-weight:700;padding-left:24px;padding-right:24px}
.button-icon{border-radius:50%;padding:0}
.text-button{border-radius:8px;padding-left:2px;padding-right:2px}
.primary,.simple-start>.route-card{border-radius:999px}
.eyebrow{display:inline-flex;align-items:center;padding:6px 12px;border-radius:999px;background:var(--gold-soft);color:#8a6330;font-weight:800;letter-spacing:.12em;font-size:10.5px;margin-bottom:16px}
.tag{font-weight:800;letter-spacing:.08em}
.card{border-radius:28px}
.step-nav{border-radius:999px;padding:6px}
.step-nav button{border-radius:999px;padding-left:18px;padding-right:18px}
.step-number{font-weight:800}
.book-card{border-radius:30px}.book-art{border-radius:22px}
.book-card button{border-radius:999px}
.modal{border-radius:32px}
.field{font-weight:700}
.start-choices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:0 0 30px}
.start-card{display:grid;grid-template-rows:auto auto 1fr auto;align-content:start;gap:12px;padding:26px 24px 24px}
.start-card h3{font-family:var(--display);font-size:20px;letter-spacing:-.035em}
.start-card p{font-size:14px;line-height:1.6}
.start-card button{justify-self:start;margin-top:6px}
.start-num{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:var(--gold-soft);color:#8a6330;font-weight:800;font-size:14px}
@media(max-width:900px){.start-choices{grid-template-columns:1fr}.start-card button{justify-self:stretch}}
.workshop:has(#projectStep:not([hidden])):not(:has(#activeOrderCard:not([hidden]))) .step-nav{display:none}
#refDrop{display:none!important}
.scissors-note{display:grid;gap:4px;margin-top:14px;padding:14px 16px;border-radius:18px;background:var(--gold-soft);border:1px solid #efe1c9;font-size:12.5px;color:#7a6446;line-height:1.5}
.scissors-note b{color:#4e3d27;font-size:13px}
.scissors-note em{font-style:normal;font-weight:700;color:#4e3d27}
.info{display:grid;grid-template-columns:minmax(220px,.8fr) minmax(0,1fr);gap:26px;align-items:center;margin-top:18px;padding:20px 24px;border-radius:26px;background:linear-gradient(135deg,#fdf6f8,#f8eef3 55%,#f6eddf);border:1px solid var(--plum-line)}
.info-fig{position:relative;margin:0;height:290px;display:flex;justify-content:center}
.info-halo{position:absolute;inset:3% 10% 0;border-radius:50%;background:radial-gradient(closest-side,#f3d6e1,#f9ebe800)}
.fig-in{position:relative;height:100%;aspect-ratio:1360/2919}
.fig-in>img{display:block;height:100%;width:100%;mix-blend-mode:multiply}
.cal{position:absolute;display:flex;align-items:center;margin-top:-14px}
.cal b{flex:none;padding:7px 13px;border-radius:999px;background:var(--surface);border:1px solid var(--plum-line);font-size:11.5px;font-weight:700;color:var(--plum-2);box-shadow:0 10px 18px -12px #55203f66;white-space:nowrap}
.cal i{flex:none;width:34px;height:0;border-top:1.5px dashed var(--plum);position:relative}
.cal i::after{content:'';position:absolute;top:-5px;width:8px;height:8px;border-radius:50%;background:var(--plum)}
.cal-l i::after{right:-4px}.cal-r i::after{left:-4px}
.chip{display:inline-flex;align-items:center;padding:6px 13px;border-radius:999px;background:var(--gold-soft);color:#8a6330;font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}
.info-text h4{font-family:var(--display);font-size:20px;line-height:1.2;letter-spacing:-.035em;margin:14px 0 16px}
.why{list-style:none;margin:0;padding:0;display:grid;gap:12px;counter-reset:why}
.why li{position:relative;padding-left:44px;font-size:13.5px;line-height:1.5;color:var(--ink-2);counter-increment:why}
.why li::before{content:counter(why);position:absolute;left:0;top:0;width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:var(--plum);color:#fff;font-size:13px;font-weight:800}
.why b{display:block;color:var(--ink);font-size:14px;margin-bottom:2px}
.flow{display:grid;gap:6px;justify-items:start;margin-top:18px}
.flow span{padding:8px 14px;border-radius:999px;background:var(--surface);border:1px solid var(--line);font-size:12.5px;font-weight:700;color:var(--plum-2)}
.flow em{font-style:normal;color:var(--plum);font-weight:800;line-height:1;margin-left:14px}
@container (max-width:640px){.info{grid-template-columns:110px minmax(0,1fr);gap:16px;align-items:start;padding:16px}.info-fig{height:230px}.cal{display:none}
 .info-text h4{font-size:17px;margin:10px 0 12px}.why{gap:9px}.why li{padding-left:36px;font-size:12.5px}.why li::before{width:26px;height:26px;font-size:12px}.why b{font-size:13px}.flow{display:none}}
@container (max-width:380px){.info{grid-template-columns:84px minmax(0,1fr)}.info-fig{height:180px}}
/* The one rule the cutting depends on: a magenta strip between items. A small drawing shows it with a size arrow. */
.gap-rule{display:grid;grid-template-columns:200px minmax(0,1fr);gap:22px;align-items:center;margin-top:14px;padding:18px 22px;border-radius:26px;background:linear-gradient(135deg,#fff4fd,#ffe9fb);border:1.5px solid #ff00ff55;box-shadow:0 18px 36px -28px #ff00ffaa}
.gap-rule svg{display:block;width:100%;height:auto}
.gap-rule .chip{background:#ff00ff;color:#fff}
.gap-rule h4{font-family:var(--display);font-size:19px;line-height:1.2;letter-spacing:-.03em;margin:10px 0 8px}
.gap-rule p{margin:0;font-size:13.5px;line-height:1.55;color:var(--ink-2)}
.gap-rule p b{color:var(--ink)}
.gap-yes-no{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
.gap-yes-no span{padding:7px 12px;border-radius:999px;font-size:12.5px;font-weight:800}
.gap-yes-no .ok{background:#e6f5ea;color:#24703a}.gap-yes-no .bad{background:#fde8ea;color:#a12a3a}
@container (max-width:640px){.gap-rule{grid-template-columns:110px minmax(0,1fr);gap:16px;padding:16px}.gap-rule h4{font-size:16px}.gap-rule p{font-size:12.5px}}
@container (max-width:380px){.gap-rule{grid-template-columns:84px minmax(0,1fr)}}
.resume-card{display:flex;align-items:center;gap:26px;margin-bottom:24px;padding:26px 32px;border-radius:30px;box-shadow:0 22px 44px -32px #55203f55}
.resume-card>img{flex:none;width:96px;height:150px;object-fit:contain;border-radius:16px;background:var(--surface-2)}
.resume-card-body{flex:1;min-width:0}
.resume-card h3{font-family:var(--display);font-size:20px;letter-spacing:-.03em;line-height:1.2;margin:0}
.resume-card p{margin:10px 0 0;font-size:14.5px;color:var(--ink-2)}
.resume-card .row{margin-top:18px}
.resume-card .text-button{margin-top:10px}
.workshop:has(#resumeOrderPanel:not([hidden])) #lastResultRecoveryPanel{display:none}
@media(max-width:720px){.resume-card{flex-direction:column;align-items:flex-start;gap:16px;padding:22px 20px;border-radius:24px}}
/* ---------- Clothes step: three numbered steps, like the landing ---------- */
.wz{list-style:none;margin:0;padding:0;display:grid;gap:16px}
.wz-step{display:grid;grid-template-columns:64px 1fr;gap:22px;align-items:start;padding:30px 34px 32px;border-radius:30px;background:var(--surface);border:1px solid var(--line);box-shadow:0 22px 44px -32px #55203f55}
.wz-n{font-family:var(--display);font-weight:800;font-size:56px;line-height:1;letter-spacing:-.06em;color:var(--rose);-webkit-text-stroke:1.5px #d9a9bf}
.wz-n.sm{font-size:34px;margin-right:6px}
.wz-main{container-type:inline-size;min-width:0}font-family:var(--display);font-size:21px;font-weight:700;letter-spacing:-.04em;line-height:1.15;margin:4px 0 0}
.wz-main>p{margin:10px 0 0;font-size:14.5px;color:var(--ink-2)}
.wz-actions{margin-top:18px}
.wz .prompt-box{margin:16px 0 0;padding:0;border:0;background:none}
.wz .prompt-list{margin-top:0}
.wz .clothes-drop{margin-top:18px;min-height:190px;border-radius:24px}
.wz .processing-notice{margin-top:14px}
.clothing-workflow{border-radius:30px;padding:28px 34px;box-shadow:0 22px 44px -32px #55203f55}
.clothing-workflow .card-heading{justify-content:flex-start;gap:14px;margin-bottom:14px}
@media(max-width:720px){.wz-step{grid-template-columns:1fr;gap:6px;padding:22px 20px 24px;border-radius:24px}.wz-n{font-size:40px}.clothing-workflow{padding:22px 20px}}
.fit-tab-icon.has-pic{overflow:hidden;background:#fff!important}.fit-tab-icon img{width:100%;height:100%;object-fit:contain;padding:3px;display:block}
