/* ---------- «Своя вещь через нейросеть» on phones: stacked blocks instead of two squeezed columns ---------- */
@container (max-width:560px){
 .info{grid-template-columns:1fr;gap:14px;align-items:start;padding:18px 16px 20px;justify-items:stretch}
 .info-fig{height:250px;margin:0 auto}
