 .why{gap:12px}.why li{padding-left:42px;font-size:13.5px}.why li::before{width:28px;height:28px;font-size:13px}.why b{font-size:14px}
 .flow{display:grid}
 .gap-rule{grid-template-columns:1fr;gap:14px;padding:18px 16px 20px;justify-items:stretch}
