 .prompt-card pre{max-height:11em;overflow:hidden;padding:32px 14px 12px}
 .prompt-card pre::before{top:10px;left:14px;padding:0;background:none}
 .prompt-card:not(.open) pre::after{content:'';position:absolute;left:0;right:0;bottom:0;height:64px;border-radius:0 0 16px 16px;background:linear-gradient(#faf7f900,#faf7f9 88%)}
 .prompt-card.open pre{max-height:none}
 .prompt-more{display:block;justify-self:center;min-height:42px;padding:0 18px;border:0;border-radius:999px;background:var(--plum-soft);color:var(--plum);font:700 13.5px var(--ui);box-shadow:none}
}
/* ---------- «Свой образ»: a call-to-action under the fitting room opens a separate full-screen page ---------- */
.own-cta{display:flex;align-items:center;gap:16px;margin:18px 0 0;padding:18px 20px;border-radius:26px;background:linear-gradient(135deg,#fdf6f8,#f8eef3 60%,#f6eddf);border:1px solid var(--plum-line);box-shadow:0 20px 40px -32px #55203f66}
.own-cta-icon{flex:none;display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:var(--surface);color:var(--plum);box-shadow:0 0 0 1px #f0e0e9,0 10px 20px -12px #55203f77}
.own-cta-text{flex:1;min-width:0;display:grid;gap:2px}.own-cta-text b{font:800 17px/1.25 var(--ui);color:var(--ink)}.own-cta-text span{font-size:13px;line-height:1.45;color:var(--ink-2)}
.own-cta .primary{flex:none}
.own-clothes{display:none}
.own-clothes>summary{display:none}
.own-clothes.is-page{display:block;position:fixed;inset:0;z-index:9000;margin:0;border:0;border-radius:0;box-shadow:none;background:var(--paper);overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;animation:ownIn .32s cubic-bezier(.2,.85,.3,1)}
.own-clothes.is-page>.disclosure-body{max-width:820px;margin:0 auto;padding:0 18px calc(48px + env(safe-area-inset-bottom));gap:18px}
html.own-open{overflow:hidden}
.own-bar{position:sticky;top:0;z-index:3;margin:0 -18px;padding:max(10px,env(safe-area-inset-top)) 18px 10px;background:linear-gradient(var(--paper) 78%,#faf7f300)}
.own-back{display:inline-flex;align-items:center;min-height:44px;padding:0 18px;border:0;border-radius:999px;background:var(--surface);color:var(--plum);font:700 14px var(--ui);box-shadow:0 0 0 1px #f0e0e9,0 10px 20px -14px #55203f88}
.own-hero{display:grid;justify-items:start;gap:10px}
.own-hero h2{margin:0;font-family:var(--display);font-size:30px;line-height:1.1;letter-spacing:-.04em}
.own-hero p{margin:0;font-size:14.5px;line-height:1.55;color:var(--ink-2)}
.own-quick{margin:4px 0 2px;padding:0;list-style:none;display:grid;gap:8px;counter-reset:q;width:100%}
.own-quick li{counter-increment:q;position:relative;padding:11px 14px 11px 52px;border-radius:18px;background:var(--surface);border:1px solid var(--line);font-size:14px;font-weight:700;color:var(--ink)}
.own-quick li::before{content:counter(q);position:absolute;left:12px;top:50%;transform:translateY(-50%);display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--plum);color:#fff;font-size:13px;font-weight:800}
.own-gpt{display:inline-flex;align-items:center;min-height:38px;padding:0 16px;border-radius:999px;background:var(--surface);border:1px solid var(--plum-line);color:var(--plum);font:700 14px var(--ui);text-decoration:none;box-shadow:0 10px 20px -14px #55203f66}
.own-clothes .wz-n:not(.sm){display:none}.own-clothes .wz-step{grid-template-columns:1fr;gap:4px;padding:20px 18px 22px}
.own-rule{margin:12px 0 0!important;padding:12px 14px;border-radius:16px;background:#fff0fd;border:1px solid #ff00ff44;font-size:13px!important;line-height:1.5;color:var(--ink)!important}
.why-more{margin-top:16px}
.why-more>.disclosure-body{padding:0 14px 16px}
@keyframes ownIn{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
