 .fit-tabs{position:absolute;left:10px;right:10px;bottom:10px;z-index:9;display:flex;flex-wrap:nowrap;gap:6px;overflow-x:auto;margin:0;padding:6px;border:0;border-radius:999px;background:#ffffffe0;-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);box-shadow:0 0 0 1px #f0e0e9,0 14px 28px -16px #55203f99;scrollbar-width:none;scroll-snap-type:x proximity}
 .fit-tabs::-webkit-scrollbar{display:none}
 .fit-tab{min-height:46px;padding:4px 14px 4px 4px;font-size:13px;white-space:nowrap;scroll-snap-align:center}
