 .fit-grid{position:absolute;z-index:10;right:10px;top:56px;bottom:84px;width:98px;display:flex;flex-direction:column;gap:10px;max-height:none;min-height:0;margin:0;padding:18px 9px;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;border-radius:30px;background:#ffffffeb;-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px);box-shadow:0 0 0 1px #f0e0e9,0 28px 52px -22px #55203fb3;scrollbar-width:none;scroll-snap-type:y proximity;
  -webkit-mask-image:linear-gradient(#0000,#000 16px,#000 calc(100% - 16px),#0000);mask-image:linear-gradient(#0000,#000 16px,#000 calc(100% - 16px),#0000);
  opacity:0;visibility:hidden;pointer-events:none;transform:translateX(30px) scale(.94);transform-origin:right center;transition:opacity .25s,transform .42s cubic-bezier(.2,.9,.3,1.12),visibility 0s .42s}
 .fit-grid::-webkit-scrollbar{display:none}
 .fitting[data-rail=open] .fit-grid{opacity:1;visibility:visible;pointer-events:auto;transform:none;transition:opacity .25s,transform .42s cubic-bezier(.2,.9,.3,1.12),visibility 0s}
 .fit-tile{flex:none;padding:0;scroll-snap-align:center;border-radius:22px}
 .fit-tile-name{display:none}
 .fit-tile-pic{border-radius:22px}
 .fit-tile[aria-pressed=true]::after{top:4px;right:4px}
 .fitting[data-rail=open] .fit-tile{animation:railIn .45s cubic-bezier(.2,.9,.3,1.1) both}
 .fitting[data-rail=open] .fit-tile:nth-child(2){animation-delay:.04s}.fitting[data-rail=open] .fit-tile:nth-child(3){animation-delay:.08s}.fitting[data-rail=open] .fit-tile:nth-child(4){animation-delay:.12s}.fitting[data-rail=open] .fit-tile:nth-child(n+5){animation-delay:.16s}
 .fit-rail-close{position:absolute;z-index:11;right:18px;top:12px;display:grid;place-items:center;width:34px;height:34px;min-height:0;padding:0;border-radius:50%;border:0;background:#fff;color:var(--plum);font-size:20px;line-height:1;box-shadow:0 0 0 1px #f0e0e9,0 8px 16px -8px #55203f88;opacity:0;visibility:hidden;transform:scale(.7);transition:opacity .2s,transform .3s cubic-bezier(.2,.9,.3,1.3),visibility 0s .3s}
 .fitting[data-rail=open] .fit-rail-close{opacity:1;visibility:visible;transform:none;transition:opacity .2s,transform .3s cubic-bezier(.2,.9,.3,1.3),visibility 0s}
}
@keyframes railIn{from{opacity:0;transform:translateX(18px) scale(.9)}to{opacity:1;transform:none}}
