  // ---------- Alignment to the reference mannequin ----------
  // Both images are reduced to ~240 px wide; magenta = mannequin skin, figure = anything that is not white background.
  // We search scale, rotation and shift so that the generation's visible magenta lands on the reference magenta
  // and the reference body is covered by the generation's figure (body + clothes).
  let refImage = null, refMask = null;
  const refInfoEl = document.getElementById('refInfo');
  const alignEl = document.getElementById('align');

  function maskOf(src, maxW) {
    const w0 = src.naturalWidth || src.width, h0 = src.naturalHeight || src.height;
    const f = Math.min(1, maxW / w0);
    const w = Math.max(1, Math.round(w0 * f)), h = Math.max(1, Math.round(h0 * f));
    const c = document.createElement('canvas'); c.width = w; c.height = h;
    const x = c.getContext('2d', { willReadFrequently: true });
    x.drawImage(src, 0, 0, w, h);
    const d = x.getImageData(0, 0, w, h).data;
    const mag = new Uint8Array(w * h), fig = new Uint8Array(w * h);
    const magPts = [];
    let top = h, bottom = -1, figTop = h, figBottom = -1, figL = w, figR = -1, magL = w, magR = -1;
    for (let y = 0; y < h; y++) for (let xx = 0; xx < w; xx++) {
