      if (d[p + 3] <= 10) continue;
      const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
      if (r - g > 80 && b - g > 80) {
        mag[i] = 1; magPts.push((xx + 0.5) / f, (y + 0.5) / f);
