  function alignedCanvas(gen, A) {
    const c = document.createElement('canvas');
    c.width = refMask.w0; c.height = refMask.h0;
    const x = c.getContext('2d');
    x.setTransform(A.m[0], A.m[1], A.m[2], A.m[3], A.m[4], A.m[5]);
    x.imageSmoothingQuality = 'high';
    x.drawImage(gen, 0, 0);
    return c;
  }

  function fitPreview(clothesUrl, score) {
    const panel = document.getElementById('fitPanel'), img = document.getElementById('fit'), sc = document.getElementById('fitScore');
    const c = document.createElement('canvas'); c.width = refMask.w0; c.height = refMask.h0;
    const x = c.getContext('2d');
    x.globalAlpha = 0.45; x.drawImage(refImage, 0, 0); x.globalAlpha = 1;
    const cl = new Image();
    cl.onload = () => { x.drawImage(cl, 0, 0); img.src = c.toDataURL('image/png'); };
    cl.src = clothesUrl;
    const pct = Math.round(score * 100);
    sc.textContent = 'совпадение ' + pct + '%';
    sc.className = 'score ' + (pct >= 95 ? 'good' : pct >= 90 ? 'mid' : 'bad');
    panel.hidden = false;
  }

  function setRef(img, quiet) {
    refImage = img;
    refMask = maskOf(img, 240);
    if (refMask.magCount < 50) {
      refImage = null; refMask = null;
      refInfoEl.textContent = 'На этой картинке нет пурпурного шаблона куклы. Нужен исходный пурпурный шаблон куклы.';
      return;
    }
    refInfoEl.textContent = 'Эталон загружен: ' + refMask.w0 + ' × ' + refMask.h0 + ' px. Результат будет этого же размера.';
    if (!quiet) process();
  }

  function loadRef(file) {
    if (!file || !file.type.startsWith('image/')) return;
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        setRef(img);
        queueProjectSave();
        try { localStorage.setItem('refMannequin', reader.result); } catch (e) { refInfoEl.textContent += ' (Запомнить не удалось — загрузи заново при следующем открытии.)'; }
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  }

