  function processNow() {
    if (!currentImage) return;
    const t = Number(tol.value);
    tolVal.textContent = t;
    try {
      if(!hasMagentaMannequin(currentImage)){
        const r=cleanLooseSheet(currentImage);lastResult=r;outImg.src=r.url;outImg.hidden=false;saveBtn.disabled=false;
        document.getElementById('fitPanel').hidden=true;document.getElementById('clothesDiagnostics').textContent='Шаблона куклы нет: удалён внешний белый фон. Размеры исходные, без подгонки к кукле.';
        statusEl.textContent='Лист без шаблона куклы: нарезаем отдельные предметы. Посадку проверяй на примерке.';return r;
      }
      let source = currentImage, A = null;
      if (refMask && alignEl.checked) {
        A = findAlignment(currentImage);
        if (A) source = alignedCanvas(currentImage, A);
      }
      const r = removeMagenta(source, t);
      lastResult = r;
      document.getElementById('addOutfit').disabled = document.getElementById('addOutfit2').disabled = !(refMask && A);
      outImg.src = r.url; outImg.hidden = false;
      saveBtn.disabled = false;
      let msg = 'Удалено пикселей: ' + r.removed + ' из ' + r.total + '. Если пурпурные пятна остались, подними допуск; если край одежды съело, опусти.';
      if (A) {
        fitPreview(r.url, A.score);
        const pct = Math.round(A.score * 100);
        msg = 'Подогнано под эталон: масштаб ' + (A.scale * 100).toFixed(1) + '%, поворот ' + A.angle.toFixed(1) + '°, совпадение ' + pct + '%. '
          + (pct >= 95 ? 'Можно брать.' : pct >= 90 ? 'Проверь рукава и брючины на примерке.' : 'Поза сильно отличается — лучше перегенерировать.')
          + ' PNG того же размера, что эталон: в Canva ставь его ровно поверх куклы. ' + msg;
      } else {
        document.getElementById('fitPanel').hidden = true;
        if (refMask && alignEl.checked) msg = 'Подогнать не вышло: на генерации не найден пурпурный шаблон куклы. ' + msg;
      }
      document.getElementById('clothesDiagnostics').textContent=msg;
      const percent=A?Math.round(A.score*100):null;
      statusEl.textContent=A?'Одежда готова. Совпадение с эталоном: '+percent+'%. '+(percent>=95?'Проверь примерку и добавь образ на лист.':percent>=90?'Проверь рукава и брючины перед добавлением.':'Поза заметно отличается. Лучше создать новый образ.'):'Шаблон куклы убран. Проверь результат перед добавлением на лист.';
