  function process() {
    if(!currentImage)return;
    // The result is rebuilt from scratch: hold the page height and the scroll position so the screen does not jump while it is empty.
    const step=document.getElementById('clothesStep'),keepY=window.scrollY;step.style.minHeight=step.offsetHeight+'px';
    // Put the page back every frame while the result is rebuilt (and a moment after), unless the person scrolls on their own.
    let hold=true,until=Infinity;const release=()=>{hold=false;};
    for(const ev of ['touchstart','wheel','keydown'])window.addEventListener(ev,release,{once:true,passive:true});
    (function keep(){if(!hold||performance.now()>until)return;if(Math.abs(window.scrollY-keepY)>1)window.scrollTo({top:keepY,behavior:'instant'});requestAnimationFrame(keep);})();
    const ticket=++clothesRenderTicket;resetClothingPlan();setClothesBusy(true);
    requestAnimationFrame(()=>setTimeout(async()=>{if(ticket!==clothesRenderTicket){hold=false;return;}try{const result=processNow();if(result)await prepareClothing(result,safeName(fileBase||'obraz'));}finally{setClothesBusy(false);updateClothesUI();refreshClothingActions();step.style.minHeight='';if(hold){window.scrollTo({top:keepY,behavior:'instant'});until=performance.now()+700;}}},0));
  }

  function loadFile(file) {
    if (!file || !file.type.startsWith('image/')) {
      statusEl.textContent = 'Нужна картинка (PNG или JPG).';
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        currentImage = img;
        srcImg.src = img.src; srcImg.hidden = false;
        process();
      };
      img.onerror=()=>{setClothesBusy(false);statusEl.textContent='Не удалось открыть картинку. Попробуй PNG или JPG.';};img.src = reader.result;
    };
    reader.onerror=()=>{setClothesBusy(false);statusEl.textContent='Не удалось прочитать файл.';};reader.readAsDataURL(file);
  }

  fileInput.addEventListener('change', e => handleFiles([...e.target.files]));
  // The slider only moves the number while it is dragged; the picture is rebuilt once, when the finger is lifted.
  tol.addEventListener('input', () => { tolVal.textContent = tol.value; });
  tol.addEventListener('change', process);
  document.getElementById('halo').addEventListener('change', process);
