  const sheetPieces = [];
  let outfitCount = 0;
  let lastResult = null;

  // ---- downloads that work both inside Claude and in the offline file ----
  async function saveBlob(name, blob) {
    let dl = null;
    try { if (typeof claude !== 'undefined' && claude && claude.use) dl = await claude.use('downloads'); } catch (e) { dl = null; }
    if (dl) { await dl.save({ filename: name, data: blob }); return; }
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = name;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 30000);
  }
