  // ---- split one processed image (in the doll frame) into pieces ----
  // A pair of shoes shares one film window. The gap between the feet grows with the doll, so the joining distance grows too
  // (6 mm at the standard 160 mm doll, as before); otherwise a tall doll loses the second shoe from the print.
  const pairJoinMM = () => 6 * Math.max(1, (Number(document.getElementById('dollMM')?.value) || 160) / 160);
  function splitPieces(frame, mmPerPx, label, loose = false, loosePair = false) {
    const paperOff = Number(document.getElementById('paperOff').value) || 0;
    const filmOff = Number(document.getElementById('filmOff').value) || 0;
    const sf = mmPerPx * K;                      // work px per source px
    const P = Math.ceil((Math.max(filmOff, 0) + 8) * K); // padding so contours never touch the border
    const fw = frame.width, fh = frame.height;
    const w = Math.ceil(fw * sf) + 2 * P, h = Math.ceil(fh * sf) + 2 * P;
    const wc = document.createElement('canvas'); wc.width = w; wc.height = h;
    const wx = wc.getContext('2d', { willReadFrequently: true });
    wx.setTransform(sf, 0, 0, sf, P, P); wx.drawImage(frame, 0, 0);
    const d = wx.getImageData(0, 0, w, h).data;
    const alpha = new Uint8Array(w * h);
    for (let i = 0; i < w * h; i++) alpha[i] = d[i * 4 + 3] > 60 ? 1 : 0;
    const closed = closeMask(alpha, w, h, 0.4 * K);
    const { lab, comps } = components(closed, w, h);
    let parts = comps.filter(c => c.area > (loose ? 0.2 : 40) * K * K); // drop specks < 40 mm²
    if (!parts.length) return [];
    const top = Math.min(...parts.map(c => c.minY)), bot = Math.max(...parts.map(c => c.maxY));
    const maxA = Math.max(...parts.map(c => c.area));
    const footY = P + fh * 0.83 * sf;
    const shoes = loose ? [] : parts.filter(c => c.cy >= footY && (parts.length === 2 || c.area < 0.3 * maxA));
    const groups = [];
    const rest = parts.filter(c => !shoes.includes(c)).sort((a, b) => a.cy - b.cy);
    if (loosePair) groups.push({ comps: rest, pair: true }); else
    rest.forEach(c => groups.push({ comps: [c] }));
    if (shoes.length >= 2) groups.push({ comps: shoes, pair: true }); else shoes.forEach(c => groups.push({ comps: [c] }));
    groups.sort((a, b) => Math.min(...a.comps.map(c => c.cy)) - Math.min(...b.comps.map(c => c.cy)));
    let nTop = 0;
    const out = [];
    for (const g of groups) {
      const ids = new Set(g.comps.map(c => c.id));
      const m = new Uint8Array(w * h);
      for (let i = 0; i < w * h; i++) if (ids.has(lab[i])) m[i] = 1;
      const paper = grow(m, w, h, paperOff * K);
      const filmCount = f => components(f, w, h).comps.filter(c => c.area > 20).length;
      let film = grow(g.pair ? closeMask(m, w, h, pairJoinMM() * K) : m, w, h, filmOff * K);
