      filmC[0].forEach(p => { minX = Math.min(minX, p[0]); minY = Math.min(minY, p[1]); maxX = Math.max(maxX, p[0]); maxY = Math.max(maxY, p[1]); });
      const toMM = (p) => [(p[0] - minX) / K, (p[1] - minY) / K];
