      const pxPerMm = 1 / mmPerPx;
      const pc = document.createElement('canvas'); pc.width = Math.ceil(wmm * pxPerMm); pc.height = Math.ceil(hmm * pxPerMm);
      const px = pc.getContext('2d');
      const x0 = (minX - P) / sf, y0 = (minY - P) / sf;  // film box origin in source px
      px.drawImage(frame, -x0, -y0);
      px.globalCompositeOperation = 'destination-in';
      px.setTransform(1 / sf, 0, 0, 1 / sf, -x0 - P / sf, -y0 - P / sf); px.drawImage(keepMask, 0, 0);
