    const ringExtra = Math.max(0, ringMM() - RING_DEFAULT); // a wider ring sticks out further beyond the pieces
    // SIL_GAP: the red ring stays a few mm inside the frame line instead of touching it.
    const mx = Math.max(margin, SIL_SAFE_X + SIL_GAP + ringExtra), my = Math.max(margin, SIL_SAFE_Y + SIL_GAP + ringExtra);
    const tryPlace = (s, w, h) => {
