  function renderSheet(sh, SW, SH, pxPerMm, withCuts, crop) {
    const c = document.createElement('canvas'); c.width = Math.round((crop ? crop.w : SW) * pxPerMm); c.height = Math.round((crop ? crop.h : SH) * pxPerMm);
    const x = c.getContext('2d');
