  const f3 = (v) => (Math.round(v * 1000) / 1000).toString();
  // With `crop` the coordinates start at the corner of the cut area and the frame is exactly that area (the same size as the print PNG).
  function makeDXF(sh, SW, SH, crop) {
    if (crop) { SW = crop.w; SH = crop.h; }
