    const L = ['0', 'SECTION', '2', 'HEADER', '9', '$INSUNITS', '70', '4', '0', 'ENDSEC', '0', 'SECTION', '2', 'ENTITIES'];
    const poly = (pts, layer, color) => {
      L.push('0', 'POLYLINE', '8', layer, '62', String(color), '66', '1', '70', '1', '10', '0', '20', '0', '30', '0');
      pts.forEach(p => L.push('0', 'VERTEX', '8', layer, '10', f3(p[0]), '20', f3(SH - p[1]), '30', '0'));
