  function canvaPos(p) {
    const X = Number(document.getElementById('cvX').value) || 0, Y = Number(document.getElementById('cvY').value) || 0, W = Number(document.getElementById('cvW').value) || 1;
    const k = W / p.box.fw, r = (v) => (Math.round(v * 10) / 10).toString().replace('.', ',');
    return { x: r(X + p.box.x * k), y: r(Y + p.box.y * k), w: r(p.box.w * k), h: r(p.box.h * k) };
  }
  function renderPieceList() {
