  // Several mannequins side by side in one picture: cut between figures at empty columns,
  // so each figure is aligned to the reference on its own.
  async function splitMannequinImages(img) {
    const W = img.naturalWidth || img.width, H = img.naturalHeight || img.height;
    const c = document.createElement('canvas'); c.width = W; c.height = H;
    const x = c.getContext('2d', { willReadFrequently: true }); x.drawImage(img, 0, 0);
    const d = x.getImageData(0, 0, W, H).data, ink = new Uint32Array(W), mag = new Uint32Array(W);
    for (let y = 0; y < H; y++) for (let xx = 0; xx < W; xx++) {
      const i = (y * W + xx) * 4; if (d[i + 3] <= 10) continue;
      const r = d[i], g = d[i + 1], b = d[i + 2]; if (Math.min(r, g, b) >= 235) continue;
