    const t = Number(tol.value), lines = [];
    let ok = 0;
    for (let i = 0; i < files.length; i++) {
      const f = files[i];
      statusEl.textContent = 'Обрабатываю ' + (i + 1) + ' из ' + files.length + ': ' + f.name + '…';
      await new Promise(r => setTimeout(r, 30));
