  const toBlob = (im) => new Promise(res => { const c = document.createElement('canvas'); c.width = im.naturalWidth || im.width; c.height = im.naturalHeight || im.height; const x = c.getContext('2d'); x.fillStyle = '#fff'; x.fillRect(0, 0, c.width, c.height); x.drawImage(im, 0, 0); c.toBlob(res, 'image/png'); });
  async function upload(blob, name) {
    const fd = new FormData(); fd.append('image', blob, name); fd.append('overwrite', 'true');
    const r = await fetch(api('/upload/image'), { method: 'POST', body: fd });
    if (!r.ok) throw new Error('загрузка картинки: ' + r.status);
    const j = await r.json(); return j.subfolder ? j.subfolder + '/' + j.name : j.name;
  }
  function buildPrompt(bodyName, headName, seed) {
    const p = JSON.parse(JSON.stringify(gWorkflow));
    const ids = Object.keys(p), title = (id) => ((p[id]._meta && p[id]._meta.title) || '').toLowerCase();
    const loads = ids.filter(id => p[id].class_type === 'LoadImage');
    let bodyId = loads.find(id => /body|тело|base|target/.test(title(id))), headId = loads.find(id => /head|голов|ref|face/.test(title(id)) && id !== bodyId);
    if (!bodyId || !headId) { [bodyId, headId] = loads.slice().sort((a, b) => Number(b) - Number(a)); }
    if (!bodyId || !headId) throw new Error('в схеме не нашёл два узла Load Image');
    p[bodyId].inputs.image = bodyName; p[headId].inputs.image = headName;
    // prompt: add the "do not touch the body" line
    const extra = ' keep everything below the neck exactly unchanged: same arms, hands, body, clothes, legs, feet. keep the whole head with hair inside the frame.';
    ids.forEach(id => { const inp = p[id].inputs || {}; Object.keys(inp).forEach(k => { if (typeof inp[k] === 'string' && /head_swap/i.test(inp[k]) && !inp[k].includes('below the neck')) inp[k] += extra; }); });
    // seed
    ids.forEach(id => { const inp = p[id].inputs || {}; ['seed', 'noise_seed'].forEach(k => { if (typeof inp[k] === 'number') inp[k] = seed; }); });
    // output size in the doll's proportions (multiples of 32, ~2 MP)
    const ar = gTemplate.width / gTemplate.height, mp = 2.0e6;
    let H = Math.round(Math.sqrt(mp / ar) / 32) * 32, W = Math.round(H * ar / 32) * 32;
    ids.forEach(id => { if (p[id].class_type === 'EmptyLatentImage' || /EmptyLatent|EmptySD3|EmptyQwen/i.test(p[id].class_type)) { p[id].inputs.width = W; p[id].inputs.height = H; } });
    return p;
  }
  function pickOutput(hist, prompt) {
    const outs = hist.outputs || {}; let best = null;
    Object.keys(outs).forEach(id => {
      (outs[id].images || []).forEach(img => {
        const ct = (prompt[id] && prompt[id].class_type) || '';
        const rank = /^SaveImage/.test(ct) ? 3 : img.type === 'output' ? 2 : /Preview/.test(ct) ? 0 : 1;
        if (!best || rank > best.rank) best = { rank, img };
      });
    });
    return best && best.img;
  }
  async function generate() {
    if (gBusy) return; gBusy = true; gInfoRender();setGenerationBusy(true);
    const t0 = Date.now(), tick = setInterval(() => { G.status.textContent = G.status.dataset.stage + ' · ' + Math.round((Date.now() - t0) / 1000) + ' с'; }, 1000);
    const stage = (s) => { G.status.dataset.stage = s; G.status.textContent = s; };
    try {
      stage('Отправляю куклу и фото на сервер…');
      const bodyName = await upload(gTemplate._file || await toBlob(gTemplate), 'kukla_shablon.png');
      const headName = await upload(gPhotoFile, 'zakaz_' + Date.now() + '.' + ((gPhotoFile.name.split('.').pop() || 'png').toLowerCase()));
      const prompt = buildPrompt(bodyName, headName, Math.floor(Math.random() * 2 ** 31));
      stage('Ставлю в очередь…');
      const q = await fetch(api('/prompt'), { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ prompt, client_id: 'kukla-page' }) });
      const qj = await q.json().catch(() => ({}));
      if (!q.ok) throw new Error('сервер не принял схему: ' + (qj.error && qj.error.message || q.status) + (qj.node_errors ? ' · ' + JSON.stringify(qj.node_errors).slice(0, 300) : ''));
      stage('Генерация на сервере…');
      let hist = null;
      for (let i = 0; i < 600; i++) {
        await new Promise(r => setTimeout(r, 2000));
        const h = await fetch(api('/history/' + qj.prompt_id)); const hj = await h.json();
        if (hj[qj.prompt_id]) { hist = hj[qj.prompt_id]; if (hist.status && hist.status.status_str === 'error') throw new Error('ошибка на сервере: ' + JSON.stringify(hist.status.messages || '').slice(0, 300)); if (hist.outputs && Object.keys(hist.outputs).length) break; }
      }
      const img = hist && pickOutput(hist, prompt);
      if (!img) throw new Error('сервер не вернул картинку');
      stage('Забираю результат…');
      const blob = await (await fetch(api('/view?filename=' + encodeURIComponent(img.filename) + '&subfolder=' + encodeURIComponent(img.subfolder || '') + '&type=' + (img.type || 'output')))).blob();
      const url = URL.createObjectURL(blob); const im = new Image();
      await new Promise((res, rej) => { im.onload = res; im.onerror = () => rej(new Error('картинка не открылась')); im.src = url; });
      // to the doll's frame and size
      const c = document.createElement('canvas'); c.width = gTemplate.width; c.height = gTemplate.height;
      c.getContext('2d').drawImage(im, 0, 0, c.width, c.height);
      gResult = c; G.out.src = c.toDataURL('image/png'); G.out.hidden = false;
      queueProjectSave();
      G.save.disabled = false; G.add.disabled = false; G.cmp.disabled = false;
      clearInterval(tick); G.status.textContent = 'Готово за ' + Math.round((Date.now() - t0) / 1000) + ' с. Проверь «Сравнить с эталоном», потом «Добавить на лист».';
    } catch (err) {
      clearInterval(tick);
      const m = String(err && err.message || err);
      G.status.textContent = 'Не получилось: ' + m + (/Failed to fetch|NetworkError|Load failed/i.test(m) ? ' — сервер выключен, неверный адрес/токен или на сервере не включён CORS (запусти ustanovka_bfs.sh ещё раз).' : '');
    } finally { clearInterval(tick); gBusy = false; gInfoRender();setGenerationBusy(false); }
  }
  // ---- Hugging Face Space (Gradio REST API) ----
  function spaceUrl() {
    const v = gSpace.value.trim();
    if (/^https?:\/\//.test(v)) return v.replace(/\/+$/, '');
    const [u, n] = v.split('/'); if (!u || !n) throw new Error('имя Space в виде пользователь/имя');
    return 'https://' + (u + '-' + n).toLowerCase().replace(/[^a-z0-9-]/g, '-') + '.hf.space';
  }
  const hfHeaders = () => (gHfTok.value.trim() ? { Authorization: 'Bearer ' + gHfTok.value.trim() } : {});
  function newGenerationRequestId() {
    const b=crypto.getRandomValues(new Uint8Array(16));
    return [...b].map(x=>x.toString(16).padStart(2,'0')).join('');
  }
  // browser-face-check-v1
  var browserFaceFile=null, browserFaceReady=false, browserFaceTask=null, browserFaceModel=null;
  function loadBrowserFaceModel(){
    if(!browserFaceModel)browserFaceModel=(async()=>{
      const base='https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21';
      const {FaceDetector,FilesetResolver}=await import(base+'/vision_bundle.mjs');
      return FaceDetector.createFromOptions(await FilesetResolver.forVisionTasks(base+'/wasm'),{
        baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/face_detector/blaze_face_short_range/float16/1/blaze_face_short_range.tflite',delegate:'CPU'},
        // Real portraits score 0.93–0.98; the magenta mannequin head scored 0.71, so keep a clear margin.
        runningMode:'IMAGE',minDetectionConfidence:0.85
      });
    })();
    return browserFaceModel;
  }
  async function checkPhotoBeforeGeneration(file){
    if(file===browserFaceFile&&browserFaceTask)return browserFaceTask;
    browserFaceFile=file;browserFaceReady=false;
    browserFaceTask=(async()=>{
      if(!file)throw Error('Выбери фото ребёнка.');
      if(file.size>15728640)throw Error('Выбери фото меньше 15 МБ.');
      G.status.textContent='Проверяем лицо на фото…';
      let url;
      try{
        let detector;
        try{detector=await Promise.race([loadBrowserFaceModel(),new Promise((_,reject)=>setTimeout(()=>reject(Error('timeout')),45000))]);}
        catch(_){ // the check itself cannot run here (old phone, blocked script): let the person go on instead of locking the button
          if(file!==gPhotoFile)throw Error('Фото изменилось.');browserFaceModel=null;browserFaceReady=true;
          G.status.textContent='Проверка лица на этом устройстве недоступна, фото не проверено. Куклу создать можно.';return;
        }
        const im=new Image();url=URL.createObjectURL(file);im.src=url;await im.decode();
        if(file!==gPhotoFile)throw Error('Фото изменилось.');
        if(im.naturalWidth*im.naturalHeight>40000000)throw Error('Выбери фото до 40 мегапикселей.');
        const c=document.createElement('canvas'),k=Math.min(1,1024/Math.max(im.naturalWidth,im.naturalHeight));
        c.width=Math.round(im.naturalWidth*k);c.height=Math.round(im.naturalHeight*k);
        c.getContext('2d').drawImage(im,0,0,c.width,c.height);
        const faces=detector.detect(c).detections;
        if(!faces.length)throw Error('Лицо не найдено. Выбери портрет ребёнка.');
        if(faces.length!==1)throw Error('На фото несколько лиц. Нужен один ребёнок.');
        if(faces[0].boundingBox.width/c.width<0.12||faces[0].boundingBox.width/k<80)throw Error('Лицо слишком маленькое. Выбери крупный портрет.');
        browserFaceReady=true;
        G.status.textContent='Одно лицо найдено. Можно создать куклу.';
      }catch(e){
        if(file===gPhotoFile){browserFaceReady=false;browserFaceModel=null;}
        throw e;
      }finally{if(url)URL.revokeObjectURL(url);}
    })();
    return browserFaceTask;
  }

  async function generateHF() {
    if (gBusy) return; gBusy = true; gInfoRender();setGenerationBusy(true);
    const t0 = Date.now(); let stage = 'Загружаю фотографии…';
    const tick = setInterval(() => { G.status.textContent = stage + ' · ' + Math.round((Date.now() - t0) / 1000) + ' с'; }, 1000);
    let url = null;
    try {
      stage='Подготавливаю генерацию…';const end=Date.now()+12000;while((cloudBusy||projectBusy||projectRestoring)&&Date.now()<end)await new Promise(r=>setTimeout(r,100));
      // A slow or hung save must never block the doll: after a short wait we go on, the project is saved again once the result is ready.
      if(!cloudBusy&&!projectRestoring&&(cloudDirty||!cloudProject)){cloudDirty=true;try{await Promise.race([cloudSave(),new Promise(r=>setTimeout(r,20000))]);}catch(_){}}
      rememberActive('2');if(cloudProject?.id)markGeneration(cloudProject.id);
      const fd = new FormData();if(cloudProject?.id)fd.append('projectId',cloudProject.id); fd.append('body', await toBlob(gTemplate), 'body.png');fd.append('head', gPhotoFile, gPhotoFile.name || 'head.png');
      await checkPhotoBeforeGeneration(gPhotoFile);fd.append('attemptId',newGenerationRequestId());
      const job = await accountAPI('hf.start', { method: 'POST', body: fd });
      if(job.generation){generationStatus=job.generation;renderGenerationQuota();}
      stage = 'Нейросеть создаёт куклу. Очередь может занять несколько минут…';
      // The server keeps working when the phone is put to sleep or the browser is minimised: ask again for the same job until it is ready.
      let done = null;
      for (;;) {
        try { done = await accountAPI('hf.result&job=' + job.job); break; }
        catch (e) {
          const waiting = !e.status || e.status === 504 || /Сервер не ответил|ещё идёт/.test(e.message || '');
          if (!waiting || Date.now() - t0 > 20 * 60000) throw e;
          stage = 'Нейросеть продолжает создавать куклу…';
          await new Promise(resolve => { if (!document.hidden) { setTimeout(resolve, 2000); return; } const back = () => { if (!document.hidden) { document.removeEventListener('visibilitychange', back); setTimeout(resolve, 500); } }; document.addEventListener('visibilitychange', back); });
        }
      }
      stage = 'Забираю готовую куклу…';
      const response = await fetch('api.php?action=hf.image&job=' + job.job, { cache: 'no-store' });
      if (!response.ok) { const e = await response.json().catch(() => ({}));throw new Error(e.error || 'Не удалось скачать результат'); }
      url = URL.createObjectURL(await response.blob());const image = new Image();image.src = url;await image.decode();
      const canvas = document.createElement('canvas');canvas.width = image.naturalWidth;canvas.height = image.naturalHeight;canvas.getContext('2d').drawImage(image, 0, 0);
      clearInterval(cmpTimer);cmpOn = false;G.cmp.textContent = 'Сравнить с эталоном';
      gResult = canvas;resultJobId=job.job;clearGenerationMark();G.out.src = canvas.toDataURL('image/png');G.out.hidden = false;G.save.disabled = G.add.disabled = G.cmp.disabled = false;queueProjectSave();
      G.status.textContent = 'Готово за ' + Math.round((Date.now() - t0) / 1000) + ' с, seed ' + done.seed + '. Получен цельный результат Hugging Face. Можно добавить куклу на лист.';
      const pendingBook=personalization?.pending;autoInstallDoll();if(pendingBook)setStage('4');rememberActive();try{await rememberReusableChild();}catch(e){G.status.textContent+=' Кукла готова, но отдельное сохранение для других книг не удалось: '+e.message;}
    } catch(e) { G.status.textContent = e.message || 'Не удалось получить картинку.'; void refreshGenerationStatus(); }
    finally { clearInterval(tick);if(url)URL.revokeObjectURL(url);gBusy = false;gInfoRender();setGenerationBusy(false); }
  }
  document.getElementById('gRecover').addEventListener('click', async () => {
    if(personalization?.pending){G.status.textContent='В новой книге сначала создай куклу по новому фото. Восстановление прежней генерации здесь отключено.';return;}
