  // Background trapped inside the doll's outline by flyaway hair (by an ear, between a braid and the neck, an armpit): pure white
  // pockets the background flood never reaches. Only pure white near the outline goes; the white underwear is never quite that white.
  function clearWhitePockets(canvas){
    const W=canvas.width,H=canvas.height,N=W*H,ctx=canvas.getContext('2d',{willReadFrequently:true}),img=ctx.getImageData(0,0,W,H),d=img.data;
    const pure=new Uint8Array(N),near=new Uint8Array(N);
    for(let i=0;i<N;i++){const p=i*4;if(d[p+3]<200)continue;const mn=Math.min(d[p],d[p+1],d[p+2]),mx=Math.max(d[p],d[p+1],d[p+2]);if(mn>=235&&mx-mn<=20){near[i]=1;if(mn>=245&&mx-mn<=10)pure[i]=1;}}
    // steps from every pixel to the nearest removed one (only up to maxD)
    const maxD=Math.round(W*0.1),dist=new Uint16Array(N).fill(65535),q=new Int32Array(N);let head=0,tail=0;
    for(let i=0;i<N;i++)if(d[i*4+3]<=10){dist[i]=0;q[tail++]=i;}
    const reach=(j,nd)=>{if(dist[j]>nd){dist[j]=nd;q[tail++]=j;}};
    while(head<tail){const i=q[head++],nd=dist[i]+1;if(nd>maxD)continue;const x=i%W;if(x>0)reach(i-1,nd);if(x<W-1)reach(i+1,nd);if(i>=W)reach(i-W,nd);if(i<N-W)reach(i+W,nd);}
    const kill=new Uint8Array(N),seen=new Uint8Array(N);let removed=0;
    for(let s0=0;s0<N;s0++){
      if(!pure[s0]||seen[s0])continue;
      head=0;tail=0;seen[s0]=1;q[tail++]=s0;let md=65535;
      const take=j=>{if(pure[j]&&!seen[j]){seen[j]=1;q[tail++]=j;}};
      while(head<tail){const i=q[head++];if(dist[i]<md)md=dist[i];const x=i%W;if(x>0)take(i-1);if(x<W-1)take(i+1);if(i>=W)take(i-W);if(i<N-W)take(i+W);}
      if(tail>=30&&tail<=0.01*N&&md<=maxD){for(let k=0;k<tail;k++)kill[q[k]]=1;removed+=tail;}
    }
    if(!removed)return 0;
    // the soft edge of a pocket (near white, a few pixels) goes with it
    for(let pass=0;pass<3;pass++){const nx=new Uint8Array(kill);for(let i=0;i<N;i++){if(kill[i])continue;if(!near[i])continue;const x=i%W;if((x>0&&kill[i-1])||(x<W-1&&kill[i+1])||(i>=W&&kill[i-W])||(i<N-W&&kill[i+W]))nx[i]=1;}kill.set(nx);}
    for(let i=0;i<N;i++)if(kill[i])d[i*4+3]=0;
    ctx.putImageData(img,0,0);return removed;
  }
  function installGeneratedDoll() {
    if(!gResult||!refMask)throw new Error('Нужны готовая кукла и эталон.');
    // The pockets are only a fallback for a doll that came without the background-removal model (it never leaves any, and on a
    // pure white T-shirt the fallback would punch holes).
    const r=removeMagenta(gResult,Number(tol.value));if(!r.cutOut)clearWhitePockets(r.canvas);
    const prepared=splitPieces(r.canvas,refMmPerPx()*(refMask.w0/r.canvas.width),'kukla');
    if(prepared.length!==1)throw new Error('На изображении найдена не одна цельная кукла. Попробуй другой вариант; одежда осталась без изменений.');
    const indices=sheetPieces.map((p,i)=>isDollPiece(p)?i:-1).filter(i=>i>=0);
    if(indices.length){for(const i of indices)sheetPieces[i]={...prepared[0],name:sheetPieces[i].name,role:'doll'};}
    else {let name='kukla_detal',k=2;while(sheetPieces.some(p=>p.name===name))name='kukla_detal_'+k++;for(let i=0;i<Math.max(1,bookLayout?.dollSlots?.length||0);i++)sheetPieces.push({...prepared[0],name:i?name+'_'+(i+1):name,role:'doll'});}
    personalization=null;sheetOut.replaceChildren();lastSheets=null;renderPieceList();drawDock();syncRepeatChildUI();
    G.status.textContent='Новая кукла на листе. Одежда и эталон сохранены. Проверь результат — и можно скачивать архив для печати.';
  }
