  function flyToSheet(imgEl) { /* replaced by flyToBook in the fitting room */ }
  // A piece bigger than the chosen sheet (the Кото-кафе furniture was drawn for A3) cannot go on any number of such sheets: on this
  // sheet size it goes as a smaller copy (picture and cut lines together), the project keeps it at full size for bigger sheets.
  const shrunkCopies = new WeakMap();
  function shrinkToSheet(pieces, SW, SH, margin, spacing, corner, rotate) {
    let shrunk = 0;
    const out = pieces.map(p => {
      const key = [SW, SH, margin, spacing, corner, rotate, p.wmm, p.hmm].join('|'), memo = shrunkCopies.get(p);
      if (memo && memo.key === key) { if (memo.copy !== p) shrunk++; return memo.copy; }
      const fits = q => !fitCutArea(layoutSheets([q], SW, SH, margin, spacing, corner, rotate), SW, SH, margin, spacing, corner, rotate).error;
      let copy = p;
      if (!fits(p)) for (let k = 0.97; k > 0.2; k *= 0.97) {
        const q = Object.create(p); resizeGarment(q, p.wmm * k, p.hmm * k); // the full pictures, once loaded, show through
        if (fits(q)) { copy = q; break; }
      }
      shrunkCopies.set(p, { key, copy }); if (copy !== p) shrunk++;
      return copy;
    });
    return { pieces: out, shrunk };
  }
  // How the master cuts decides what the print step shows and what goes into the archive: scissors get ready pages (a book page and
  // pieces on one sheet), the plotter gets the Silhouette sheets and cut files. Kept on this device.
  let cutMode=null;try{cutMode=localStorage.getItem('mb-cut-mode');}catch(_){}if(!['scissors','plotter'].includes(cutMode))cutMode=null;
  function syncCutModeUI(){
    const sc=cutMode==='scissors',sw=document.getElementById('cutModeSwitch');sw.hidden=!cutMode;sw.textContent=(sc?'✂ Режу ножницами':'⌁ Режу плоттером')+' · сменить';
