  function refreshDock() { clearTimeout(dockTimer); dockTimer = setTimeout(drawDock, 60); }
  function drawDock() {
    const [SW, SH] = sheetSize();
    document.getElementById('dockSize').textContent = SW === 320 ? 'SRA3' : SW === 210 ? 'A4' : 'A3';
    dockCanvas.width = Math.round(SW * 2); dockCanvas.height = Math.round(SH * 2);
    const x = dockCanvas.getContext('2d'); x.fillStyle = '#fff'; x.fillRect(0, 0, dockCanvas.width, dockCanvas.height);
    const n = sheetPieces.length;
    updateSheetUI();
    ['dockZip', 'dockUndo', 'dockClear'].forEach(id => document.getElementById(id).disabled = !n);
    const msg = document.getElementById('dockMsg'); msg.textContent = '';document.getElementById('sheetError').hidden = true;
    if (!n) { document.getElementById('downloadZip').disabled = true; document.getElementById('dockCount').textContent = 'пусто'; document.getElementById('dockNav').hidden = true; lastSheets = null; return; }
    const margin = Number(document.getElementById('marginMM').value) || 15, gap = Number(document.getElementById('gapMM').value) || 8;
    const corner = Number(document.getElementById('cornerMM').value) || 0, pOff = Number(document.getElementById('paperOff').value) || 0, fOff = Number(document.getElementById('filmOff').value) || 0;
    const spacing = Math.max(1, gap - 2 * (fOff - pOff)), rotate = document.getElementById('allowRot').checked;
    const fitted = bookLayout ? { pieces: sheetPieces, shrunk: 0 } : shrinkToSheet(sheetPieces, SW, SH, margin, spacing, corner, rotate);
    const res = readyLayout(fitted.pieces, SW, SH, margin, spacing, corner, rotate);
    if (res.error) { lastSheets = null; document.getElementById('downloadZip').disabled = true; document.getElementById('dockZip').disabled = true; msg.textContent = res.error; document.getElementById('dockCount').textContent = n + ' дет.';
      // A big piece (the Кото-кафе furniture was drawn for A3) does not fit a small sheet: say so on the sheet and offer the bigger one.
      document.getElementById('sheetErrorText').textContent = res.error + (SW < 297 ? ' На A3 места больше.' : ' Уменьши высоту куклы или убери эту деталь в списке «Все детали на листах».');
      document.getElementById('sheetErrorA3').hidden = SW >= 297; document.getElementById('sheetError').hidden = false; return; }
    lastSheets = { sheets: res.sheets, SW, SH }; document.getElementById('downloadZip').disabled = false;
    if (cutMode !== 'scissors') dockPageIdx = Math.min(dockPageIdx, res.sheets.length - 1); // scissors pages are counted in drawScissorsDock
    if(personalization?.pending){document.getElementById('downloadZip').disabled=true;document.getElementById('dockZip').disabled=true;msg.textContent='Создай куклу на шаге 1 — готовые листы с одеждой уже загружены.';}
    if (cutMode === 'scissors') { syncBookUI(); void drawScissorsDock(res.sheets, SW, SH); return; }
    const pv = renderSheet(res.sheets[dockPageIdx], SW, SH, 2, true);
    x.drawImage(pv, 0, 0);pv.width=0;pv.height=0;syncBookUI();
    document.getElementById('dockCount').textContent = n + ' дет. · ' + (res.sheets.length > 1 ? res.sheets.length + ' листа' : '1 лист');
    document.getElementById('dockNav').hidden = res.sheets.length < 2;
    document.getElementById('dockPage').textContent = (dockPageIdx + 1) + ' / ' + res.sheets.length;
    if(fitted.shrunk&&!personalization?.pending)msg.textContent='Больше листа '+document.getElementById('dockSize').textContent+' и уменьшены под него, деталей: '+fitted.shrunk+'. На большем листе они будут в полный размер.';
    else if(res.sheets.length>1&&!personalization?.pending)msg.textContent=bookLayout?'Готовая книга: '+bookLayout.pages.length+' листа с одеждой'+(res.sheets.length>bookLayout.pages.length?' + лист с куклой':'')+'.':'Не влезло на один лист — добавлен ещё один.';
    if(printExportBusy){document.getElementById('dockZip').disabled=true;document.getElementById('downloadZip').disabled=true;}
  }
  document.getElementById('sheetErrorA3').addEventListener('click', () => { if (!canEditBook()) return; document.getElementById('sheetSize').value = 'a3'; dockPageIdx = 0; drawDock(); queueProjectSave(); showToast('Лист A3: детали разложены заново'); });
  document.getElementById('dockPrev').addEventListener('click', (e) => { e.stopPropagation(); dockPageIdx = Math.max(0, dockPageIdx - 1); drawDock(); });
