  // batch results: each card has its own «Добавить»
  function batchCard(canvas, name, pct, source, loose=false) {
    const wrap=document.getElementById('batchCards'),card=document.createElement('div');card.className='bcard';
    const im=document.createElement('img');im.src=canvas.toDataURL('image/png');im.alt=name;
    const text=document.createElement('div');text.className='hint';text.textContent=name+(pct!==null?' · '+pct+'%':'');
