      btn.onclick=async()=>{const ok=await copyText(it.text);if(!ok){const r=document.createRange();r.selectNodeContents(pre);getSelection().removeAllRanges();getSelection().addRange(r);}btn.textContent=ok?'Скопировано ✓':'Выделил — нажми Ctrl+C';setTimeout(()=>{btn.textContent='Скопировать промт';},2200);};
      {let inRule=false;it.text.split(/\n\s*\n/).forEach((t,i)=>{const p=document.createElement('span'),m=document.createElement('span');p.className='prompt-p';m.textContent=t;p.append(m);
