  // Cloud storage of pictures (admin only).
  {
    const msg = t => { document.getElementById('accountMessage').textContent = t; };
    const mb = n => (n / 1048576).toFixed(n > 104857600 ? 0 : 1) + ' МБ';
    const describe = st => (st.ready ? 'Облако подключено (' + st.bucket + ')' : 'Облако не подключено') + '. В облаке: ' + st.cloudImages + ' картинок, ' + mb(st.cloudBytes) + '. На хостинге: ' + st.localImages + ' картинок, ' + mb(st.localBytes) + '.';
    const form = document.getElementById('accountStorage'), buttons = () => form.querySelectorAll('button');
    const busy = on => buttons().forEach(b => { b.disabled = on; });
    form.onsubmit = async e => {
      e.preventDefault(); const f = form.elements; busy(true); msg('Проверяю хранилище…');
      try { const r = await accountPost('storage.configure', { endpoint: f.endpoint.value.trim(), bucket: f.bucket.value.trim(), key: f.key.value.trim(), secret: f.secret.value.trim(), region: f.region.value.trim(), quotaMB: Number(f.quota.value) || 2048 });
        f.key.value = ''; f.secret.value = ''; msg((r.status.ready ? 'Сохранено, запись и чтение работают. ' : 'Облако отключено. ') + describe(r.status)); }
      catch (error) { msg(error.message); } finally { busy(false); }
    };
    document.getElementById('storageStatus').onclick = async () => { busy(true); try { const st = await accountPost('storage.status', {}); const f = form.elements; if (st.endpoint) f.endpoint.value = st.endpoint; if (st.bucket) f.bucket.value = st.bucket; f.region.value = st.region || ''; f.quota.value = st.quotaMB; msg(describe(st)); } catch (error) { msg(error.message); } finally { busy(false); } };
    document.getElementById('storageMigrate').onclick = async () => {
      busy(true); let total = 0;
      try { for (;;) { const r = await accountPost('storage.migrate', {}); total += r.moved; msg('Перенесено картинок: ' + total + ', осталось: ' + r.left + '…');
          if (r.errors.length) { msg('Остановился: ' + r.errors[0] + '. Перенесено: ' + total + ', осталось: ' + r.left + '.'); break; }
          if (!r.left || !r.moved) { msg('Готово. Перенесено: ' + total + '. ' + describe(r.status)); break; } } }
      catch (error) { msg(error.message); } finally { busy(false); }
    };
    document.getElementById('storageGC').onclick = async () => {
      busy(true);
      try { const dry = await accountPost('storage.gc', { dry: true }); if (dry.skipped) { msg(dry.skipped); return; }
        if (!dry.deleted) { msg('Неиспользуемых картинок нет (новее суток не трогаем). ' + describe(dry.status)); return; }
        if (!confirm('Будет удалено картинок: ' + dry.deleted + ' (' + mb(dry.freedBytes) + '). Они не входят ни в один проект. Продолжить?')) { msg('Отменено.'); return; }
        const r = await accountPost('storage.gc', {}); msg('Удалено: ' + r.deleted + ', освобождено ' + mb(r.freedBytes) + (r.errors.length ? '. Ошибки: ' + r.errors[0] : '') + '. ' + describe(r.status)); }
      catch (error) { msg(error.message); } finally { busy(false); }
    };
  }
