  async function restoreLocalPhoto(draft){
    if(!(draft?.blob instanceof Blob)||draft.blob.size>15728640||!/^image\/(jpeg|png|webp)$/.test(draft.blob.type))return;
    const file=new File([draft.blob],draft.name||'photo.jpg',{type:draft.blob.type});const url=URL.createObjectURL(file);childPreviewURL=url;
    try{const image=new Image();image.src=url;await image.decode();if(childPreviewURL!==url)return;gPhotoFile=file;const preview=document.getElementById('childPreview');preview.src=url;preview.hidden=false;document.getElementById('childPhotoEmpty').hidden=true;document.getElementById('photoChange').hidden=false;document.getElementById('childFilename').textContent=file.name+' · фото восстановлено';gInfoRender();}catch(_){resetChildPreview();}
  }
  async function resumeSavedOrder(local,pointer){
    const id=pointer?.id||local?.cloud?.project?.id;
    const localMatches=local&&((id&&local.cloud?.project?.id===id)||(!id&&pointer?.draft&&!local.cloud?.project));
    // The copy on this device is the same revision as the account: open it from here, without downloading every picture again (~8 MB, 20+ s).
    const localFresh=localMatches&&id&&Number.isFinite(pointer?.revision)&&local.cloud?.project?.revision===pointer.revision;
    if(localMatches&&(local.cloud?.dirty||!id||localFresh)){
      projectRestoring=true;await applyProject(local);cloudProject=local.cloud?.project||null;cloudTitle.value=local.cloud?.title||pointer?.title||'Черновик';cloudDirty=!!local.cloud?.dirty;cloudBlocked=!!local.cloud?.blocked;
      if(cloudProject){try{const remote=await accountAPI('project&id='+id);if(remote.project.revision!==cloudProject.revision){cloudBlocked=true;cloudStatus.textContent='Локальная работа восстановлена. В аккаунте есть другая версия — сохрани копию перед продолжением.';}}catch(e){if(e.status===404){cloudProject=null;cloudBlocked=!pointer?.explicit;cloudDirty=true;cloudStatus.textContent='Проект удалён из аккаунта. Локальный черновик сохранён на устройстве и не отправлен автоматически. Для восстановления нажми «Сохранить копию».';}}}
      projectRestoring=false;
    }else if(id){try{await cloudOpen(id,null,true);}catch(e){if(e.status!==404||!localMatches||!pointer?.explicit)throw e;projectRestoring=true;await applyProject(local);cloudProject=null;cloudTitle.value=local.cloud?.title||'Восстановленный проект';cloudDirty=true;cloudBlocked=false;projectRestoring=false;}}
    else throw Error('Нет проекта для продолжения');
    setStage(pointer?.stage||(gResult?'4':'2'),false);rememberActive();document.getElementById('resumeOrderPanel').hidden=true;
    cloudStatus.textContent=cloudBlocked?cloudStatus.textContent:'Продолжаем проект «'+cloudTitle.value+'». Все сохранённые листы восстановлены.';
    if(cloudDirty&&!cloudBlocked){clearTimeout(cloudTimer);if(pointer?.explicit)await cloudSave();else cloudTimer=setTimeout(()=>void cloudSave(),15000);}
    void resumeGenerationForOrder();
  }
  function offerResume(local,projects){
    const panel=document.getElementById('resumeOrderPanel');const active=activePointer(),localId=local?.cloud?.project?.id,activeId=active?.id;
    // The project this device remembers was deleted in the account and holds no unsaved work: forget it instead of offering to continue it.
    if(localId&&!local.cloud?.dirty&&!projects.some(p=>p.id===localId)){local=null;void projectClear().catch(()=>{});}
    const remote=projects.find(p=>p.id===activeId)||projects.find(p=>p.id===local?.cloud?.project?.id)||projects.find(p=>!/исходные|новая книга/i.test(p.title));
    const candidate=(local?.cloud?.dirty||local?.result)&&(!remote||remote.id===localId)?{id:localId,title:local.cloud?.title||'Локальный черновик'}:remote;
    panel.hidden=!candidate;if(!candidate)return;
    const card=projects.find(p=>p.id===candidate.id)||candidate;
    document.getElementById('resumeOrderTitle').textContent='У вас остался проект «'+candidate.title+'»';const cardThumb=document.getElementById('resumeCardThumb');cardThumb.hidden=!card.thumb;if(card.thumb)cardThumb.src=card.thumb;
    // Loads the project behind a lock with the «Открываем проект…» pill; the studio itself is already usable.
    const resume=async()=>{
      document.getElementById('resumeDialog').close();mainUI.inert=dock.inert=true;document.documentElement.dataset.loading='project';
      try{await resumeSavedOrder(local,{id:candidate.id,draft:!candidate.id,stage:active?.stage||(local?.result?'4':'2'),revision:card.revision,explicit:true});}
      catch(e){if(e.status===404)forgetActive();showToast('Не удалось продолжить проект: '+e.message);}
      finally{mainUI.inert=dock.inert=false;delete document.documentElement.dataset.loading;}
    };
    document.getElementById('resumeOrderButton').onclick=resume;document.getElementById('resumeGo').onclick=resume;
    document.getElementById('resumeNew').onclick=()=>{forgetActive();document.getElementById('resumeDialog').close();};
    const thumb=document.getElementById('resumeThumb');thumb.hidden=!card.thumb;if(card.thumb)thumb.src=card.thumb;
    document.getElementById('resumeTitle').textContent=candidate.title;
    document.getElementById('resumeMeta').textContent=[card.updatedAt?projectWhen(card.updatedAt):'',typeof card.items==='number'?itemsWord(card.items):''].filter(Boolean).join(' · ')||'Сохранён на этом устройстве';
    // A reload of the same tab (the tab remembers its project) goes straight back to that project. A new visit shows the card
    // at the top of the studio; no pop-up window.
    // After the startup code has unlocked the page, so its cleanup does not drop the «Открываем проект…» lock of this load.
    if(active&&(active.id||null)===(candidate.id||null))setTimeout(()=>void resume(),0);
  }
  async function resumeGenerationForOrder(){
    if(!cloudProject||gBusy)return;const project=cloudProject.id;let mark=null;try{mark=JSON.parse(sessionStorage.getItem(pendingJobKey())||'null');}catch(_){}
    gBusy=true;gInfoRender();let url=null;
    try{
      const waiting=mark?.project===project&&Date.now()-mark.at<180000;
      if(waiting){setGenerationBusy(true);G.status.textContent='Проверяю начатую генерацию. Повторный запуск не требуется…';}
      let job=null;for(let attempt=0;attempt<(waiting?90:1);attempt++){
        try{job=await accountAPI('hf.project&project='+project);break;}catch(e){if(e.status!==404)throw e;if(!waiting)return;await new Promise(r=>setTimeout(r,1000));if(cloudProject?.id!==project)return;}
      }
      if(!job){G.status.textContent='Проект сохранён. На сервере пока не найдена начатая генерация.';return;}
      if(job.job===resultJobId||cloudProject?.id!==project){clearGenerationMark();return;}
      setGenerationBusy(true);G.status.textContent='Возвращаю результат начатой генерации. Новая обработка не запускается…';
      if(!job.ready)await accountAPI('hf.result&job='+job.job);
      if(cloudProject?.id!==project)return;
      const response=await fetch('api.php?action=hf.image&job='+job.job,{cache:'no-store'});if(!response.ok)throw Error('Не удалось получить готовую куклу');
      url=URL.createObjectURL(await response.blob());const image=new Image();image.src=url;await image.decode();const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;canvas.getContext('2d').drawImage(image,0,0);
      resultJobId=job.job;gResult=canvas;G.out.src=canvas.toDataURL('image/png');G.out.hidden=false;G.save.disabled=G.add.disabled=G.cmp.disabled=false;clearGenerationMark();
      const pendingBook=personalization?.pending;autoInstallDoll();if(pendingBook)setStage('4');queueProjectSave();
      G.status.textContent='Кукла восстановлена из начатой генерации. Дополнительная квота GPU не расходовалась.';rememberActive();
    }catch(e){G.status.textContent='Проект сохранён. Результат генерации пока не получен: '+e.message;}
    finally{if(url)URL.revokeObjectURL(url);gBusy=false;gInfoRender();setGenerationBusy(false);}
  }
  let bookProduction=null;
  // Book step: after the wardrobe the master picks a ready book. Its spreads (the backgrounds) ship with the site in books/<id>/ and
  // go into the print archive; a book can bring its own pieces to cut (Кото-кафе), marked p.kit so another choice takes them away.
  const READY_BOOKS=[
    {id:'my-doll',title:'Моя кукла',spreads:3,text:'Комнаты куколки: туалетный столик, шкаф, игровая, спальня и ванная. Одежда — из твоего гардероба.'},
    {id:'cat-cafe',title:'Кото-кафе',spreads:4,kit:true,text:'Спальня и шкаф, ванная и кухня, маникюр и косметика, кото-кафе. Котики и предметы уже готовы к вырезанию, можно добавить свои вещи из гардероба.'}];
  let chosenBook=null,bookKitBusy=false;
  const bookSpreads=id=>{const b=READY_BOOKS.find(x=>x.id===id);return b?Array.from({length:b.spreads},(_,i)=>({key:'spread'+(i+1),url:'books/'+b.id+'/spread'+(i+1)+'.jpg',preview:'books/'+b.id+'/preview-spread'+(i+1)+'.jpg'})):[];};
  // The book's own pieces as sheet pieces: small previews first (full pictures load before printing), scaled to this doll's height.
  async function loadBookKit(id,onStatus){
    const j=await accountAPI('book.kit&id='+encodeURIComponent(id)),isRef=v=>typeof v==='string'&&/^img:[a-f0-9]{64}$/.test(v);
    if(!j.pieces.length)return [];
    const hashes=[...new Set(j.pieces.flatMap(p=>[p.frame,p.print]).filter(isRef).map(v=>v.slice(4)))];
    let previews=new Map();try{previews=await fetchPreviews(hashes);}catch(_){}
    const picture=async v=>{if(!isRef(v))return v?dataURLBlob(v):null;const h=v.slice(4);if(previews.has(h)){const q=previews.get(h);return {lazy:true,h,blob:q.blob,w:q.w,hgt:q.h};}return fetchImage(h);};
    const k=(Number(document.getElementById('dollMM').value)||160)/(Number(j.dollMM)||160),out=[];
    for(let i=0;i<j.pieces.length;i++){const s=j.pieces[i];onStatus?.(i+1,j.pieces.length);
      const p=await restorePieceImages({...s,frame:await picture(s.frame),print:s.printLayout?null:await picture(s.print)});p.role='item';p.kit=id;delete p.fit;
      if(Math.abs(k-1)>0.001)resizeGarment(p,p.wmm*k,p.hmm*k);
      let name=p.name,n=2;while(sheetPieces.some(q=>q.name===name)||out.some(q=>q.name===name))name=p.name+'_'+n++;p.name=name;out.push(p);}
    return out;
  }
  async function chooseBook(id){
    if(bookKitBusy||id===chosenBook||!canEditBook())return;
    const status=document.getElementById('bookChoiceStatus'),book=READY_BOOKS.find(b=>b.id===id);bookKitBusy=true;renderBookChoices();
    try{
      let kit=[];if(book?.kit&&!sheetPieces.some(p=>p.kit===id)){status.hidden=false;status.textContent='Загружаю предметы книги «'+book.title+'»…';kit=await loadBookKit(id,(n,all)=>{status.textContent='Загружаю предметы книги «'+book.title+'»: '+n+' из '+all+'…';});}
      // The pieces of the book chosen before leave the sheet; the wardrobe items stay.
      const gone=sheetPieces.filter(p=>p.kit&&p.kit!==id).length;
      sheetPieces.splice(0,sheetPieces.length,...sheetPieces.filter(p=>!p.kit||p.kit===id),...kit);
      chosenBook=id;lastSheets=null;rehearsal.page=0;status.hidden=false;
      status.textContent=book?'Книга «'+book.title+'» выбрана.'+(kit.length?' Предметов книги на листах: '+kit.length+'.':'')+(gone?' Предметы прежней книги убраны с листов.':'')+' Дальше — печать.':'Без книги: в печать пойдут только листы для вырезания.'+(gone?' Предметы книги убраны с листов.':'');
