    document.getElementById('bookChoices').replaceChildren(...READY_BOOKS.map(book=>{
      const on=chosenBook===book.id,card=document.createElement('article');card.className='card book-choice'+(on?' is-chosen':'');
      const spreads=bookSpreads(book.id),view=document.createElement('img');view.className='book-choice-spread';view.src=spreads[0].preview;view.alt='Разворот книги «'+book.title+'»';view.width=1200;view.height=609;view.decoding='async';
      const thumbs=document.createElement('div');thumbs.className='book-choice-thumbs';thumbs.hidden=spreads.length<2;
      spreads.forEach((sp,i)=>{const b=document.createElement('button');b.type='button';b.setAttribute('aria-label','Разворот '+(i+1));b.setAttribute('aria-pressed',String(i===0));const t=document.createElement('img');t.src=sp.preview;t.alt='';t.loading='lazy';b.append(t);
        b.onclick=()=>{view.src=sp.preview;thumbs.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));};thumbs.append(b);});
      const title=document.createElement('h3');title.textContent=book.title;
      const meta=document.createElement('span');meta.className='tag';meta.textContent=book.spreads===1?'1 РАЗВОРОТ':book.spreads+' РАЗВОРОТА';
      const text=document.createElement('p');text.textContent=book.text;
      const note=document.createElement('p');note.className='hint';note.textContent=book.kit?(items?'Плюс вещи из гардероба: '+items+'.':'Свои вещи можно добавить в гардеробе.'):items?'Вещи из гардероба на листах: '+items+'.':'Сначала выбери одежду в гардеробе.';
      const pick=document.createElement('button');pick.type='button';pick.className=on?'button-secondary full':'primary full';pick.textContent=on?'✓ Книга выбрана':'Выбрать эту книгу';pick.disabled=bookKitBusy||on;pick.onclick=()=>void chooseBook(book.id);
      const head=document.createElement('div');head.className='card-heading';head.append(title,meta);
      card.append(view,thumbs,head,text,note,pick);return card;
    }));
    document.getElementById('bookNone').hidden=!chosenBook;
  }
  document.getElementById('bookNone').onclick=()=>void chooseBook(null);
  async function addBookSpreads(files){
    const book=READY_BOOKS.find(b=>b.id===chosenBook);if(!book)return;
    for(const sp of bookSpreads(book.id)){const r=await fetch(sp.url,{cache:'force-cache'});if(!r.ok)throw Error('Не удалось получить разворот книги');files.push({name:'kniga/razvorot_'+sp.key.slice(6)+'.jpg',data:await r.blob()});}
    files.push({name:'kniga/README.txt',data:'\ufeffКнига «'+book.title+'»: развороты-фоны для печати ('+book.spreads+' шт., JPG 4000 × 2030 px). Куколку и вещи печатай на листах из этого архива и вырезай по контурам.'});
  }
  function productionURL(file,preview=false,download=false){
    const q=new URLSearchParams({action:'book.production.image',id:bookProduction.id,revision:String(bookProduction.revision),key:file.key});
    if(preview)q.set('preview','1');if(download)q.set('download','1');return 'api.php?'+q;
  }
  async function productionBlob(file){const r=await fetch(productionURL(file),{cache:'force-cache'});if(!r.ok)throw Error('Не удалось получить '+file.filename);return r.blob();}
  async function addFactoryFiles(files){
    if(!bookProduction)return;
    if(!bookProduction.approved){files.push({name:'FABRIKA_FORMAT_NE_PODTVERZHDEN.txt',data:bookProduction.statusText+'\r\nИсходные JPG доступны в редакторе. Служебный шаблон не является страницей книги.'});return;}
    for(const file of bookProduction.files)files.push({name:'fabrika/'+file.filename,data:await productionBlob(file)});
    files.push({name:'fabrika/README.txt',data:'Обложка и 3 разворота. Загружай каждый JPG в соответствующее поле фабрики. Служебный шаблон с жёлтыми полями не включён. '+bookProduction.statusText});
  }
  function renderProduction(){
    // The factory photobook of the old catalog books is retired; a book's spreads now come from the «Книга» step.
    const panel=document.getElementById('productionPanel');panel.hidden=true;return;
    document.getElementById('productionStatus').textContent=bookProduction.statusText;
    const grid=document.getElementById('productionGallery');grid.replaceChildren();
    for(const file of bookProduction.files){const card=document.createElement('article');card.className='production-item';const im=document.createElement('img');im.src=productionURL(file,true);im.loading='lazy';im.alt=file.title;const name=document.createElement('b');name.textContent=file.title;const size=document.createElement('p');size.className='hint';size.textContent=file.width+' × '+file.height+' px · JPG';
      const link=document.createElement('a');link.className='text-button';link.textContent='Скачать исходный JPG';link.href=productionURL(file,false,true);link.target='_blank';link.rel='noopener';card.append(im,name,size,link);grid.append(card);}
    const button=document.getElementById('factoryDownload');button.disabled=!bookProduction.approved;button.textContent=bookProduction.approved?'Скачать обложку и развороты · JPG':'Нужно уточнить формат фабрики';
    const guide=document.getElementById('factoryGuide');guide.href=productionURL({key:'guide'},false,true);
