    try{const files=[];await addFactoryFiles(files);await saveBlob('fabrika_my_doll.zip',await makeZip(files));showToast('JPG для фабрики подготовлены');}catch(err){document.getElementById('productionStatus').textContent=err.message;}finally{button.disabled=!bookProduction?.approved;}
  };

  let bookLayout=null,bookInfo=null,workingProject=false,bookCatalog=[],bookGender='girl',selectedBook=null,bookStartRequest=null;
  const bookTitles={'my-doll':'Моя куколка','cat-cafe':'Кото-кафе','space-boy':'Космонавт'};
  const printSettingIds=['dollMM','sheetSize','marginMM','gapMM','paperOff','filmOff','cornerMM','allowRot','cvX','cvY','cvW'];
  function findFreeDoll(sh,p,SW,SH,margin,gap,corner,rot){
    const W=Math.ceil(SW),H=Math.ceil(SH),occ=new Uint8Array(W*H),half=gap/2;
    const mark=(x0,y0,x1,y1)=>{for(let y=Math.max(0,Math.floor(y0));y<Math.min(H,Math.ceil(y1));y++)for(let x=Math.max(0,Math.floor(x0));x<Math.min(W,Math.ceil(x1));x++)occ[y*W+x]=1;};
    for(const it of sh.items)mark(it.x-half,it.y-half,it.x+(it.rot?it.p.hmm:it.p.wmm)+half,it.y+(it.rot?it.p.wmm:it.p.hmm)+half);
    if(corner>0)for(const [x,y] of [[0,0],[SW-corner,0],[0,SH-corner],[SW-corner,SH-corner]])mark(x,y,x+corner,y+corner);
    const stride=W+1,prefix=new Int32Array((W+1)*(H+1));for(let y=0;y<H;y++){let row=0;for(let x=0;x<W;x++){row+=occ[y*W+x];prefix[(y+1)*stride+x+1]=prefix[y*stride+x+1]+row;}}
    const w=rot?p.hmm:p.wmm,h=rot?p.wmm:p.hmm;
    for(let y=Math.ceil(margin);y+h<=SH-margin;y++)for(let x=Math.ceil(margin);x+w<=SW-margin;x++){
      const x0=Math.max(0,Math.floor(x-half)),y0=Math.max(0,Math.floor(y-half)),x1=Math.min(W,Math.ceil(x+w+half)),y1=Math.min(H,Math.ceil(y+h+half));
      if(prefix[y1*stride+x1]-prefix[y0*stride+x1]-prefix[y1*stride+x0]+prefix[y0*stride+x0]===0)return {p,x,y,rot};
    }
    return null;
  }

  // Cut box of one placed item (red ring + blue film line), in sheet mm.
  function itemCutBox(it){let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;for(const pl of paperCuts(it.p).concat(it.p.film||[]))for(const q of pl){const [X,Y]=place(it,q);if(X<x0)x0=X;if(Y<y0)y0=Y;if(X>x1)x1=X;if(Y>y1)y1=Y;}return {x0,y0,x1,y1};}
  function sheetCutBox(sh){let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;for(const it of sh.items){const b=itemCutBox(it);x0=Math.min(x0,b.x0);y0=Math.min(y0,b.y0);x1=Math.max(x1,b.x1);y1=Math.max(y1,b.y1);}return {x0,y0,x1,y1};}
  function sheetInCutArea(sh,A){const b=sheetCutBox(sh),e=0.05;return b.x0>=A.x-e&&b.y0>=A.y-e&&b.x1<=A.x+A.w+e&&b.y1<=A.y+A.h+e;}
  // The cut DXF covers exactly Silhouette's cut area. A single line outside it makes the DXF bigger than that area, Silhouette shrinks
  // the whole file to fit, and every cut misses the print. Books saved with older layout rules can have pieces there, so every sheet is
  // checked: a sheet that sticks out is moved as a whole (the book keeps its arrangement); one that cannot fit is laid out again.
  function fitCutArea(res,SW,SH,margin,gap,corner,rotate){
    const A=silCutArea(SW,SH);if(res.error||!A)return res;
    const out=[];let moved=0,relaid=0;
    for(const sh of res.sheets){
      if(sheetInCutArea(sh,A)){out.push(sh);continue;}
      const b=sheetCutBox(sh),pad=0.5;
      if(b.x1-b.x0<=A.w-2*pad&&b.y1-b.y0<=A.h-2*pad){
        const dx=Math.min(Math.max(0,A.x+pad-b.x0),A.x+A.w-pad-b.x1),dy=Math.min(Math.max(0,A.y+pad-b.y0),A.y+A.h-pad-b.y1);
        out.push({items:sh.items.map(it=>({p:it.p,x:it.x+dx,y:it.y+dy,rot:it.rot}))});moved++;continue;
      }
      const again=layoutSheets(sh.items.map(it=>it.p),SW,SH,margin,gap,corner,rotate);if(again.error)return again;
      for(const ns of again.sheets){if(sheetInCutArea(ns,A)){out.push(ns);continue;}const nb=sheetCutBox(ns);if(nb.x1-nb.x0>A.w-2*pad||nb.y1-nb.y0>A.h-2*pad)return {error:'Детали не помещаются в зону резки Silhouette. Уменьши высоту куклы или колечко красного реза.'};
        const ndx=Math.min(Math.max(0,A.x+pad-nb.x0),A.x+A.w-pad-nb.x1),ndy=Math.min(Math.max(0,A.y+pad-nb.y0),A.y+A.h-pad-nb.y1);out.push({items:ns.items.map(it=>({p:it.p,x:it.x+ndx,y:it.y+ndy,rot:it.rot}))});}
      relaid++;
    }
    const notes=[];if(moved)notes.push('сдвинуто листов: '+moved);if(relaid)notes.push('разложено заново: '+relaid);
    return {sheets:out,note:notes.length?'Детали подвинуты внутрь зоны резки Silhouette, чтобы рез совпал с печатью ('+notes.join(', ')+').':''};
  }
  function readyLayout(pieces,SW,SH,margin,gap,corner,rotate){return fitCutArea(readyLayoutRaw(pieces,SW,SH,margin,gap,corner,rotate),SW,SH,margin,gap,corner,rotate);}
  function readyLayoutRaw(pieces,SW,SH,margin,gap,corner,rotate){
    if(!bookLayout)return layoutSheets(pieces,SW,SH,margin,gap,corner,rotate);
    try{
      if(SW!==bookLayout.SW||SH!==bookLayout.SH)throw Error('Размер листа книги изменён. Верни исходные настройки или включи редактирование.');
      const used=new Set(),sheets=bookLayout.pages.map(page=>({items:page.map(it=>{const p=pieces[it.index];if(!p||isDollPiece(p))throw Error('Состав книги изменён. Открой исходную книгу заново.');used.add(it.index);return {p,x:it.x,y:it.y,rot:it.rot};})}));
      const extras=pieces.filter((p,i)=>!used.has(i));if(extras.some(p=>!isDollPiece(p)))throw Error('В готовую книгу добавлены детали. Включи редактирование раскладки.');
      for(const p of extras){let placed=false;for(const slot of bookLayout.dollSlots||[]){const sh=sheets[slot.page];if(!sh||sh.items.some(it=>isDollPiece(it.p)))continue;const w=slot.rot?p.hmm:p.wmm,h=slot.rot?p.wmm:p.hmm;
        if(slot.x+w>SW-margin||slot.y+h>SH-margin||slot.x<margin||slot.y<margin)continue;
        if([[0,0],[SW-corner,0],[0,SH-corner],[SW-corner,SH-corner]].some(([zx,zy])=>corner>0&&slot.x<zx+corner&&slot.x+w>zx&&slot.y<zy+corner&&slot.y+h>zy))continue;
        if(!(p.wmm<=slot.wmm+2&&p.hmm<=slot.hmm+2)&&sh.items.some(it=>{const iw=it.rot?it.p.hmm:it.p.wmm,ih=it.rot?it.p.wmm:it.p.hmm;return slot.x<it.x+iw+gap&&slot.x+w+gap>it.x&&slot.y<it.y+ih+gap&&slot.y+h+gap>it.y;}))continue;
        sh.items.push({p,x:slot.x,y:slot.y,rot:slot.rot});placed=true;break;}
        if(!placed){for(const rot of (rotate?[false,true]:[false])){for(let page=sheets.length-1;page>=0;page--){const found=findFreeDoll(sheets[page],p,SW,SH,margin,gap,corner,rot);if(found){sheets[page].items.push(found);placed=true;break;}}if(placed)break;}}
        if(!placed){const added=layoutSheets([p],SW,SH,margin,gap,corner,rotate);if(added.error)throw Error(added.error);sheets.push(...added.sheets);}
      }
      return {sheets};
    }catch(e){return {error:e.message};}
  }
  function syncBookUI(){
    const fixed=!!bookLayout;document.getElementById('bookFrozen').hidden=!fixed;document.getElementById('lastResultRecoveryPanel').hidden=document.getElementById('resumeRecoverLink').hidden=workingProject||!lastRecoverJob;
    document.getElementById('bookFrozenText').textContent=fixed?'Книга «'+(bookTitles[bookInfo?.id]||'Готовый набор')+'»: '+bookLayout.pages.length+' готовых листа с одеждой. Раскладка зафиксирована. Кукла добавится в свободное место или на отдельный лист.'+(bookLayout.notice?' '+bookLayout.notice:''):'';
    document.getElementById('activeOrderCard').hidden=!workingProject;document.getElementById('startChoices').hidden=workingProject;
    document.getElementById('bookPublishSection').hidden=document.getElementById('bookPublish').hidden=true;document.getElementById('showLibrary').hidden=!account?.admin;
    // Masters get only what they need to print; the cutting settings, the backup file and the manual refresh stay with the owner.
    for(const id of ['printAdvanced','printBackup','rehearsalRefresh'])document.getElementById(id).hidden=!account?.admin;
    document.getElementById('flowPath').hidden=workingProject;
    [...printSettingIds,'refFile','gTpl'].forEach(id=>document.getElementById(id).disabled=fixed);document.getElementById('wardrobeEditor').hidden=fixed;document.getElementById('wardrobeReady').hidden=!fixed;
    for(const id of ['dockUndo','dockClear','clearPieces','addPng'])document.getElementById(id).disabled=fixed||(!sheetPieces.length&&id!=='addPng');
    document.querySelectorAll('#pieceList .piece button').forEach(el=>el.disabled=fixed);
  }
  function canEditBook(){if(!bookLayout)return true;showToast('Листы книги зафиксированы. Для изменений нажми «Редактировать раскладку».');return false;}
  function currentBookLayout(){
    drawDock();if(!lastSheets)throw Error('Сначала подготовь листы на шаге «Печать».');
    const pages=[],dollSlots=[];
    for(const sh of lastSheets.sheets){const clothes=sh.items.filter(it=>!isDollPiece(it.p));if(!clothes.length)continue;const page=pages.length;
      pages.push(clothes.map(it=>({index:sheetPieces.indexOf(sheetPieces.includes(it.p)?it.p:Object.getPrototypeOf(it.p)),x:it.x,y:it.y,rot:it.rot})));
      for(const it of sh.items.filter(it=>isDollPiece(it.p)))dollSlots.push({page,x:it.x,y:it.y,rot:it.rot,wmm:it.p.wmm,hmm:it.p.hmm});
    }
    if(!pages.length)throw Error('Нужны готовые листы с одеждой. Кукла сама по себе не является книгой.');
    return {SW:lastSheets.SW,SH:lastSheets.SH,pages,dollSlots};
  }
  async function loadBooks(){bookCatalog=(await accountAPI('books')).books;renderBooks();
    // No books in the catalog: every way into them goes away (the studio starts from the doll and the wardrobe).
    const none=!bookCatalog.length;document.getElementById('readyBookOptions').hidden=none;document.getElementById('readyBooksButton').hidden=none;document.getElementById('startBooks').closest('.start-card').hidden=none;}
  function renderBooks(){
    const grid=document.getElementById('bookCatalog');grid.replaceChildren();
    document.querySelectorAll('[data-book-gender]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.bookGender===bookGender));b.hidden=false;});
    for(const book of bookCatalog.filter(b=>b.gender===bookGender)){
