  let reusableChild=null,reusableChildren=[];
  const childNameOf=label=>{const parts=String(label||'').split(/\s[—–-]\s/);return (parts.length>1?parts[parts.length-1]:String(label||'')).trim().slice(0,70);};
  async function childTemplateKey(){const b=await pngBlob(refImage);if(!b)throw Error('Не загружен эталон');return [...new Uint8Array(await crypto.subtle.digest('SHA-256',await b.arrayBuffer()))].map(x=>x.toString(16).padStart(2,'0')).join('');}
  function bodyShape(image){
    const m=maskOf(image,180);let left=m.w,right=-1,top=m.h,bottom=-1;
    for(let y=0;y<m.h;y++)for(let x=0;x<m.w;x++)if(m.mag[y*m.w+x]){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}
    if(right<=left||bottom<=top)throw Error('Не удалось проверить форму эталонного тела');
    const bits=[];for(let y=0;y<100;y++)for(let x=0;x<64;x++){const yy=Math.min(bottom,Math.round(top+(bottom-top)*(.28+.72*y/99))),xx=Math.min(right,Math.round(left+(right-left)*x/63));bits.push(m.mag[yy*m.w+xx]);}
