  }
  async function compatibleChild(child,reference){
    if(!child.reference||!reference)return false;let a=null,b=null;
    try{const asBlob=v=>v instanceof Blob?v:dataURLBlob(v);a=await loadPNGAsset(asBlob(child.reference),'эталон готовой куклы');b=await loadPNGAsset(asBlob(reference),'эталон книги');const A=bodyShape(a),B=bodyShape(b);let intersection=0,union=0;for(let i=0;i<A.bits.length;i++){if(A.bits[i]&&B.bits[i])intersection++;if(A.bits[i]||B.bits[i])union++;}return union>100&&intersection/union>=.97&&Math.abs(A.aspect/B.aspect-1)<.02;}
