      mainUI.inert=true;dock.inert=true;
      if(cloudBlocked)throw new Error('Сначала разреши конфликт версий проекта.');
      if(cloudDirty||!cloudProject){cloudDirty=true;await cloudSave();}
      clearTimeout(cloudTimer);
      const signature=JSON.stringify([cloudProject.id,cloudProject.revision,name,target]);
      if(!repeatCloneRequest||repeatCloneRequest.signature!==signature){const bytes=crypto.getRandomValues(new Uint8Array(16));repeatCloneRequest={signature,id:[...bytes].map(x=>x.toString(16).padStart(2,'0')).join('')};}
      // Only small metadata goes over the network. Images stay on server and in existing canvases.
      const reply=await accountPost('project.clone',{source:cloudProject.id,expectedRevision:cloudProject.revision,title:name,target,requestId:repeatCloneRequest.id});
      projectRestoring=true;
      sheetPieces.forEach((p,i)=>{p.role=(target==='auto'?isDollPiece(p):target!=='none'&&i===Number(target))?'doll':'item';});
      personalization={pending:true};gResult=null;gPhotoFile=null;G.photo.value='';resetChildPreview();
      clearInterval(cmpTimer);cmpOn=false;G.cmp.textContent='Сравнить с эталоном';G.out.hidden=true;G.out.removeAttribute('src');G.save.disabled=G.add.disabled=G.cmp.disabled=true;
      resetClothingPlan();lastResult=null;currentImage=null;document.getElementById('batchCards').replaceChildren();srcImg.hidden=outImg.hidden=true;document.getElementById('fitPanel').hidden=true;saveBtn.disabled=true;
      cloudProject=reply.project;cloudTitle.value=name;cloudDirty=false;cloudBlocked=false;sheetOut.replaceChildren();lastSheets=null;syncRepeatChildUI();renderPieceList();drawDock();gInfoRender();
      try{await projectWrite(await projectSnapshot());}catch(localError){projectStatus.textContent='Копия сохранена в аккаунте. Не удалось сохранить копию в браузере.';}
      try{await cloudList();}catch(listError){cloudStatus.textContent='Копия создана; список проектов можно обновить позже.';}
      repeatCloneRequest=null;
      document.getElementById('repeatChildDialog').close();setStage('2');G.status.textContent='Новая книга создана. Выбери фото ребёнка. Вся одежда уже на листах.';showToast('Копия создана — осталось заменить куклу');
    }catch(err){error.hidden=false;error.textContent=/Load failed|Failed to fetch|NetworkError/i.test(err.message)?'Соединение прервалось. Нажми ещё раз: если копия уже создана, откроется она же. Исходная книга сохранена.':err.message;}
    finally{projectRestoring=false;mainUI.inert=false;dock.inert=false;button.disabled=false;button.removeAttribute('aria-busy');button.textContent='Создать копию и выбрать фото';}
  });

  // Clothing has an explicit preparation -> separation -> add/download workflow.
  let clothingPlan = null, clothingPlanTicket = 0;
  function clothingGeometryKey() { return [refMask?.w0,refMask?.h0,...['dollMM','paperOff','filmOff'].map(id=>document.getElementById(id).value)].join('|'); }
  function garmentLabel(piece,index,total) {
    if(clothingPlan?.loose)return 'Предмет '+(index+1);
    if (/_obuv(?:_\d+)?$/.test(piece.name)) return 'Обувь — пара';
    if (total===1)return 'Вещь';
    if (/_verh$/.test(piece.name))return 'Верх';
    if (/_niz$/.test(piece.name))return 'Низ';
    return 'Вещь '+(index+1);
  }
  function resetClothingPlan() {
    clothingPlanTicket++;clothingPlan=null;
    document.getElementById('clothingWorkflow').hidden=true;document.getElementById('garmentCards').replaceChildren();
    document.getElementById('splitClothes').disabled=true;document.getElementById('addOutfit2').disabled=true;addOutfitBtn.disabled=true;
  }
  // A hidden tab gets no animation frames: the timer keeps the work going while the person is in another tab or app.
  const nextPaint=()=>new Promise(resolve=>{let done=false;const go=()=>{if(!done){done=true;setTimeout(resolve,0);}};requestAnimationFrame(go);setTimeout(go,100);});
  async function prepareClothing(result,label) {
    const ticket=++clothingPlanTicket;clothingPlan=null;document.getElementById('clothingWorkflow').hidden=false;
    document.getElementById('garmentCards').replaceChildren();document.getElementById('splitClothes').disabled=true;
    document.getElementById('clothingCount').textContent='Проверяем, сколько вещей на картинке…';document.getElementById('splitReason').textContent='На лист пока ничего не добавляется.';
    document.getElementById('addOutfit2').disabled=addOutfitBtn.disabled=true;
    await nextPaint();if(ticket!==clothingPlanTicket)return;
    try {
      const mm=result.loose?25.4/300:refMmPerPx();if(!mm)throw new Error('Нужен пурпурный эталон, чтобы сохранить размер одежды.');
      const pieces=result.loose?await splitLooseSheet(result.canvas,label):splitPieces(result.canvas,mm*(refMask.w0/result.canvas.width),label);
      if(ticket!==clothingPlanTicket)return;
      clothingPlan={canvas:result.canvas,loose:!!result.loose,pieces,split:result.loose||pieces.length===1,added:new Map(),geometry:clothingGeometryKey(),label};
      renderClothingPlan();
      if(result.loose&&pieces.length){addPreparedClothing(pieces.map((_,i)=>i));statusEl.textContent='Нарезано и добавлено на лист: '+pieces.length+' предметов. Размер без подгонки к кукле; проверь примерку.';}
    } catch(error) { document.getElementById('clothingCount').textContent='Не удалось подготовить вещи';document.getElementById('splitReason').textContent=error.name==='InvalidStateError'?'Браузер не смог обработать изображение. Закрой эту вкладку и открой редактор заново; если ошибка повторится — попробуй изображение меньшего размера.':error.message; }
  }
  function refreshClothingActions() {
    const plan=clothingPlan,add=document.getElementById('addOutfit2'),split=document.getElementById('splitClothes');
    if(!plan){add.disabled=addOutfitBtn.disabled=true;return;}
    const n=plan.pieces.length;const left=plan.pieces.filter((_,i)=>!sheetPieces.includes(plan.added.get(i))).length;
    split.disabled=n<=1||plan.split;split.textContent=plan.split&&n>1?'✓ Вещи разделены':'Разделить на вещи';
    add.disabled=addOutfitBtn.disabled=(!n||!plan.split||!left);add.hidden=!!n&&!plan.split&&n>1;
    add.textContent=!n?'Нет вещей для добавления':!plan.split?'Сначала раздели на вещи':!left?'✓ Всё добавлено на лист':n===1?'＋ Добавить вещь на лист':left===n?'＋ Добавить все вещи ('+n+') на лист':'＋ Добавить оставшиеся: '+left;
    addOutfitBtn.textContent='Добавить подготовленные вещи';
    const all=document.getElementById('downloadAllClothes');all.hidden=!(plan.split&&n>1);all.textContent='Скачать все PNG ('+n+') ↓';
    document.querySelectorAll('[data-garment-add]').forEach(button=>{const index=Number(button.dataset.garmentAdd);const added=sheetPieces.includes(plan.added.get(index));button.disabled=added;button.textContent=added?'✓ На листе':'＋ Добавить на лист';});
  }
  function renderClothingPlan() {
    const plan=clothingPlan;if(!plan)return;
    const n=plan.pieces.length;document.getElementById('clothingWorkflow').hidden=false;
    document.getElementById('clothingCount').textContent=n===0?'Вещи не найдены':n===1?'Найдена 1 вещь':n<5?'Найдены '+n+' вещи':'Найдено вещей: '+n;
    document.getElementById('splitReason').textContent=n===0?'Попробуй изменить допуск очистки. Очень мелкие части не считаются отдельными вещами.':n===1?'Делить не нужно: можно сразу скачать PNG или добавить вещь на лист.':plan.split?'Готово, каждая вещь отдельно. Скачай нужные или добавь их на лист для печати.':'Сейчас все вещи на одной картинке. Разделим их, чтобы каждая стала отдельным файлом: так их можно скачать и разложить на листе для печати.';
    document.getElementById('connectedClothesHint').hidden=plan.loose||n!==1;
    if(plan.loose)document.getElementById('splitReason').textContent='Предметы нарезаны и добавлены на печатный лист. Белый фон убран; размер пока исходный (300 dpi), без подгонки к кукле. Соприкасающиеся предметы могут остаться вместе.';
    const whole=document.getElementById('clothingWhole');whole.hidden=!(n>1&&!plan.split);if(!whole.hidden)document.getElementById('clothingWholePreview').src=plan.canvas.toDataURL('image/png');
    const cards=document.getElementById('garmentCards');cards.replaceChildren();
    if(plan.split)plan.pieces.forEach((piece,i)=>{
      const card=document.createElement('article');card.className='garment-card';
      const im=document.createElement('img');im.src=piece.frame instanceof HTMLImageElement?piece.frame.src:piece.frame.toDataURL('image/png');im.alt=garmentLabel(piece,i,n);im.className='garment-image checker';
      const heading=document.createElement('h3');heading.textContent=garmentLabel(piece,i,n);
      const size=document.createElement('p');size.className='hint';size.textContent='Отдельный PNG · '+piece.frame.width+' × '+piece.frame.height+' px';
      const download=document.createElement('button');download.className='button-secondary';download.textContent='Скачать PNG ↓';download.dataset.garmentDownload=String(i);
      download.addEventListener('click',async()=>{download.disabled=true;try{await saveBlob(piece.name+'.png',await pngBlob(piece.frame));showToast('PNG вещи подготовлен к скачиванию');}catch(e){document.getElementById('splitReason').textContent='Не удалось скачать: '+e.message;}finally{download.disabled=false;}});
      const add=document.createElement('button');add.className='primary';add.dataset.garmentAdd=String(i);add.addEventListener('click',()=>addPreparedClothing([i]));
      card.append(im,heading,size,download,add);cards.append(card);
    });
    refreshClothingActions();
  }
  function addPreparedClothing(indices) {
    if(!canEditBook())return;
    const plan=clothingPlan;if(!plan||!plan.split)return;
    if(!plan.loose&&plan.geometry!==clothingGeometryKey()){statusEl.textContent='Размер или отступы изменились. Перепроверь подготовленные вещи.';void prepareClothing({canvas:plan.canvas,loose:plan.loose},plan.label);return;}
    let count=0;
    for(const i of indices){if(sheetPieces.includes(plan.added.get(i)))continue;const original=plan.pieces[i];if(!original)continue;
      let name=original.name,k=2;while(sheetPieces.some(p=>p.name===name))name=original.name+'_'+k++;
      const piece={...original,name};sheetPieces.push(piece);plan.added.set(i,piece);count++;
    }
    if(count){renderPieceList();statusEl.textContent=count===1?'Вещь добавлена на лист. Остальные вещи можно скачать или добавить отдельно.':'Добавлено на лист: '+count+' вещи. На шаге «Печать» можно проверить раскладку.';showToast(count===1?'Вещь добавлена на лист':'Добавлено вещей: '+count);}
    refreshClothingActions();
  }
  // Clothes library: ready items (cut out, with their cut lines) from the catalog books and the owner's projects. An item goes on the
  // sheet as it is, scaled from the doll height it was made for to the current one; no model is involved.
  let libraryItems=null,librarySource='',libraryTicket=0;
  async function openLibrary(){
    const status=document.getElementById('libraryStatus');document.getElementById('libraryUpload').hidden=!account?.admin;document.getElementById('libraryDialog').showModal();
    if(!libraryItems){status.textContent='Загружаю гардероб…';try{libraryItems=(await accountAPI('library')).items;}catch(e){status.textContent='Не удалось открыть гардероб: '+e.message;return;}}
    await renderLibrary();
  }
  async function renderLibrary(){
    const grid=document.getElementById('libraryGrid'),status=document.getElementById('libraryStatus'),ticket=++libraryTicket;
    // For the owner: items without a type never reach the fitting room, so they get their own tab first.
    const UNTYPED='#untyped',untyped=account?.admin?libraryItems.filter(i=>!i.hidden&&!fitRule(libraryKind(i))&&libraryKind(i)!=='thing').length:0;
    const sources=[...new Set(libraryItems.map(i=>i.source))];if(librarySource&&!sources.includes(librarySource)&&!(librarySource===UNTYPED&&untyped))librarySource='';
    const inTab=(i,s)=>s===UNTYPED?!i.hidden&&!fitRule(libraryKind(i))&&libraryKind(i)!=='thing':!s||i.source===s;
    document.getElementById('librarySources').replaceChildren(...['',...(untyped?[UNTYPED]:[]),...sources].map(s=>{const b=document.createElement('button');b.type='button';b.textContent=(s===UNTYPED?'⚠ Без типа — мастера их не видят':s||'Все')+' · '+libraryItems.filter(i=>inTab(i,s)).length;b.setAttribute('aria-pressed',String(s===librarySource));b.onclick=()=>{librarySource=s;void renderLibrary();};return b;}));
    document.getElementById('libraryAutoKind').hidden=!untyped;
    const list=libraryItems.filter(i=>inTab(i,librarySource)),imgs=new Map();
    status.textContent=list.length?'Загружаю картинки…':'В гардеробе пока нет вещей. Они появятся, когда в проекте «Гардероб» будет одежда.';
    grid.replaceChildren(...list.map(it=>{
      const card=document.createElement('div');card.className='garment-card'+(it.hidden?' library-hidden':'');
      const img=document.createElement('img');img.className='garment-image checker';img.alt=it.name;imgs.set(it.h,img);
      const title=document.createElement('strong');title.textContent=it.name;
      const meta=document.createElement('p');meta.className='hint';meta.textContent=it.source+' · '+Math.round(it.wmm)+' × '+Math.round(it.hmm)+' мм'+(it.hidden?' · скрыта от мастеров':'');
      const add=document.createElement('button');add.type='button';add.className='button-secondary';add.textContent='＋ Добавить на лист';add.onclick=()=>void addLibraryItem(it,add);
      card.append(img,title,meta,add);
      // The owner says what an item is; the fitting room puts it on the doll by that.
      if(account?.admin){const sel=document.createElement('select');sel.setAttribute('aria-label','Тип вещи');
        sel.append(new Option(libraryKind(it)&&!it.kind?'Тип: '+KIND_TITLES[libraryKind(it)]+' (из книги)':'Тип не выбран',''),...Object.entries(KIND_TITLES).map(([k,t])=>new Option(t,k)));sel.value=it.kind||'';
        sel.onchange=async()=>{sel.disabled=true;try{await accountPost('library.kind',{h:it.h,kind:sel.value});it.kind=sel.value||null;void renderFitting();if(librarySource==='#untyped')void renderLibrary();}catch(e){showToast(e.message);sel.value=it.kind||'';}finally{sel.disabled=false;}};card.append(sel);}
      if(account?.admin){const hide=document.createElement('button');hide.type='button';hide.className='text-button';hide.textContent=it.hidden?'Вернуть мастерам':'Скрыть от мастеров';
        hide.onclick=async()=>{hide.disabled=true;try{await accountPost('library.hide',{h:it.h,hide:!it.hidden});it.hidden=!it.hidden;void renderLibrary();}catch(e){showToast(e.message);hide.disabled=false;}};card.append(hide);
        const del=document.createElement('button');del.type='button';del.className='text-button danger';del.textContent='Удалить из библиотеки';
        del.onclick=async()=>{if(!confirm('Удалить «'+it.name+'» из библиотеки? В уже собранных проектах вещь останется.'))return;del.disabled=true;
          try{await accountPost('library.delete',{h:it.h});libraryItems=libraryItems.filter(x=>x!==it);fitting.wear.delete(it.h);void renderLibrary();void renderFitting();}catch(e){showToast(e.message);del.disabled=false;}};card.append(del);}
      return card;
    }));
    if(!list.length)return;
    let previews=new Map();try{previews=await fetchPreviews(list.map(i=>i.h));}catch(_){}
    if(ticket!==libraryTicket)return;
    for(const [h,img] of imgs){const p=previews.get(h);if(p)img.src=URL.createObjectURL(p.blob);}
    // No preview (the server could not make one): the full picture instead, a few at a time.
    await eachLimited([...imgs].filter(([h])=>!previews.has(h)),3,async([h,img])=>{try{const b=await fetchImage(h);if(ticket===libraryTicket)img.src=URL.createObjectURL(b);}catch(_){}});
    if(ticket!==libraryTicket)return;
    status.textContent='Вещей: '+list.length+'. Вещь ложится на лист с готовыми контурами резки, под высоту куклы этого проекта.';
  }
  // A library item as a sheet piece (full pictures, cut lines), scaled from the doll height it was made for to the current one.
  async function loadLibraryPiece(it){
    const j=await accountAPI('library.piece&h='+it.h),s=j.piece,isRef=v=>typeof v==='string'&&/^img:[a-f0-9]{64}$/.test(v);
    const p=await restorePieceImages({...s,print:s.printLayout?null:isRef(s.print)?await fetchImage(s.print.slice(4)):null,frame:await fetchImage(s.frame.slice(4))});
    p.role='item';p.lib=it.h;delete p.fit;
    const k=(Number(document.getElementById('dollMM').value)||160)/(Number(j.dollMM)||160);if(Math.abs(k-1)>0.001)resizeGarment(p,p.wmm*k,p.hmm*k);
    let name=p.name,n=2;while(sheetPieces.some(q=>q.name===name))name=p.name+'_'+n++;p.name=name;
    return p;
  }
  async function addLibraryItem(it,btn){
    if(!canEditBook())return;
    const label=btn.textContent;btn.disabled=true;btn.textContent='Добавляю…';
    try{
      sheetPieces.push(await loadLibraryPiece(it));renderPieceList();refreshClothingActions();
      btn.textContent='✓ На листе';showToast('Вещь «'+it.name+'» добавлена на лист');
      setTimeout(()=>{btn.textContent=label;btn.disabled=false;},2500);
    }catch(e){btn.textContent=label;btn.disabled=false;showToast('Не удалось добавить вещь: '+e.message);}
  }

  // Fitting room: the generated child, and the library items by kind. A tap puts an item on the child at the place its kind has on
  // the doll (the same rules as the fitting on the print step), a second tap takes it off; «Гардероб собран» puts the worn
  // items on the sheet at those sizes.
  const KIND_TITLES={dress:'Платье',top:'Верх',robe:'Куртка / пальто',pants:'Брюки / джинсы',shorts:'Шорты',skirt:'Юбка',outfit:'Образ целиком',shoes:'Обувь',hat:'Шапка',accessory:'Аксессуар',animal:'Животное',thing:'Не показывать в примерочной'};
  const FIT_GROUPS=[['all','Всё',null,'✨'],['dress','Платья',['dress'],'👗'],['top','Верх',['top','robe'],'👕'],['bottom','Низ',['pants','shorts','skirt'],'👖'],['outfit','Образы',['outfit'],'🧸'],['shoes','Обувь',['shoes'],'👟'],['hat','Шапки',['hat'],'🧢'],['acc','Аксессуары',['accessory'],'👜'],['animal','Животные',['animal'],'🐱']];
  const FIT_Z={shoes:1,pants:2,shorts:2,skirt:2,dress:3,outfit:3,top:4,robe:5,hat:6,accessory:7,animal:8};
  // Where an item goes on the doll (shares of the doll height). Every item keeps its own size: the sheets are drawn in Canva to the
  // scale of a doll of a known height (the library project's doll height). Shoes stand on the soles; an accessory
  // starts by the right hand and an animal at the feet, both free to drag.
  // Tops sit with their shoulders on the doll's shoulders (the print-step rule at .245 left the vest straps showing).
  const FIT_SHOULDER=.22;const FIT_WAIST=.515;
  const fitRule=kind=>kind==='outfit'?{length:.755,y:FIT_SHOULDER}:kind==='shoes'?{bottom:true}:kind==='accessory'?{free:'hand'}:kind==='animal'?{free:'feet'}:['dress','robe','top'].includes(kind)?{...garmentTypes[kind],y:FIT_SHOULDER}:['pants','shorts','skirt'].includes(kind)?{...garmentTypes[kind],y:FIT_WAIST}:garmentTypes[kind]?.length?garmentTypes[kind]:null;
  // One item per place on the body: a new top (a jumper, a T-shirt, a coat or a robe) replaces the old one, and so on. Accessories
  // and animals are not worn, any number of them can stand by the doll.
  const fitSlot=(kind,it)=>['pants','shorts','skirt'].includes(kind)?'bottom':kind==='robe'?'top':kind==='accessory'||kind==='animal'?kind+':'+it.h:kind;
  // What an item is: the owner's label first, then the kinds the «Моя куколка» book already knows, then a pair of shoes by its name.
  function libraryKind(it){
    if(it.kind)return it.kind;const m=/^mydoll_(\d{3})$/.exec(it.name);if(m){const k=myDollTypes[Number(m[1])-1];return k==='set'?'outfit':k||null;}
    return /_obuv(_\d+)?$/.test(it.name)?'shoes':null;
  }
  // offsets: how far the person dragged an item from its place, in doll heights (so it keeps on any doll size and on the sheet).
  const fitting={wear:new Map(),group:'all',urls:new Map(),loading:null,busy:false,offsets:new Map(),scales:new Map(),sel:null};
  // Size of a worn item: what this person set, else the owner's size for everyone, else as drawn.
  const fitScale=it=>fitting.scales.get(it.h)??(Number(it.scale)||1);
  function fitDoll(){
    if(gResult&&refMask){const s=gResult.width/refMask.w0;return {src:G.out.src,w:gResult.width,h:gResult.height,top:refMask.top*s,bottom:refMask.bottom*s,cx:refMask.cx*s};}
    const d=sheetPieces.find(p=>p.role==='doll');
    if(d?.print){const w=d.print.naturalWidth||d.print.width,h=d.print.naturalHeight||d.print.height;return {src:d.print.src||d.print.toDataURL('image/png'),w,h,top:0,bottom:h,cx:w/2};}
    return null;
  }
  // Heads differ from doll to doll: a hat is drawn for the head of the Canva sheet doll (its width at the brow, hair included, is
  // .153 of her height) and grows or shrinks with this doll's head, measured once on her picture.
  const HEAD_REF=.153;
  function dollHeadScale(doll){
    if(fitting.head?.src===doll.src)return fitting.head.k;
    const img=document.getElementById('fitDoll');if(!img.complete||!img.naturalWidth||img.getAttribute('src')!==doll.src)return 1;
    const k=Math.min(1,300/doll.w),W=Math.round(doll.w*k),Hc=Math.round(doll.h*k),c=document.createElement('canvas');c.width=W;c.height=Hc;
    const g=c.getContext('2d',{willReadFrequently:true});g.drawImage(img,0,0,W,Hc);const d=g.getImageData(0,0,W,Hc).data,H=(doll.bottom-doll.top)*k;
    const widths=[.05,.06,.07,.08,.09].map(f=>{const y=Math.round(doll.top*k+f*H);let l=-1,r=-1;for(let x=0;x<W;x++){const i=(y*W+x)*4;if(d[i+3]>128&&Math.min(d[i],d[i+1],d[i+2])<232){if(l<0)l=x;r=x;}}return l<0?0:(r-l+1)/H;}).filter(Boolean).sort((a,b)=>a-b);
    const s=widths.length?Math.min(1.25,Math.max(.75,widths[widths.length>>1]/HEAD_REF)):1;
    fitting.head={src:doll.src,k:s};return s;
  }
  document.getElementById('fitDoll').addEventListener('load',()=>{if(fitting.wear.size)drawFitStage();});
  async function fitPreviewURLs(list){
    const need=list.filter(it=>!fitting.urls.has(it.h));if(!need.length)return;
    let previews=new Map();try{previews=await fetchPreviews(need.map(i=>i.h));}catch(_){}
    for(const it of need){const p=previews.get(it.h);if(p)fitting.urls.set(it.h,URL.createObjectURL(p.blob));}
    await eachLimited(need.filter(it=>!fitting.urls.has(it.h)),3,async it=>{try{fitting.urls.set(it.h,URL.createObjectURL(await fetchImage(it.h)));}catch(_){}});
  }
  function wearItem(it){
    const kind=libraryKind(it),slot=fitSlot(kind,it);
