    const off={dress:['top','bottom','outfit'],outfit:['top','bottom','dress'],top:['dress','outfit'],bottom:['dress','outfit']}[slot]||[];
    for(const s of off)fitting.wear.delete(s);fitting.wear.set(slot,it);fitting.last=it.h;
