  function fitTarget(){const w=[...fitting.wear.values()];return w.find(it=>it.h===fitting.sel)||w.find(it=>it.h===fitting.last)||w[w.length-1]||null;}

  function drawFitStage(){try{const h=document.getElementById('fitHint');if(h)h.hidden=!fitting.wear.size||localStorage.getItem('mbHintDone')==='1';}catch(_){}
    const doll=fitDoll(),stage=document.getElementById('fitStage'),img=document.getElementById('fitDoll');
    stage.querySelectorAll('.fit-wear').forEach(el=>el.remove());
    document.getElementById('fitEmpty').hidden=!!doll;img.hidden=!doll;document.getElementById('fittingRoom').classList.toggle('no-doll',!doll);
    if(!doll){document.getElementById('fitClear').disabled=!fitting.wear.size;document.getElementById('fitAdd').disabled=!fitting.wear.size&&!sheetPieces.some(p=>!isDollPiece(p));return;}
    stage.style.aspectRatio=doll.w+'/'+doll.h;if(img.getAttribute('src')!==doll.src)img.src=doll.src;
    const H=doll.bottom-doll.top;
    for(const it of [...fitting.wear.values()].sort((a,b)=>(FIT_Z[libraryKind(a)]||9)-(FIT_Z[libraryKind(b)]||9))){
      const r=fitRule(libraryKind(it)),url=fitting.urls.get(it.h);if(!r||!url||!(it.hmm>0))continue;
      // Every item at its own size, as on the Canva sheet: millimetres of the item over the height of the doll it was drawn for.
      const per=H/(Number(it.dollMM)||160),sc=fitScale(it)*(libraryKind(it)==='hat'?dollHeadScale(doll):1),ih=it.hmm*per*sc,iw=it.wmm*per*sc,el=document.createElement('img');if(fitting.sel===it.h)el.classList.add('selected');el.className='fit-wear';el.alt='';el.src=url;el.dataset.h=it.h;el.draggable=false;
      const off=fitting.offsets.get(it.h)||{x:0,y:0};
      const x=r.free?Math.max(0,Math.min(doll.w-iw,r.free==='hand'?doll.cx+H*.16:doll.cx-H*.1-iw)):doll.cx-iw/2;
      // A hat sits with its brim on the forehead, whatever its height.
      const y=libraryKind(it)==='hat'?doll.top+H*.122-ih:r.bottom||r.free==='feet'?doll.bottom-ih:r.free==='hand'?doll.top+H*.42:doll.top+r.y*H;
      Object.assign(el.style,{left:(x+off.x*H)/doll.w*100+'%',top:(y+off.y*H)/doll.h*100+'%',width:iw/doll.w*100+'%',height:ih/doll.h*100+'%',zIndex:String(FIT_Z[libraryKind(it)]||9)});
      stage.append(el);
    }
    // «Сейчас надето»: a small picture of every worn item, × takes it off.
    document.getElementById('fitWorn').replaceChildren(...[...fitting.wear.values()].map(it=>{const chip=document.createElement('button');chip.type='button';chip.className='fit-chip';chip.title='Снять: '+(KIND_TITLES[libraryKind(it)]||it.name);
      const im=document.createElement('img');im.alt='';const u=fitting.urls.get(it.h);if(u)im.src=u;const x=document.createElement('span');x.textContent='×';x.setAttribute('aria-hidden','true');
      chip.append(im,x);chip.onclick=()=>{wearItem(it);void renderFitting();};return chip;}));
    // «Подогнать по фигуре» is always there while something is worn: for the item tapped on the doll, else the one put on last.
    if(fitting.sel&&![...fitting.wear.values()].some(it=>it.h===fitting.sel))fitting.sel=null;const selIt=fitTarget();
    const tools=document.getElementById('fitTools');tools.hidden=!selIt;if(selIt){const se=stage.querySelector('.fit-wear[data-h="'+selIt.h+'"]');const mid=se?parseFloat(se.style.top)+parseFloat(se.style.height)/2:0;tools.classList.toggle('at-top',mid>52);}
    if(selIt){document.getElementById('fitToolsName').textContent='Подогнать по фигуре: '+(KIND_TITLES[libraryKind(selIt)]||selIt.name).toLowerCase();document.getElementById('fitSizeValue').textContent=Math.round(fitScale(selIt)*100)+' %';
      document.getElementById('fitSizeSave').hidden=!account?.admin;document.getElementById('fitSizeSave').textContent=Math.abs(fitScale(selIt)-(Number(selIt.scale)||1))<.001?'✓ Размер для всех':'Запомнить для всех';}
    document.getElementById('fitClear').disabled=!fitting.wear.size;
    document.getElementById('fitAdd').disabled=(!fitting.wear.size&&!sheetPieces.some(p=>!isDollPiece(p)))||fitting.busy;
    document.getElementById('fitAdd').textContent='Гардероб собран'+(fitting.wear.size?' ('+fitting.wear.size+')':'')+(chosenBook?' → в печать':' → выбрать книгу');
