  async function renderFitting(){
    const status=document.getElementById('fitStatus'),grid=document.getElementById('fitGrid');
    if(!libraryItems){if(!fitting.loading)fitting.loading=accountAPI('library').then(j=>{libraryItems=j.items;}).finally(()=>{fitting.loading=null;});
      status.textContent='Загружаю вещи…';try{await fitting.loading;}catch(e){status.textContent='Не удалось загрузить вещи: '+e.message;return;}}
    const wearable=libraryItems.filter(it=>!it.hidden&&fitRule(libraryKind(it)));
    document.getElementById('fitCount').textContent=wearable.length?'Вещей в гардеробе: '+wearable.length:'';
    const groups=FIT_GROUPS.filter(([id,,kinds])=>!kinds||wearable.some(it=>kinds.includes(libraryKind(it))));
    if(!groups.some(([id])=>id===fitting.group))fitting.group='all';
    document.getElementById('fitTabs').replaceChildren(...groups.map(([id,title,kinds,icon])=>{const b=document.createElement('button');b.type='button';b.className='fit-tab';b.setAttribute('aria-pressed',String(id===fitting.group));
      const i=document.createElement('span');i.className='fit-tab-icon';i.setAttribute('aria-hidden','true');i.textContent=icon;
      // The tab shows a real picture of one item from that section (same style as the items), «Всё» a plain star.
      if(!kinds){i.innerHTML='<svg viewBox="0 0 24 24" width="20" height="20"><path d="M12 2.5l2.2 6.3 6.3 2.2-6.3 2.2L12 19.5l-2.2-6.3-6.3-2.2 6.3-2.2z" fill="currentColor"/></svg>';}
      else{const rp=wearable.find(it=>kinds.includes(libraryKind(it)));if(rp){i.dataset.rep=rp.h;const ru=fitting.urls.get(rp.h);if(ru){const pic=new Image();pic.alt='';pic.src=ru;i.textContent='';i.append(pic);i.classList.add('has-pic');}}}
      const t=document.createElement('span');t.textContent=title;
      const n=document.createElement('small');n.textContent=String(wearable.filter(it=>!kinds||kinds.includes(libraryKind(it))).length);
      b.append(i,t,n);b.onclick=()=>{fitting.group=id;void renderFitting();};return b;}));
    const kinds=FIT_GROUPS.find(([id])=>id===fitting.group)[2],list=wearable.filter(it=>!kinds||kinds.includes(libraryKind(it)));
    status.textContent=list.length?'':account?.admin?'Пока нечего мерить. Открой «Все вещи гардероба» и выбери вещам тип: платье, верх, обувь…':'Вещей для примерки пока нет.';
    const worn=new Set(fitting.wear.values());
    grid.replaceChildren(...list.map(it=>{const b=document.createElement('button');b.type='button';b.className='fit-tile';b.setAttribute('aria-pressed',String(worn.has(it)));b.title=it.name;if(sheetPieces.some(q=>q.lib===it.h))b.dataset.inbook='1';
      const pic=document.createElement('span');pic.className='fit-tile-pic';const im=document.createElement('img');im.alt='';im.dataset.h=it.h;const u=fitting.urls.get(it.h);if(u)im.src=u;pic.append(im);
      const t=document.createElement('span');t.className='fit-tile-name';t.textContent=KIND_TITLES[libraryKind(it)]||it.name;
      b.append(pic,t);
      // Two taps on the same item in a row (mouse or finger): it stays on the doll and goes on the sheet. The first tap already put it
      // on, so the second only adds it (the tiles are redrawn in between, the item is what counts).
      b.onclick=()=>{const now=Date.now();if(fitTap.it===it&&now-fitTap.t<500){fitTap={};if(![...fitting.wear.values()].includes(it))wearItem(it);void renderFitting();setTimeout(()=>void addWornToBook([it]),80);return;}
        fitTap={it,t:now};wearItem(it);void renderFitting();};return b;}));
    drawFitStage();
    const reps=groups.map(g=>g[2]?wearable.find(it=>g[2].includes(libraryKind(it))):null).filter(Boolean);
    await fitPreviewURLs(list.concat([...fitting.wear.values()],reps));
    document.querySelectorAll('#fitTabs .fit-tab-icon[data-rep]:not(.has-pic)').forEach(i=>{const u=fitting.urls.get(i.dataset.rep);if(u){const pic=new Image();pic.alt='';pic.src=u;i.textContent='';i.append(pic);i.classList.add('has-pic');}});
    grid.querySelectorAll('img[data-h]').forEach(im=>{if(!im.getAttribute('src')){const u=fitting.urls.get(im.dataset.h);if(u)im.src=u;}});
    drawFitStage();
  }
  document.getElementById('fitClear').onclick=()=>{fitting.wear.clear();fitting.offsets.clear();fitting.scales.clear();fitting.sel=null;void renderFitting();};
  // − / + change the tapped item by 3 % (50–160 %); «Как было» goes back to the size for everyone.
  {const selected=()=>fitTarget();
   const step=d=>{const it=selected();if(!it)return;fitting.scales.set(it.h,Math.min(1.6,Math.max(.5,Math.round((fitScale(it)+d)*100)/100)));drawFitStage();};
   document.getElementById('fitSmaller').onclick=()=>step(-.03);document.getElementById('fitBigger').onclick=()=>step(.03);
   document.getElementById('fitSizeReset').onclick=()=>{const it=selected();if(!it)return;fitting.scales.delete(it.h);drawFitStage();};
   document.getElementById('fitSizeSave').onclick=async e=>{const it=selected();if(!it)return;const b=e.currentTarget,sc=fitScale(it);b.disabled=true;
     try{await accountPost('library.scale',{h:it.h,scale:sc});it.scale=sc;fitting.scales.delete(it.h);showToast('Размер '+Math.round(sc*100)+' % теперь у всех мастеров');}catch(err){showToast(err.message);}finally{b.disabled=false;drawFitStage();}};}
  // Drag a worn item to put it where it looks right (mouse or finger); the shift is kept in doll heights.
  {const stage=document.getElementById('fitStage');let drag=null,lastTap={h:null,t:0},tapTimer=0;
   stage.addEventListener('pointerdown',e=>{const el=e.target.closest('.fit-wear');if(!el)return;e.preventDefault();try{el.setPointerCapture(e.pointerId);}catch(_){}el.classList.add('dragging');
     const doll=fitDoll();if(!doll)return;const rect=stage.getBoundingClientRect(),off=fitting.offsets.get(el.dataset.h)||{x:0,y:0};
     drag={el,id:e.pointerId,x0:e.clientX,y0:e.clientY,left0:parseFloat(el.style.left),top0:parseFloat(el.style.top),off,perX:(doll.bottom-doll.top)/doll.w*rect.width,perY:(doll.bottom-doll.top)/doll.h*rect.height,rect};});
   stage.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x0,dy=e.clientY-drag.y0;if(!drag.moved&&Math.hypot(dx,dy)<=16)return;drag.moved=true;
     drag.el.style.left=drag.left0+dx/drag.rect.width*100+'%';drag.el.style.top=drag.top0+dy/drag.rect.height*100+'%';});
   const end=e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x0,dy=e.clientY-drag.y0;drag.el.classList.remove('dragging');
     if(drag.moved)fitting.offsets.set(drag.el.dataset.h,{x:drag.off.x+dx/drag.perX,y:drag.off.y+dy/drag.perY});else{drag.el.style.left=drag.left0+'%';drag.el.style.top=drag.top0+'%';const h=drag.el.dataset.h,now=Date.now();if(lastTap.h===h&&now-lastTap.t<500){clearTimeout(tapTimer);lastTap={h:null,t:0};const it=[...fitting.wear.values()].find(x=>x.h===h);if(it)void (async()=>{for(let i=0;i<50&&fitting.busy;i++)await new Promise(r=>setTimeout(r,100));await addWornToBook([it]);})();}else{lastTap={h,t:now};clearTimeout(tapTimer);tapTimer=setTimeout(()=>{fitting.sel=fitting.sel===h?null:h;drawFitStage();},510);}}drag=null;};
   stage.addEventListener('pointerup',end);stage.addEventListener('pointercancel',end);}
  // «На листе для печати»: what is already on the print sheet, next to the wardrobe — in the empty space on the right when the screen
  // is wide, above the clothes otherwise — so nothing is forgotten and nothing goes on the sheet twice.
  const onSheet=h=>sheetPieces.some(p=>p.lib===h);
  function renderSheetRail(){
    const rail=document.getElementById('sheetRail'),stage=document.querySelector('.step-nav [aria-current]')?.dataset.stage;
    rail.hidden=!workingProject||!['3','5'].includes(stage);if(rail.hidden)return;
    const list=document.getElementById('sheetRailList');document.getElementById('sheetRailCount').textContent=String(sheetPieces.length);document.getElementById('sheetRailEmpty').hidden=!!sheetPieces.length;
    list.replaceChildren(...sheetPieces.map((p,i)=>{const el=document.createElement('div');el.className='sheet-rail-item';el.title=p.name;
      const c=document.createElement('canvas');c.width=c.height=120;const k=Math.min(112/p.print.width,112/p.print.height);try{c.getContext('2d').drawImage(p.print,(120-p.print.width*k)/2,(120-p.print.height*k)/2,p.print.width*k,p.print.height*k);}catch(_){}
      const t=document.createElement('span');t.textContent=isDollPiece(p)?'Кукла':KIND_TITLES[p.fit?.kind==='set'?'outfit':p.fit?.kind]||'Вещь';
      const x=document.createElement('button');x.type='button';x.textContent='×';x.setAttribute('aria-label','Убрать с листа: '+p.name);
      x.onclick=()=>{if(!canEditBook())return;sheetPieces.splice(i,1);renderPieceList();void renderFitting();showToast('Убрано с листа');};
      el.append(c,t,x);return el;}));
    placeSheetRail();
  }
  function placeSheetRail(){
    const rail=document.getElementById('sheetRail');if(rail.hidden)return;
    const host=document.querySelector('[data-step]:not([hidden])');if(host&&rail.parentElement!==host){const anchor=host.querySelector('#fittingRoom,#bookChoices');if(anchor)anchor.before(rail);else host.prepend(rail);}
    const stage=document.querySelector('[data-step]:not([hidden])'),r=stage?.getBoundingClientRect(),free=r?innerWidth-r.right-32:0;
    if(free>=230){rail.classList.add('side');Object.assign(rail.style,{left:(r.right+16)+'px',top:'120px',width:Math.min(free,320)+'px'});}
    else{rail.classList.remove('side');rail.removeAttribute('style');}
  }
  addEventListener('resize',placeSheetRail);
  let fitTap={};
  // «В книгу»: a liked item goes onto the print sheet (the future book) and flies into the «Печать» tab; the person keeps trying things on.
  function flyToBook(list){
    if(!list.length||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
    const tab=document.querySelector('.step-nav [data-stage="4"] .step-number')||document.querySelector('.step-nav [data-stage="4"]');
    const t=tab&&tab.getBoundingClientRect();const ok=t&&t.width>0;
    const pulse=()=>{try{for(const el of [document.getElementById('sheetBadge'),document.querySelector('.step-nav [data-stage="4"]')])if(el&&el.getClientRects().length)el.animate([{transform:'scale(1)'},{transform:'scale(1.28)'},{transform:'scale(1)'}],{duration:480,easing:'cubic-bezier(.2,.9,.3,1.4)'});}catch(_){}};
    list.forEach(({c,r},i)=>{
      Object.assign(c.style,{position:'fixed',left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px',margin:'0',maxWidth:'none',zIndex:'9500',pointerEvents:'none',animation:'none',outline:'none',transformOrigin:'50% 50%',filter:'drop-shadow(0 10px 14px #55203f66)'});
      document.body.append(c);
      const dx=ok?t.left+t.width/2-(r.left+r.width/2):0,dy=ok?t.top+t.height/2-(r.top+r.height/2):-220,sc=Math.max(.06,Math.min(.5,26/Math.max(r.width,r.height,1)));
      try{
        const an=c.animate([{transform:'translate(0,0) scale(1) rotate(0deg)',opacity:1,offset:0},
          {transform:'translate('+dx*.22+'px,'+(dy*.22-70)+'px) scale(.78) rotate(-9deg)',opacity:1,offset:.32},
          {transform:'translate('+dx+'px,'+dy+'px) scale('+sc+') rotate(16deg)',opacity:.85,offset:1}],
          {duration:900,delay:i*140,easing:'cubic-bezier(.55,.05,.25,1)',fill:'both'});
        an.onfinish=()=>{c.remove();pulse();};an.oncancel=()=>c.remove();
      }catch(_){c.remove();pulse();}
    });
  }
  async function addWornToBook(items){try{localStorage.setItem('mbHintDone','1');const h=document.getElementById('fitHint');if(h)h.hidden=true;}catch(_){}
    if(!canEditBook()||!items.length||fitting.busy)return;
    const todo=items.filter(it=>!sheetPieces.some(q=>q.lib===it.h));
    if(!todo.length){showToast('Эта вещь уже в книге');return;}
    const button=document.getElementById('fitAdd');fitting.busy=true;button.disabled=true;button.textContent='Добавляю…';
    // Pictures that will fly: copies of the items as they stand on the doll right now.
    const flyers=todo.map(it=>{const el=document.querySelector('#fitStage .fit-wear[data-h="'+it.h+'"]');return el?{c:el.cloneNode(),r:el.getBoundingClientRect()}:null;}).filter(Boolean);
    // The flight starts at once; loading the full picture takes a few seconds and the tap must visibly do something right away.
    flyToBook(flyers);for(const f of flyers){const o=document.querySelector('#fitStage .fit-wear[data-h="'+f.c.dataset.h+'"]');if(o)o.style.visibility='hidden';}
    const done=[];
    try{for(const it of todo){const kind=libraryKind(it),p=await loadLibraryPiece(it);
        // Every item at its own size, as on the doll here (already scaled to this doll's height). The kind tells the print-step
        // fitting where it goes.
        p.fit={version:1,kind:kind==='outfit'?'set':garmentTypes[kind]?kind:'accessory',percent:100,baseW:p.wmm,baseH:p.hmm};
        {const doll=fitDoll(),sc=fitScale(it)*(kind==='hat'&&doll?dollHeadScale(doll):1);if(Math.abs(sc-1)>.001){resizeGarment(p,p.wmm*sc,p.hmm*sc);if(p.fit)p.fit.percent=Math.round((p.fit.percent||100)*sc);}}
        // Where the person dragged it: the same shift in the print-step fitting (mm of the doll height).
        const off=fitting.offsets.get(it.h);if(off){const doll=Number(document.getElementById('dollMM').value)||160;p.fit={...p.fit,offset:{x:off.x*doll,y:off.y*doll}};}
        p.lib=it.h;sheetPieces.push(p);done.push(it);}
      if(done.length){
        const keep=new Set(done.map(it=>it.h));
        for(const [slot,it] of [...fitting.wear.entries()])if(keep.has(it.h)){fitting.wear.delete(slot);fitting.offsets.delete(it.h);fitting.scales.delete(it.h);if(fitting.sel===it.h)fitting.sel=null;}
        showToast(done.length===1?'Вещь в книге. Примеряй дальше или иди в «Печать»':'В книге вещей: '+done.length+'. Примеряй дальше или иди в «Печать»');
      }
    }catch(e){showToast('Не удалось добавить вещь: '+e.message);}
    finally{fitting.busy=false;if(done.length){renderPieceList();refreshClothingActions();}void renderFitting();}
  }
  document.querySelector('#fittingRoom .fit-body').addEventListener('click',e=>{if(fitting.sel&&!e.target.closest('.fit-wear,.fit-tools,.fit-tile,.fit-tab,.fit-chip,.fit-actions,button')){fitting.sel=null;drawFitStage();}});
  document.getElementById('fitAdd').onclick=async()=>{
    if(fitting.wear.size){await addWornToBook([...fitting.wear.values()]);await new Promise(r=>setTimeout(r,950));}
    setStage(chosenBook?'4':'5'); // the book step only until a book is chosen
  };
  document.getElementById('showLibrary').onclick=()=>void openLibrary();
  // Sheets uploaded again: the same garments get the types their old pictures had; only really new things are left to sort.
  document.getElementById('libraryAutoKind').onclick=async e=>{
    const b=e.currentTarget,status=document.getElementById('libraryStatus');b.disabled=true;status.textContent='Сравниваю вещи с прежними… до пары минут.';
    try{const r=await accountPost('library.autokind',{});libraryItems=(await accountAPI('library')).items;await renderLibrary();
      status.textContent=r.matched?'Тип подобран для вещей: '+r.matched+'. Проверь их — и разметь оставшиеся.':'Похожих прежних вещей не нашлось — разметь вручную.';void renderFitting();}
    catch(err){status.textContent='Не получилось: '+err.message;}finally{b.disabled=false;}
  };
  // Owner: PNG sheets -> cut-out items (the same cutting as «Своя вещь») -> shown first -> added to the library in one go.
  let libraryPending=[];
  function renderLibraryPending(){
    const box=document.getElementById('libraryPending');
    box.replaceChildren(...libraryPending.map((p,i)=>{const card=document.createElement('div');card.className='garment-card';
      const c=document.createElement('canvas');const k=Math.min(240/p.print.width,240/p.print.height,1);c.width=Math.max(1,Math.round(p.print.width*k));c.height=Math.max(1,Math.round(p.print.height*k));c.getContext('2d').drawImage(p.print,0,0,c.width,c.height);
      const t=document.createElement('strong');t.textContent=p.name;const m=document.createElement('p');m.className='hint';m.textContent=Math.round(p.wmm)+' × '+Math.round(p.hmm)+' мм';
      const x=document.createElement('button');x.type='button';x.className='text-button';x.textContent='Не добавлять';x.onclick=()=>{libraryPending.splice(i,1);renderLibraryPending();};
      card.append(c,t,m,x);return card;}));
    const n=libraryPending.length;document.getElementById('libraryAddAll').hidden=document.getElementById('libraryClearPending').hidden=!n;
    document.getElementById('libraryAddAll').textContent='Добавить в библиотеку · '+n;
  }
  document.getElementById('libraryFiles').onchange=async e=>{
    const files=[...e.target.files].filter(f=>f.type.startsWith('image/'));e.target.value='';if(!files.length)return;
    const status=document.getElementById('libraryUploadStatus'),group=document.getElementById('libraryGroup');
    if(!group.value.trim())group.value=files[0].name.replace(/\.[^.]+$/,'').slice(0,80);
    try{
      for(let i=0;i<files.length;i++){
        status.textContent='Нарезаю лист '+(i+1)+' из '+files.length+'…';await nextPaint();
        const img=await loadImg(files[i]);
        if(hasMagentaMannequin(img)){showToast('«'+files[i].name+'» на шаблоне куклы — такой образ добавь через «Своя вещь».');continue;}
        const r=cleanLooseSheet(img),label=safeName(files[i].name)||'list';
        const parts=await splitLooseSheet(r.canvas,label);r.canvas.width=r.canvas.height=0;
