  const garmentTypes={dress:{title:'Платье',length:.51,y:.245},robe:{title:'Халат / пальто',length:.55,y:.245},top:{title:'Верх',length:.30,y:.245},pants:{title:'Брюки / джинсы',length:.425,y:.55},shorts:{title:'Шорты',length:.18,y:.55},skirt:{title:'Юбка',length:.25,y:.55},shoes:{title:'Обувь',length:.115,y:.885},hat:{title:'Шапка',length:.15,y:-.015},accessory:{title:'Аксессуар'},set:{title:'Комплект — нужна отдельная примерка'}};
  const myDollTypes=['dress','robe','set','accessory','accessory','accessory','accessory','hat','shoes','top','shoes','pants','shoes','shorts','shorts','skirt','pants','accessory','top','accessory','accessory','dress','accessory','accessory','skirt','pants','dress','robe','top','shorts','accessory','dress','shoes','shoes','top','skirt','shoes','top','pants','pants','top','shoes'];
  function garmentKind(p){if(p.fit?.kind&&garmentTypes[p.fit.kind])return p.fit.kind;const m=/^mydoll_(\d{3})$/.exec(p.name);if(m&&bookInfo?.id==='my-doll')return myDollTypes[Number(m[1])-1]||'accessory';if(/niz|pants|jeans/i.test(p.name))return 'pants';if(/obuv|shoe/i.test(p.name))return 'shoes';if(/verh|top/i.test(p.name))return 'top';return 'accessory';}
  function resizeGarment(p,w,h){const k=w/p.wmm;if(!Number.isFinite(k)||k<=0||Math.abs(k-1)<.000001)return false;p.wmm=w;p.hmm=h;for(const kind of ['paper','film'])p[kind]=p[kind].map(poly=>poly.map(([x,y])=>[x*k,y*k]));return true;}
  function fitGarment(p,kind,percent=100){const rule=garmentTypes[kind];p.fit={...(p.fit||{}),version:1,kind,percent,baseW:p.fit?.baseW||p.wmm,baseH:p.fit?.baseH||p.hmm};if(!rule.length)return resizeGarment(p,p.fit.baseW,p.fit.baseH);const target=(Number(document.getElementById('dollMM').value)||160)*rule.length*percent/100;const aspect=p.wmm/p.hmm;const changed=resizeGarment(p,target*aspect,target);p.fit.dollMM=Number(document.getElementById('dollMM').value)||160;return changed;}
  function saveFitChanges(){bookLayout=null;lastSheets=null;rehearsal.offsets=new WeakMap();renderPieceList();drawDock();queueProjectSave();}
  function ensureGarmentFit(){let changed=false,tagged=false;for(const p of rehearsalItems()){if(!p.fit){const kind=garmentKind(p);if(bookInfo?.id==='my-doll'&&/^mydoll_\d{3}$/.test(p.name)){changed=fitGarment(p,kind)||changed;tagged=true;}}}if(changed)saveFitChanges();else if(tagged)queueProjectSave();}
  function garmentPosition(p,doll,origin){const kind=garmentKind(p),rule=garmentTypes[kind];if(!rule.length)return null;const delta=p.fit?.offset||{x:0,y:0};return {x:100-p.wmm/2+delta.x,y:(kind==='shoes'?origin.y+doll.hmm-p.hmm:origin.y+doll.hmm*rule.y)+delta.y};}
  function updateFitControls(item){const kind=item?garmentKind(item):'accessory',rule=garmentTypes[kind];document.getElementById('garmentType').value=kind;document.getElementById('garmentScale').value=item?.fit?.percent||100;document.getElementById('garmentPercent').textContent=(item?.fit?.percent||100)+'%';document.getElementById('garmentScale').disabled=!item||!rule.length;document.getElementById('garmentSize').textContent=item?rule.title+' · '+item.wmm.toFixed(1)+' × '+item.hmm.toFixed(1)+' мм · '+Math.round(item.print.height/(item.hmm/25.4))+' dpi исходника':'';}
  document.getElementById('garmentType').onchange=e=>{const p=rehearsalItems()[rehearsal.item];if(!p)return;fitGarment(p,e.target.value);if(p.fit)delete p.fit.offset;saveFitChanges();void renderRehearsal();};
