  // Doll height scales everything already on the sheet, so the clothes keep fitting the doll.
  {const dollInput=document.getElementById('dollMM');let dollPrev=Number(dollInput.value)||160;
   dollInput.addEventListener('focus',()=>{dollPrev=Number(dollInput.value)||160;});
   dollInput.addEventListener('change',()=>{
    const next=Number(dollInput.value);
    if(!Number.isFinite(next)||next<60||next>400){dollInput.value=dollPrev;showToast('Высота куклы — от 60 до 400 мм.');return;}
    if(!canEditBook()){dollInput.value=dollPrev;return;}
    const k=next/dollPrev;dollPrev=next;if(Math.abs(k-1)<.0001||!sheetPieces.length)return;
    for(const p of sheetPieces){resizeGarment(p,p.wmm*k,p.hmm*k);if(p.fit){if(p.fit.baseW)p.fit.baseW*=k;if(p.fit.baseH)p.fit.baseH*=k;if(p.fit.dollMM)p.fit.dollMM=next;if(p.fit.offset)p.fit.offset={x:p.fit.offset.x*k,y:p.fit.offset.y*k};}}
    saveFitChanges();showToast('Кукла и вещи пересчитаны под высоту '+next+' мм.');
   });}

  // Rehearsal uses garment dimensions shared by print and cut exports.
  const rehearsal={item:0,page:0,offsets:new WeakMap(),images:new Map(),turn:0,pages:[]};
  function rehearsalItems(){return sheetPieces.filter(p=>p.role!=='doll');}
  // A background is either a JPG kept next to the book (factory files) or a PNG in the picture store (cloud, cached on this device like every other picture).
  function rehearsalImage(file){const hash=file.image?file.image.slice(4):null,key=hash?file.image:file.preview||productionURL(file,true);if(!rehearsal.images.has(key)){const im=new Image();const fail=()=>{rehearsal.images.delete(key);return Error('Не загрузился фон. Открой вкладку «Печать» заново.');};const promise=new Promise((ok,no)=>{im.onload=()=>ok(im);im.onerror=()=>no(fail());(hash?fetchImage(hash).then(b=>URL.createObjectURL(b)):Promise.resolve(key)).then(u=>{im.src=u;},()=>no(fail()));});rehearsal.images.set(key,promise);}return rehearsal.images.get(key);}
  function rehearsalPack(items){
    const pages=[[]];let grid=new Uint8Array(48*46);
    for(const p of items){const w=Math.ceil(p.wmm/4)+1,h=Math.ceil(p.hmm/4)+1;let found=null;
      if(w>48||h>46){pages.push([{p,x:210,y:10,oversize:true}]);grid=new Uint8Array(48*46);pages.push([]);continue;}
      for(let pageTry=0;pageTry<2&&!found;pageTry++){
        for(let y=0;y+h<=46&&!found;y++)for(let x=0;x+w<=48&&!found;x++){let free=true;for(let yy=y;yy<y+h&&free;yy++)for(let xx=x;xx<x+w;xx++)if(grid[yy*48+xx]){free=false;break;}if(free){found={p,x:204+x*4,y:8+y*4};for(let yy=y;yy<y+h;yy++)for(let xx=x;xx<x+w;xx++)grid[yy*48+xx]=1;}}
        if(!found){pages.push([]);grid=new Uint8Array(48*46);}
      }
      if(found)pages[pages.length-1].push(found);
    }return pages.filter(p=>p.length).length?pages.filter(p=>p.length):[[]];
  }
  async function renderRehearsal(){
    const noFit=true; // fitting lives in the wardrobe now: print only shows the book preview
    if(bookInfo?.id!=='cat-cafe')ensureGarmentFit();const token=++rehearsal.turn,items=rehearsalItems(),doll=sheetPieces.find(p=>p.role==='doll');
    const status=document.getElementById('rehearsalStatus'),canvas=document.getElementById('rehearsalCanvas'),ctx=canvas.getContext('2d');
    status.textContent='Загружаю просмотр…';canvas.setAttribute('aria-busy','true');
    try{
      rehearsal.item=Math.max(0,Math.min(rehearsal.item,items.length-1));rehearsal.pages=rehearsalPack(items);const factory=bookProduction?.files?.filter(f=>f.key.startsWith('spread'))||[],backgrounds=bookSpreads(chosenBook);
      const total=Math.max(rehearsal.pages.length,backgrounds.length,1);rehearsal.page=(rehearsal.page+total)%total;
      let bg=null;if(backgrounds.length)bg=await rehearsalImage(backgrounds[rehearsal.page%backgrounds.length]);if(token!==rehearsal.turn)return;
      ctx.clearRect(0,0,1200,609);ctx.fillStyle='#f9f5ef';ctx.fillRect(0,0,1200,609);if(bg)ctx.drawImage(bg,0,0,1200,609);ctx.save();ctx.scale(3,3);
      ctx.strokeStyle='#b6a3b0';ctx.setLineDash([2,2]);ctx.beginPath();ctx.moveTo(200,0);ctx.lineTo(200,203);ctx.stroke();ctx.setLineDash([]);
      let origin=null;
      if(doll){origin={x:100-doll.wmm/2,y:195-doll.hmm};ctx.drawImage(doll.print,origin.x,origin.y,doll.wmm,doll.hmm);}
      const item=items[rehearsal.item];if(!noFit)updateFitControls(item);
      if(item&&doll&&!noFit){let pos=rehearsal.offsets.get(item)||garmentPosition(item,doll,origin);if(pos){rehearsal.offsets.set(item,pos);ctx.drawImage(item.print,pos.x,pos.y,item.wmm,item.hmm);}}
      for(const placed of rehearsal.pages[rehearsal.page]||[]){const p=placed.p;ctx.drawImage(p.print,placed.x,placed.y,p.wmm,p.hmm);if(p===item){ctx.strokeStyle='#a31576';ctx.lineWidth=.7;ctx.strokeRect(placed.x-1,placed.y-1,p.wmm+2,p.hmm+2);}}
      ctx.restore();document.getElementById('rehearsalPage').textContent=(rehearsal.page+1)+' / '+total;
      document.getElementById('rehearsalItem').textContent=item?`${rehearsal.item+1} / ${items.length} · ${item.name}`:'На листах пока нет вещей';document.getElementById('garmentType').closest('.notice').hidden=!item||noFit;
      status.textContent=noFit?(doll?'Так будет выглядеть книга: куколка в комнате, рядом листы с вещами.':'Сначала добавь готовую куклу на лист.'):!doll?'Сначала добавь готовую куклу на лист. Вещи уже видны справа.':!items.length?'Добавь одежду — здесь появится примерка.':'Выбирай вещи в карусели. Их можно перемещать на кукле и уточнять размер.';
      for(const el of document.querySelectorAll('#bookRehearsal h4, #bookRehearsal details, #rehearsalStrip, #rehearsalReset'))el.hidden=noFit;document.getElementById('rehearsalPrevItem').closest('.row').hidden=noFit;document.querySelector('#bookRehearsal .card-heading .tag').textContent=noFit?'ПРОСМОТР':'ПРОСМОТР И ПРИМЕРКА';
      document.getElementById('rehearsalPrevItem').disabled=document.getElementById('rehearsalNextItem').disabled=!items.length;
      const strip=document.getElementById('rehearsalStrip');strip.replaceChildren();items.forEach((p,i)=>{const b=document.createElement('button');b.type='button';b.setAttribute('aria-label','Примерить '+p.name);b.setAttribute('aria-pressed',String(i===rehearsal.item));const c=document.createElement('canvas');c.width=c.height=64;const k=Math.min(60/p.print.width,60/p.print.height);c.getContext('2d').drawImage(p.print,(64-p.print.width*k)/2,(64-p.print.height*k)/2,p.print.width*k,p.print.height*k);b.append(c);b.onclick=()=>{rehearsal.item=i;void renderRehearsal();};strip.append(b);});
    }catch(e){if(token===rehearsal.turn)status.textContent=e.message;}finally{if(token===rehearsal.turn)canvas.setAttribute('aria-busy','false');}
  }
  for(const [id,delta] of [['rehearsalPrevItem',-1],['rehearsalNextItem',1]])document.getElementById(id).onclick=()=>{const n=rehearsalItems().length;if(n){rehearsal.item=(rehearsal.item+delta+n)%n;void renderRehearsal();}};
  for(const [id,delta] of [['rehearsalPrev',-1],['rehearsalNext',1]])document.getElementById(id).onclick=()=>{rehearsal.page+=delta;void renderRehearsal();};
