  document.getElementById('rehearsalZoom').onclick=e=>{const on=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',String(on));e.currentTarget.textContent=on?'Показать целиком':'Увеличить просмотр';const c=document.getElementById('rehearsalCanvas');c.style.width=on?'1000px':'100%';c.style.maxWidth=on?'none':'100%';};
