  function setStage(stage, scroll = true, startProject = false) {
    stage = String(stage);if(!['1','2','3','4','5'].includes(stage))return;if(!workingProject&&['2','3'].includes(stage)&&account&&startProject){workingProject=true;cloudTitle.value='Проект '+new Date().toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});syncBookUI();queueProjectSave();}if(!workingProject&&stage!=='1'){stage='1';showToast('Сначала создай куклу, добавь одежду или выбери книгу');}
    // No child on the podium yet: the wardrobe has nobody to dress, so the doll step (photo rules + upload) comes first.
    if(stage==='3'&&!projectRestoring&&!cloudBusy&&!projectBusy&&!gResult&&!sheetPieces.some(isDollPiece)&&!fitDoll())stage='2';
    document.querySelectorAll('[data-step]').forEach(el=>el.hidden = el.dataset.step !== stage);
    document.querySelectorAll('[data-stage]').forEach(el=>{if(el.dataset.stage===stage)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});
    try { sessionStorage.setItem('memorybox-stage-v2',stage); } catch (_) {}
    if(stage==='4'){syncCutModeUI();if(!cutMode)askCutMode();drawDock();void renderRehearsal();}if(stage==='3'&&account)void renderFitting();if(stage==='5')renderBookChoices();renderSheetRail();rememberActive(stage);
    if(scroll)document.querySelector('.step-nav').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});
  }
