  // Waiting screen: phrases follow an expected ~60 s run; the bar eases towards 95 % and never claims done.
  const MAGIC_PHRASES=[[0,'Изучаем черты лица…'],[10,'Подбираем причёску и цвет волос…'],[22,'Переносим улыбку на куколку…'],[34,'Добавляем немного волшебства ✨'],[46,'Осталось совсем чуть‑чуть — куколка почти готова…'],[75,'Ещё мгновение — наводим последний блеск…']];
  let magicTimer=null;
  function setMagic(on){
    clearInterval(magicTimer);magicTimer=null;if(!on)return;
    const t0=Date.now(),phrase=document.getElementById('genPhrase'),bar=document.getElementById('genBar'),eta=document.getElementById('genEta');
    const tick=()=>{const s=(Date.now()-t0)/1000;let text=MAGIC_PHRASES[0][1];for(const [at,p] of MAGIC_PHRASES)if(s>=at)text=p;
      if(phrase.textContent!==text){phrase.textContent=text;phrase.classList.remove('swap');void phrase.offsetWidth;phrase.classList.add('swap');}
      bar.style.width=(95*(1-Math.exp(-s/28))).toFixed(1)+'%';eta.textContent=s<50?'Обычно около минуты':'Иногда бывает очередь — ещё немного';};
    tick();magicTimer=setInterval(tick,500);
  }
  function setGenerationBusy(busy) {
