    document.getElementById('generationOverlay').hidden=!busy;document.getElementById('generationSpinner').hidden=!busy;
    document.getElementById('gRun').querySelector('.button-spinner').hidden=!busy;
    document.getElementById('gRun').setAttribute('aria-busy',String(busy));
