  function refreshWorkspaceGuide(){
    const title=document.getElementById('contextTitle'),meta=document.getElementById('contextState'),next=document.getElementById('contextNext'),action=document.getElementById('contextAction');
    const ready=!!gResult||sheetPieces.some(isDollPiece),items=sheetPieces.filter(p=>!isDollPiece(p)).length,hasBook=!!bookInfo;
    document.querySelector('.work-context').hidden=!workingProject;
    const name=cloudTitle.value||'';title.textContent=workingProject&&name&&!/^(Кукла и одежда|Проект |Заказ |Новая книга)/.test(name)?'← '+name:'← Мой проект';title.title=name;
    meta.replaceChildren();for(const state of [{text:'Кукла',checked:ready},{text:items?'Гардероб · '+items:'Гардероб',checked:items>0}]){const label=document.createElement('label');label.className='readiness-item';const check=document.createElement('input');check.type='checkbox';check.checked=state.checked;check.disabled=true;check.setAttribute('aria-label',state.text+(state.checked?' — готово':' — ещё не готово'));const text=document.createElement('span');text.textContent=state.text;label.append(check,text);meta.append(label);}
    const save=document.getElementById('contextSave');save.textContent=cloudBusy?'Сохраняю…':cloudBlocked?'Конфликт версий':cloudDirty?'Есть изменения':cloudProject?'Сохранено':'Черновик';save.dataset.phase=cloudBlocked?'error':cloudBusy?'busy':cloudDirty?'dirty':cloudProject?'saved':'idle';save.title=cloudStatus.textContent;
    let target='2',label='Создать куклу',hint='Кукла → одежда → примерка и печать. Собери свою персональную книгу.';
    if(workingProject){if(!ready){target='2';label='Перейти к кукле';hint=items?'Одежда уже есть. Добавь ребёнка — вещи останутся в проекте.':'Создай куклу по фото. Её можно использовать в книгах с тем же эталоном.';}else if(!items){target='3';label='Добавить одежду';hint='Кукла готова. Добавь вещи для своей книги.';}else if(!chosenBook){target='5';label='Выбрать книгу';hint='Кукла и одежда готовы. Выбери книгу — её фоны пойдут в печать вместе с листами.';}else{target='4';label='Проверить и скачать';hint='Кукла, одежда и книга готовы. Проверь развороты и скачай файлы для печати.';}}
    next.textContent=hint;action.dataset.next=target;action.textContent=label+' →';const stage=document.querySelector('.step-nav [aria-current]')?.dataset.stage||'1';action.hidden=stage===target;const home=document.getElementById('homeNextAction');home.dataset.next=target;home.textContent=(target==='2'?'1. Создать куклу':target==='3'?'2. Подготовить одежду':target==='5'?'3. Выбрать книгу':'4. Проверить и скачать')+' →';document.getElementById('accountProjectState').textContent=cloudStatus.textContent;
    document.querySelectorAll('.step-nav [data-stage]').forEach(el=>el.dataset.complete=String(el.dataset.stage==='1'?workingProject:el.dataset.stage==='2'?ready:el.dataset.stage==='3'?items>0:el.dataset.stage==='5'?!!chosenBook:false));
    const dollNext=document.getElementById('dollNextAction');dollNext.dataset.next=ready&&items?(chosenBook?'4':'5'):'3';dollNext.textContent=ready&&items?'Проверить свою книгу →':'Дальше: подготовить одежду →';
    const readyLink=document.querySelector('#wardrobeReady [data-next="2"]');if(readyLink)readyLink.textContent=ready?'Посмотреть готовую куклу':'Добавить ребёнка';
    for(const id of ['appToast','cloudStatus','gStatus','projectStatus']){const el=document.getElementById(id);el.classList.toggle('is-error',/не удалось|ошибк|не хватает|закончилось|конфликт|не сохранён|не найден/i.test(el.textContent));}
  }
  let guideFrame=null;function scheduleWorkspaceGuide(){if(guideFrame!==null)return;guideFrame=requestAnimationFrame(()=>{guideFrame=null;refreshWorkspaceGuide();});}
  for(const id of ['cloudStatus','gStatus','projectStatus','appToast','dockCount'])new MutationObserver(scheduleWorkspaceGuide).observe(document.getElementById(id),{childList:true,subtree:true,characterData:true});
  new MutationObserver(scheduleWorkspaceGuide).observe(G.out,{attributes:true,attributeFilter:['src','hidden']});
  new MutationObserver(scheduleWorkspaceGuide).observe(document.getElementById('cloudSave'),{attributes:true,attributeFilter:['disabled','aria-busy']});
  cloudTitle.addEventListener('input',scheduleWorkspaceGuide);
  for(const id of ['contextAction','dollNextAction'])document.getElementById(id).addEventListener('click',e=>{if(e.currentTarget.dataset.next==='1')requestAnimationFrame(()=>{document.getElementById('readyBookOptions').open=true;document.getElementById('bookCatalog').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});});});
  document.querySelectorAll('[data-stage],[data-next]').forEach(el=>el.addEventListener('click',scheduleWorkspaceGuide));
  refreshWorkspaceGuide();

  new MutationObserver(updateResultUI).observe(G.out,{attributes:true,attributeFilter:['hidden','src']});
  function resetChildPreview() {
    if(childPreviewURL){URL.revokeObjectURL(childPreviewURL);childPreviewURL=null;}
    document.getElementById('childPreview').hidden=true;document.getElementById('childPreview').removeAttribute('src');
    document.getElementById('childPhotoEmpty').hidden=false;document.getElementById('photoChange').hidden=true;document.getElementById('childFilename').textContent='Фотография пока не выбрана';
  }
  G.photo.addEventListener('change',async()=>{
    resetChildPreview();const file=G.photo.files[0];if(!file)return;const preview=document.getElementById('childPreview');
    const url=URL.createObjectURL(file);childPreviewURL=url;document.getElementById('childFilename').textContent='Открываю фотографию…';
    try{const image=new Image();image.src=url;await image.decode();if(childPreviewURL!==url)return;preview.src=url;preview.hidden=false;document.getElementById('childPhotoEmpty').hidden=true;document.getElementById('photoChange').hidden=false;document.getElementById('childFilename').textContent=file.name+' · '+(file.size/1048576).toFixed(1)+' МБ';G.status.textContent='Фото выбрано. Нажми «Создать куклу», чтобы начать обработку.';updateResultUI();queueProjectSave();}
    catch(_){if(childPreviewURL!==url)return;gPhotoFile=null;gInfoRender();resetChildPreview();G.status.textContent='Не удалось открыть фото. Выбери JPG, PNG или WebP.';}
  });
  const photoDrop=document.getElementById('photoDrop');
  ['dragenter','dragover'].forEach(event=>photoDrop.addEventListener(event,e=>{e.preventDefault();if(!gBusy)photoDrop.classList.add('over');}));
  ['dragleave','drop'].forEach(event=>photoDrop.addEventListener(event,e=>{e.preventDefault();photoDrop.classList.remove('over');}));
  photoDrop.addEventListener('drop',e=>{if(gBusy)return;const files=[...e.dataTransfer.files].filter(f=>f.type.startsWith('image/'));if(!files.length)return;const transfer=new DataTransfer();transfer.items.add(files[0]);G.photo.files=transfer.files;G.photo.dispatchEvent(new Event('change',{bubbles:true}));});
  for(const [id,input] of [['photoDrop','gPhoto'],['drop','file'],['refDrop','refFile']]){
    const label=document.getElementById(id);label.tabIndex=0;label.setAttribute('role','button');label.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();document.getElementById(input).click();}});
  }
  function updateClothesUI(){const empty=srcImg.hidden&&outImg.hidden;document.getElementById('clothesPreviews').hidden=empty;const cmp=document.getElementById('clothesCompare');if(cmp.hidden&&!empty)cmp.open=true;cmp.hidden=empty;}
  new MutationObserver(updateClothesUI).observe(srcImg,{attributes:true,attributeFilter:['hidden','src']});
  document.getElementById('downloadMannequin').addEventListener('click',()=>{const a=document.createElement('a');a.href=REF_DEFAULT;a.download='memorybox_shablon-kukly_1360x2919.png';document.body.append(a);a.click();a.remove();});
  document.getElementById('printBackup').addEventListener('click',()=>document.getElementById('saveProject').click());
  // Automatic check of a finished doll against the template: the head swap must leave the body untouched.
  // Compared from mid-torso down, because loose hair of any length may cover the shoulders and the gaps
  // beside the arms; a 2-px tolerance (≈8 px at full size) absorbs anti-aliasing and resampling.
  function checkDollAgainstTemplate(){
    const el=document.getElementById('dollCheck');
    if(!gResult||!gTemplate||G.out.hidden){el.hidden=true;return;}
    const W=340,H=Math.round(W*gTemplate.height/gTemplate.width),top=Math.round(H*.45),R=2;
    const body=src=>{const c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d',{willReadFrequently:true});x.fillStyle='#fff';x.fillRect(0,0,W,H);x.drawImage(src,0,0,W,H);
      const d=x.getImageData(0,0,W,H).data,m=new Uint8Array(W*H);let x0=W,x1=-1,y1=-1;
      for(let y=top;y<H;y++)for(let xx=0;xx<W;xx++){const i=(y*W+xx)*4;if(d[i]<235||d[i+1]<235||d[i+2]<235){m[y*W+xx]=1;if(xx<x0)x0=xx;if(xx>x1)x1=xx;if(y>y1)y1=y;}}
      return {m,w:x1-x0+1,h:y1-top+1};};
    const near=(m,i)=>{const y=Math.floor(i/W),x=i%W;for(let dy=-R;dy<=R;dy++)for(let dx=-R;dx<=R;dx++){const yy=y+dy,xx=x+dx;if(yy>=0&&yy<H&&xx>=0&&xx<W&&m[yy*W+xx])return true;}return false;};
    const a=body(gResult),b=body(gTemplate);let both=0,any=0;
    for(let i=top*W;i<a.m.length;i++){if(!a.m[i]&&!b.m[i])continue;any++;if((!a.m[i]||near(b.m,i))&&(!b.m[i]||near(a.m,i)))both++;}
    // The silhouette cannot see a second head drawn inside the torso, so also compare the chest of the tank top:
    // a clean result differs there in under 1% of pixels, a duplicated head in about a third.
    const pixels=src=>{const c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d',{willReadFrequently:true});x.fillStyle='#fff';x.fillRect(0,0,W,H);x.drawImage(src,0,0,W,H);return x.getImageData(0,0,W,H).data;};
    const pr=pixels(gResult),pt=pixels(gTemplate);let chestAll=0,chestBad=0;
    for(let y=Math.round(H*.30);y<H*.48;y++)for(let x=Math.round(W*.38);x<W*.62;x++){const i=(y*W+x)*4;chestAll++;if(Math.abs(pr[i]+pr[i+1]+pr[i+2]-pt[i]-pt[i+1]-pt[i+2])/3>60)chestBad++;}
    const chestClean=chestBad/chestAll<=.12;
    const match=any?Math.round(both/any*100):0,prop=Math.max(0,Math.round(100-(Math.abs(a.w-b.w)/b.w+Math.abs(a.h-b.h)/b.h)/2*100));
    const ok=match>=95&&prop>=97&&chestClean;
    el.dataset.state=ok?'ok':'warn';el.hidden=false;
    const head=document.createElement('b'),note=document.createElement('span');
    head.textContent=ok?'✨ Куколка для новой книги готова!':!chestClean?'Куколка получилась с ошибкой':'Куколка готова, но тело немного изменилось';
    note.textContent=ok?'Изменилась только голова: тело совпадает с эталоном на '+match+'%, пропорции — '+prop+'%.':!chestClean?'На теле появилось лишнее изображение — например, вторая голова. Нажми «Другой вариант».':'Тело совпадает с эталоном на '+match+'%, пропорции — '+prop+'%. Лучше нажать «Другой вариант».';
    el.replaceChildren(head,note);
  }
  new MutationObserver(()=>requestAnimationFrame(checkDollAgainstTemplate)).observe(G.out,{attributes:true,attributeFilter:['src','hidden']});
  // The doll is placed automatically; the add button is only a fallback when it is missing from the sheet.
  function updateSheetUI(){G.add.hidden=!personalization?.pending&&sheetPieces.some(isDollPiece);const count=sheetPieces.length;document.getElementById('sheetBadge').textContent=count;document.getElementById('sheetBadge').hidden=!count;document.getElementById('pieceCountLabel').textContent=count+' ДЕТ.';document.getElementById('pieceListEmpty').hidden=Boolean(count);document.getElementById('sheetEmpty').hidden=Boolean(count);}
  function updateCloudUI(){const text=cloudStatus.textContent;const failed=/ошиб|не удалось|не найден|конфликт|изменён на другом|нет соединения|закончилось|Failed to fetch|Load failed|Сервер не ответил|Страница устарела/i.test(text);const saving=/Сохраня|Есть изменения/.test(text)&&!failed;document.getElementById('cloudSaveDot').className=failed?'error':saving?'busy':cloudProject?'saved':'';document.getElementById('cloudShortStatus').textContent=failed?'Нужна проверка':saving?'Сохраняем…':cloudProject?'Сохранено':'Новый проект';document.getElementById('projectDialogStatus').textContent=failed?text:'';document.getElementById('projectDialogStatus').classList.toggle('is-error',failed);cloudStatus.classList.toggle('is-error',failed);}
  new MutationObserver(updateCloudUI).observe(cloudStatus,{childList:true,characterData:true,subtree:true});
  // dockZip delegates to downloadZip, so one guard covers both buttons.
  document.getElementById('downloadZip').addEventListener('click',e=>{if(sheetPieces.some(isDollPiece))return;const stop=()=>{e.preventDefault();e.stopImmediatePropagation();};if(gResult){try{installGeneratedDoll();queueProjectSave();stop();showToast('Кукла добавлена на лист. Проверь раскладку и скачай архив ещё раз.');return;}catch(err){}}if(!confirm('На листе нет куклы — в архив попадёт только одежда. Скачать без куклы?'))stop();},true);
  document.getElementById('clearPieces').addEventListener('click',e=>{if(sheetPieces.length&&!confirm('Убрать все детали с текущего листа? Сохранённые версии проекта останутся в истории.')){e.preventDefault();e.stopImmediatePropagation();}},true);
  updateResultUI();updateSheetUI();updateClothesUI();
  // Project actions on the home card; the originals live in the header and the account dialog.
  document.getElementById('homeProjects').addEventListener('click',()=>document.getElementById('showProjects').click());
  document.getElementById('homeNew').addEventListener('click',()=>document.getElementById('cloudNew').click());

  drawDock();
  // Phone fitting room: tapping a category opens the vertical picker on the right; picking an item (or tapping the doll) closes it.
  (function(){
    const room=document.getElementById('fittingRoom'),tabs=document.getElementById('fitTabs'),grid=document.getElementById('fitGrid'),col=room&&room.querySelector('.fit-doll-col'),closeBtn=document.getElementById('fitRailClose');
    return; // phone wardrobe v3: the item strip is always visible, nothing to open or close
    if(!room||!tabs||!grid||!col)return;
    const phone=window.matchMedia('(max-width:760px)');
    const isOpen=()=>room.dataset.rail==='open';
    const open=()=>{room.dataset.rail='open';setTimeout(()=>{grid.scrollTop=0;},30);};
    const close=()=>{delete room.dataset.rail;};
    tabs.addEventListener('click',e=>{
      if(!phone.matches)return;
      const list=[...tabs.children],clicked=list.findIndex(b=>b.contains(e.target));if(clicked<0)return;
      const current=list.findIndex(b=>b.getAttribute('aria-pressed')==='true');
      if(isOpen()&&clicked===current)close();else open();
    },true);
    grid.addEventListener('click',e=>{if(phone.matches&&e.target.closest('.fit-tile'))setTimeout(close,220);},true);
    col.addEventListener('click',e=>{if(phone.matches&&isOpen()&&!e.target.closest('.fit-wear,.fit-tools,.fit-chip,.fit-tabs,.fit-grid,.fit-actions'))close();});
    if(closeBtn)closeBtn.addEventListener('click',close);
    document.addEventListener('keydown',e=>{if(e.key==='Escape'&&isOpen())close();});
    phone.addEventListener?.('change',()=>close());
  })();
  // No «save image» menu on long press or right click for garments and previews: the originals are only used for the print files.
  document.addEventListener('contextmenu',e=>{const t=e.target;if(t&&t.closest&&t.closest('.workshop')&&t.matches('img,canvas,.fit-wear,.fit-tile,.fit-chip'))e.preventDefault();});
  document.addEventListener('dragstart',e=>{const t=e.target;if(t&&t.closest&&t.closest('.workshop')&&t.matches('img,canvas'))e.preventDefault();});
  // «Ничего не подошло?»: the own-outfit workflow (template, ChatGPT prompt, upload) opens as its own full-screen page.
  (function(){
    const own=document.getElementById('ownClothes'),openBtn=document.getElementById('ownOpen'),backBtn=document.getElementById('ownBack');
    if(!own||!openBtn)return;
    let lastY=0;const home=document.createComment('own-outfit-page');own.before(home);
    const isOpen=()=>own.classList.contains('is-page');
    // The page is moved to <body> while open, so no animated or transformed parent can shrink its full-screen box.
    const open=()=>{if(isOpen())return;lastY=window.scrollY;document.body.append(own);own.open=true;own.classList.add('is-page');document.documentElement.classList.add('own-open');own.scrollTop=0;try{history.pushState({own:1},'');}catch(_){}};
    const close=viaHistory=>{if(!isOpen())return;own.classList.remove('is-page');home.parentNode.insertBefore(own,home.nextSibling);document.documentElement.classList.remove('own-open');window.scrollTo(0,lastY);if(!viaHistory&&history.state&&history.state.own){try{history.back();}catch(_){}}};
    openBtn.addEventListener('click',open);
    if(backBtn)backBtn.addEventListener('click',()=>close(false));
    window.addEventListener('popstate',()=>close(true));
    document.addEventListener('keydown',e=>{if(e.key==='Escape'&&isOpen()&&!document.querySelector('dialog[open]'))close(false);});
  })();
